	/** What lies on the Chambers of Xeric floor, all piles together. */
	private Map<Integer, Long> raidLeft()
	{
		Map<Integer, Long> left = new LinkedHashMap<>();
		if (nomad != null)
		{
			for (Store s : nomad.stores(Kind.FLOOR))
			{
				if (s.world == Nomad.RAID)
				{
					s.items.forEach((item, qty) -> left.merge(item, qty, Long::sum));
				}
			}
		}
		return left;
	}

	/** "You left 6 things (1.2M) on the floor" above the raid's ways out. */
	private String raidLabel()
	{
		Map<Integer, Long> left = raidLeft();
		int n = left.size();
		return "You left " + n + (n == 1 ? " thing" : " things") + " (" + Format.coins(Items.worth(left, this::price)) + ") on the floor";
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		raidFloor.spawned(event.getGameObject());
		if (Death.holderObject(event.getGameObject().getId()))
		{
			holders.add(event.getGameObject());
		}
		int[] capes = nomad == null ? null : CapeHanger.holds(event.getGameObject().getId());
		if (capes == null)
		{
			return;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (int id : capes)
		{
			items.put(id, 1L);
		}
		Store s = nomad.store(CapeHanger.KEY);
		if (items.isEmpty())
		{
			if (s != null)
			{
				nomad.remove(CapeHanger.KEY);
				changed();
			}
			return;
		}
		if (s == null)
		{
			s = new Store(CapeHanger.KEY, Kind.KEPT, CapeHanger.NAME);
			nomad.put(s);
		}
		if (!items.equals(s.items))
		{
			s.fill(items, System.currentTimeMillis());
			changed();
		}
	}

	/** Reads the compost bin nearby, if the game is telling us about one here. */
	private void readBin()
	{
		CompostBins.Bin bin = CompostBins.near(lastRegion);
		if (bin == null || nomad == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		Map<Integer, Long> items = CompostBins.read(bin.big, client.getVarbitValue(bin.varbit));
		Store s = nomad.store(bin.key);
		if (items.isEmpty())
		{
			if (s != null)
			{
				nomad.remove(bin.key);
				changed();
			}
			return;
		}
		if (s == null)
		{
			s = new Store(bin.key, Kind.KEPT, bin.name);
			nomad.put(s);
		}
		if (!items.equals(s.items))
		{
			s.fill(items, now);
			changed();
		}
	}

	/** Says once, on the way in, what dying in the Wilderness would cost. */
	private void warnWilderness()
	{
		List<String> lose = new ArrayList<>();
		Store bank = nomad.deathbank();
		if (bank != null)
		{
			lose.add("your deathbank at " + bank.name + (bank.exact ? " (" + Format.coins(Items.worth(bank.items, this::price)) + ")" : ""));
		}
		com.codex.nomad.core.Kept k = com.codex.nomad.core.Kept.of(nomad.loose(), this::price, keep());
		long drop = k.droppedWorth + Items.worth(nomad.inside(), this::price);
		if (drop > 0)
		{
			lose.add(Format.coins(drop) + " of what you carry");
		}
		if (!lose.isEmpty())
		{
			say("Wilderness: dying here costs " + String.join(" and ", lose) + "." + needless(), true);
		}
	}

	/**
	 * " You carry 3.1M that Vorkath does not need: Dragon pickaxe, Abyssal whip.": what the active
	 * packing list leaves out, risked for nothing. Empty with no list, or under 10k.
	 */
	private String needless()
	{
		Trip t = nomad.activeTrip();
		Fetch f = t == null ? null : Views.plan(nomad, t, lookup(), here());
		if (f == null || f.extra.isEmpty())
		{
			return "";
		}
		List<Map.Entry<Integer, Long>> extra = new ArrayList<>(f.extra.entrySet());
		extra.sort((a, b) -> Long.compare(price(b.getKey()) * b.getValue(), price(a.getKey()) * a.getValue()));
		long worth = Items.worth(f.extra, this::price);
		if (worth < 10_000)
		{
			return "";
		}
		List<String> names = new ArrayList<>();
		for (int i = 0; i < Math.min(3, extra.size()); i++)
		{
			names.add(name(itemManager.canonicalize(extra.get(i).getKey())));
		}
		return " You carry " + Format.coins(worth) + " that " + t.name + " does not need: " + String.join(", ", names)
			+ (extra.size() > 3 ? " and more" : "") + ".";
	}

	/** Lets dropped items go when their time comes, and warns before. */
	private void watchFloor()
	{
		long now = System.currentTimeMillis();
		dropping.values().removeIf(t -> client.getTickCount() - t > DROP_TICKS);
		for (Map.Entry<Store, Map<Integer, Long>> e : nomad.expire(now).entrySet())
		{
			nomad.lose("Dropped on world " + e.getKey().world + " and vanished", e.getValue(), Items.worth(e.getValue(), this::price), now);
			say("Dropped on world " + e.getKey().world + " and now gone: " + itemsText(e.getValue()) + ".", true);
			changed();
		}
		long warnMs = config.floorWarning() * 1000L;
		if (warnMs <= 0)
		{
			return;
		}
		for (Store s : nomad.stores(Kind.FLOOR))
		{
			for (Map.Entry<Integer, Long> e : s.expires.entrySet())
			{
				long left = e.getValue() - now;
				if (left > 0 && left <= warnMs && warned.add(s.key + ":" + e.getKey() + ":" + e.getValue()))
				{
					say(name(itemManager.canonicalize(e.getKey())) + " on the floor vanishes in " + (left + 999) / 1000 + " seconds"
						+ (s.world != client.getWorld() ? ", on world " + s.world : "") + ".", true);
				}
			}
		}
	}

	private String itemsText(Map<Integer, Long> items)
	{
		List<String> parts = new ArrayList<>();
		items.forEach((id, q) -> parts.add(q > 1 ? q + " x " + name(itemManager.canonicalize(id)) : name(itemManager.canonicalize(id))));
		return parts.size() > 3 ? String.join(", ", parts.subList(0, 3)) + " and " + (parts.size() - 3) + " more" : String.join(", ", parts);
	}

	private void readCarried()
	{
		long now = System.currentTimeMillis();
		nomad.account = client.getVarbitValue(VarbitID.IRONMAN);
		lastInv = contents(client.getItemContainer(InventoryID.INV));
		lastWorn = contents(client.getItemContainer(InventoryID.WORN));
		nomad.carry(Nomad.INVENTORY, lastInv, now);
		nomad.carry(Nomad.WORN, lastWorn, now);
		ItemContainer bag = client.getItemContainer(InventoryID.LOOTING_BAG);
		if (bag != null)
		{
			nomad.carry(Nomad.LOOTING_BAG, contents(bag), now);
		}
		readPouch();
		changed();
	}

	private void readPouch()
	{
		boolean pouch = false;
		for (int id : lastInv.keySet())
		{
			pouch |= POUCHES.contains(id);
		}
		Map<Integer, Long> runes = new HashMap<>();
		if (pouch)
		{
			EnumComposition e = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			for (int i = 0; i < POUCH_RUNES.length; i++)
			{
				int type = client.getVarbitValue(POUCH_RUNES[i]);
				int amount = client.getVarbitValue(POUCH_AMOUNTS[i]);
				int item = type > 0 && e != null ? e.getIntValue(type) : -1;
				if (item > 0 && amount > 0)
				{
					runes.merge(item, (long) amount, Long::sum);
				}
			}
		}
		nomad.carry(Nomad.RUNE_POUCH, runes, System.currentTimeMillis());
	}

	/** Items picked up beside a deathpile come out of it. */
	private void pickUp(Map<Integer, Long> gained)
	{
		Player me = client.getLocalPlayer();
		if (gained.isEmpty() || me == null)
		{
			return;
		}
		WorldPoint at = me.getWorldLocation();
		for (Store pile : nomad.stores(Kind.DEATHPILE))
		{
			if (pile.plane != at.getPlane() || Math.max(Math.abs(pile.x - at.getX()), Math.abs(pile.y - at.getY())) > PILE_REACH)
			{
				continue;
			}
			for (Map.Entry<Integer, Long> e : gained.entrySet())
			{
				long n = pile.take(e.getKey(), e.getValue());
				gained.put(e.getKey(), e.getValue() - n);
			}
			if (pile.isEmpty())
			{
				nomad.remove(pile.key);
				say("Deathpile cleared: you have everything back.");
			}
		}
	}

	// ---- deaths ----

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (nomad == null || event.getActor() != client.getLocalPlayer())
		{
			return;
		}
		Map<Integer, Long> before = new HashMap<>(lastInv);
		Items.add(before, lastWorn);
		Items.add(before, nomad.inside());
		beforeDeath = before;
		WorldPoint at = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
		deathAt = at;
		deathRegion = at == null ? -1 : at.getRegionID();
		deathInstanced = client.isInInstancedRegion();
		deathTick = client.getTickCount();
	}

	/** Once respawned, works out what the death did with everything. */
	private void judgeDeath()
	{
		Player me = client.getLocalPlayer();
		if (beforeDeath == null || me == null)
		{
			return;
		}
		boolean moved = deathAt == null || me.getWorldLocation().distanceTo(deathAt) > 15;
		boolean late = client.getTickCount() - deathTick > DEATH_TICKS;
		if (!moved && !late || client.getBoostedSkillLevel(Skill.HITPOINTS) <= 0)
		{
			return;
		}
		Map<Integer, Long> after = new HashMap<>(lastInv);
		Items.add(after, lastWorn);
		Death d = Death.of(beforeDeath, after, deathRegion, deathInstanced);
		long now = System.currentTimeMillis();
		Store bank = nomad.deathbank();
		if (d.kind == Death.Kind.PILE)
		{
			if (bank != null)
			{
				nomad.remove(Nomad.DEATHBANK);
				nomad.lose("Deathbank at " + bank.name + " wiped by a death", bank.items, Items.worth(bank.items, this::price), now);
				say("That death wiped your deathbank at " + bank.name + ".", true);
			}
			Store pile = nomad.pile(d.lost, deathAt.getX(), deathAt.getY(), deathAt.getPlane(), now);
			WayBack.Way way = wayBack(pile);
			say("Deathpile left: " + Format.coins(Items.worth(pile.items, this::price)) + ", gone in an hour of play."
				+ (way != null ? " Quickest way back: " + way.say() + "." : ""));
		}
		else if (d.kind == Death.Kind.DEATHBANK)
		{
			if (bank != null && !bank.name.equals(d.place))
			{
				nomad.lose("Deathbank at " + bank.name + " wiped by a death", bank.items, Items.worth(bank.items, this::price), now);
				say("Your deathbank at " + bank.name + " was wiped by this death.", true);
			}
			Store s = new Store(Nomad.DEATHBANK, Kind.DEATHBANK, d.place);
			s.items = Items.clean(d.lost);
			s.exact = false;
			s.seen = now;
			s.since = now;
			nomad.put(s);
			say("Deathbank at " + d.place + ": " + Format.coins(Items.worth(s.items, this::price))
				+ ". " + (Death.claim(d.place) != null ? Death.claim(d.place) + ". " : "")
				+ "Any unsafe death before you claim it wipes it.");
		}
		if (d.kind == Death.Kind.PILE || d.kind == Death.Kind.DEATHBANK)
		{
			// Whatever was inside a bag, pouch or sack went with it.
			for (String c : nomad.containers())
			{
				if (!c.equals(Nomad.INVENTORY) && !c.equals(Nomad.WORN))
				{
					nomad.carry(c, new HashMap<>(), now);
				}
			}
			readPouch();
			readAll();
		}
		beforeDeath = null;
		deathTick = -1;
		changed();
	}

	/** The place a retrieval window belongs to, as best known: where the player is or last died. */
	private String place()
	{
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			String lair = Death.lair(me.getWorldLocation().getRegionID());
			if (lair != null)
			{
				return lair;
			}
		}
		return deathAt == null ? "Unknown place" : "near your death";
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (nomad == null || event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		guide.heard(message);
		if (herbSack.heard(message, nomad, System.currentTimeMillis()) | Bags.heard(message, nomad, System.currentTimeMillis())
			| Sayings.heard(message, weapon(), this::itemNamed, nomad, System.currentTimeMillis()))
		{
			changed();
		}
		if (nomad.following)
		{
			observeRoute();
		}
		if (message.startsWith("You have items stored in an item retrieval service."))
		{
			sawRetrieval = true;
			if (nomad.deathbank() == null)
			{
				Store s = new Store(Nomad.DEATHBANK, Kind.DEATHBANK, "Unknown place");
				s.exact = false;
				s.seen = System.currentTimeMillis();
				nomad.put(s);
				changed();
			}
		}
		else if (message.equals("You deposit your items into the STASH unit."))
		{
			stashDeposit = client.getTickCount();
		}
		else if (message.equals("You withdraw your items from the STASH unit."))
		{
			stashWithdraw = client.getTickCount();
		}
	}

	private void settleStash()
	{
		boolean deposit = stashDeposit >= 0 && client.getTickCount() > stashDeposit;
		boolean withdraw = stashWithdraw >= 0 && client.getTickCount() > stashWithdraw;
		if (!deposit && !withdraw)
		{
			return;
		}
		STASHUnit unit = nearestStash();
		if (unit != null)
		{
			String key = "stash:" + unit.name();
			Store s = nomad.store(key);
			long now = System.currentTimeMillis();
			if (withdraw)
			{
				if (s != null)
				{
					s.fill(new HashMap<>(), now);
				}
			}
			if (deposit)
			{
				if (s == null)
				{
					WorldPoint p = unit.getWorldPoints()[0];
					StashBook.Unit u = stash.unit(unit.name());
					s = new Store(key, Kind.STASH, u == null ? Text.titleCase(unit) : u.place).at(p.getX(), p.getY(), p.getPlane());
					nomad.put(s);
				}
				Map<Integer, Long> put = new HashMap<>(removedBefore);
				Items.add(put, removed);
				s.fill(put, now);
			}
			changed();
		}
		stashDeposit = -1;
		stashWithdraw = -1;
	}

	private STASHUnit nearestStash()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		WorldPoint at = me.getWorldLocation();
		STASHUnit best = null;
		int bestD = Integer.MAX_VALUE;
		for (STASHUnit u : STASHUnit.values())
		{
			for (WorldPoint p : u.getWorldPoints())
			{
				int d = p.getPlane() == at.getPlane() ? p.distanceTo2D(at) : Integer.MAX_VALUE;
				if (d < bestD)
				{
					bestD = d;
					best = u;
				}
			}
		}
		return bestD <= STASH_REACH ? best : null;
	}

	// ---- the tick ----

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (nomad == null)
		{
			return;
		}
		long nowMs = System.currentTimeMillis();
		if (lastTickMs > 0)
		{
			nomad.played += Math.min(5_000, Math.max(0, nowMs - lastTickMs));
		}
		lastTickMs = nowMs;
		settleStash();
		if (herbSack.tick(removed, gained, nomad, nowMs))
		{
			changed();
		}
		readShown(nowMs);
		gained.clear();
		removedBefore.clear();
		removedBefore.putAll(removed);
		removed.clear();
		if (deathTick >= 0)
		{
			judgeDeath();
		}
		for (Store gone : nomad.tick())
		{
			nomad.lose("Deathpile ran out of time", gone.items, Items.worth(gone.items, this::price), nowMs);
			say("A deathpile ran out of time: " + Format.coins(Items.worth(gone.items, this::price)) + " is gone.", true);
			changed();
		}
		warnPiles();
		watchFloor();
		if (ticks % 3 == 0)
		{
			findErrandObjects();
		}
		if (client.getTickCount() - hurtTick == 9)
		{
			dirty = true;
		}
		if (raidFloor.tick())
		{
			Map<Integer, Long> lost = nomad.endRaid();
			if (!lost.isEmpty())
			{
				nomad.lose("Left on the Chambers of Xeric floor", lost, Items.worth(lost, this::price), nowMs);
				say("You left the Chambers of Xeric with things on its floor; they are gone: " + itemsText(lost) + ".", true);
				changed();
			}
		}
		watchLair();
		checkLogin();
		if (loginTick >= 0 && client.getTickCount() - loginTick == READ_TICKS)
		{
			readAll();
		}
		observeRoute();
		guideRoute();
		ticks++;
		if (ticks % SAVE_TICKS == 0)
		{
			unsaved = true;
			save();
		}
		if (dirty || ticks % PUBLISH_TICKS == 0 && hasTimers())
		{
			publish();
		}
	}

	private boolean hasTimers()
	{
		return !nomad.stores(Kind.DEATHPILE).isEmpty() || !nomad.stores(Kind.FLOOR).isEmpty();
	}

	private void warnPiles()
	{
		long warnTicks = config.pileWarning() * 100L;
		if (warnTicks <= 0)
		{
			return;
		}
		for (Store pile : nomad.stores(Kind.DEATHPILE))
		{
			if (pile.ticksLeft == warnTicks && warned.add(pile.key))
			{
				say("A deathpile has " + config.pileWarning() + " minutes of play left.", true);
			}
		}
	}

	/** When the game's deathbank warning is on and stays quiet at login, a remembered deathbank is gone. */
	private void checkLogin()
	{
		if (loginTick < 0 || client.getTickCount() - loginTick != LOGIN_TICKS)
		{
			return;
		}
		Store bank = nomad.deathbank();
		if (bank != null && !sawRetrieval && client.getVarbitValue(VarbitID.OPTION_ITEM_RETRIEVAL_WARNING_DISABLED) == 0)
		{
			nomad.remove(Nomad.DEATHBANK);
			say("The game reports no deathbank, so Nomad has let go of the one at " + bank.name + ".");
			changed();
		}
	}

	/** Ticks the route step in hand when everything it asks for holds now. */
	private void observeRoute()
	{
		List<Route.Step> done = guide.observe(nomad, here());
		for (Route.Step s : done)
		{
			nomad.tick(s.key(), true);
		}
		if (!done.isEmpty())
		{
			guide.stale();
			Route.Step next = guide.current(nomad);
			say(next == null ? "Route finished: welcome to Prifddinas." : "Route step done. Next: " + next.text);
			changed();
		}
	}

	/** Keeps the arrow, path, outlines and plaque row on the route step in hand, each tick. */
	private void guideRoute()
	{
		Route.Step s = client.getGameState() == GameState.LOGGED_IN ? guide.current(nomad) : null;
		String key = s == null ? null : s.key();
		if (key == null ? guidedKey != null : !key.equals(guidedKey))
		{
			guidedKey = key;
			changed();
		}
		if (errand != null && (errandUrgent || s == null))
		{
			guide.head(errand, config.guideArrow(), config.shortestPath());
		}
		else if (s == null)
		{
			guide.stop();
		}
		else
		{
			guide.guide(s, config.guideArrow(), config.guideNpcs(), config.shortestPath());
		}
		List<Plaque.Row> rows = new ArrayList<>(plaqueRows);
		if (s != null && config.routeStep())
		{
			String way = RouteGuide.way(here(), guide.target(s));
			rows.add(new Plaque.Row("Route " + (s.index + 1) + " of " + route.size(), way == null ? "" : way, s.text, Theme.GOLD));
			String quest = Route.inQuest(s, guide.account());
			if (quest != null)
			{
				rows.add(new Plaque.Row("Inside the quest", "", "Open " + quest + " in Quest Helper for each click", Theme.TEAL));
			}
		}
		plaque.show("Nomad", plaqueTint, rows);
	}

	private Route.Account account()
	{
		return guide.account();
	}

	// ---- guards ----

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();
		String option = Text.removeTags(entry.getOption());
		int item = entry.getItemId();
		if (config.guardRaidFloor() && RaidFloor.objectAction(entry.getType()) && RaidFloor.exit(entry.getIdentifier())
			&& raidFloor.inRaid() && !raidLeft().isEmpty())
		{
			entry.setDeprioritized(true);
			return;
		}
		if (item <= 0)
		{
			return;
		}
		if (config.guardLootingBag() && "Destroy".equals(option) && LOOTING_BAGS.contains(item) && !bagDropsHere())
		{
			client.getMenu().removeMenuEntry(entry);
		}
		else if (config.guardSell() && option.startsWith("Sell") && worth(item) > config.sellAbove())
		{
			client.getMenu().removeMenuEntry(entry);
		}
	}

	/** Whether destroying the looting bag where the player stands drops its contents, not deletes them. */
	private boolean bagDropsHere()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return false;
		}
		WorldPoint p = WorldPoint.fromLocalInstance(client, me.getLocalLocation());
		return p != null && LootingBag.dropsHere(client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1, p.getX(), p.getY(), p.getPlane());
	}

	/** Unnoted food, potions and vials of water, which destroying a looting bag loses. */
	private boolean perishes(int item)
	{
		ItemComposition c = itemManager.getItemComposition(item);
		if (c == null || c.getNote() != -1)
		{
			return false;
		}
		if ("Vial of water".equals(c.getName()))
		{
			return true;
		}
		for (String a : c.getInventoryActions())
		{
			if ("Eat".equals(a) || "Drink".equals(a))
			{
				return true;
			}
		}
		return false;
	}

	/** An item's worth for the sell guard: the higher of its Grand Exchange and high alchemy values. */
	private long worth(int item)
	{
		int id = itemManager.canonicalize(item);
		ItemComposition c = itemManager.getItemComposition(id);
		return Math.max(itemManager.getItemPrice(id), c == null ? 0 : c.getHaPrice());
	}

	// ---- the panel and overlays ----

	private void changed()
	{
		dirty = true;
		unsaved = true;
	}

	private int[] here()
	{
		Player me = client.getLocalPlayer();
		if (me == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		WorldPoint p = WorldPoint.fromLocalInstance(client, me.getLocalLocation());
		return p == null ? null : new int[]{p.getX(), p.getY(), p.getPlane()};
	}

	private int keep()
	{
		// An ultimate ironman keeps nothing on an unsafe death, Protect Item included (OSRS Wiki).
		if (nomad != null && nomad.account == 2)
		{
			return 0;
		}
		Player me = client.getLocalPlayer();
		if (me != null && me.getSkullIcon() >= 0)
		{
			return client.isPrayerActive(Prayer.PROTECT_ITEM) ? 1 : 0;
		}
		return client.isPrayerActive(Prayer.PROTECT_ITEM) ? 4 : 3;
	}

	private void publish()
	{
		dirty = false;
		NomadPanel target = panel;
		if (nomad == null)
		{
			plaqueRows = new ArrayList<>();
		plaque.show(null, null, null);
			marker.show(null);
			tips.show(null);
			clearMap();
			if (target != null)
			{
				SwingUtilities.invokeLater(() -> target.show(new View()));
			}
			return;
		}
		int[] here = here();
		Views.Lookup look = lookup();
		View view = Views.build(nomad, look, stash, route, account(), here, keep(), config.idleHours() * 3_600_000L,
			System.currentTimeMillis());
		view.loggedIn = client.getGameState() == GameState.LOGGED_IN;
		for (View.Peril p : view.perils)
		{
			Store pile = p.kind == Kind.DEATHPILE ? nomad.store(p.key) : null;
			WayBack.Way way = pile == null ? null : wayBack(pile);
			if (way != null && way.wait == 0)
			{
				p.note = p.note + " · " + way.say();
				p.way = way.say();
			}
		}
		showOverlays(view, here);
		tips.show(whereKept(view));
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.show(view));
		}
	}

	private void showOverlays(View v, int[] here)
	{
		List<Plaque.Row> rows = new ArrayList<>();
		boolean wild = client.getGameState() == GameState.LOGGED_IN && client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1;
		Color tint = Theme.GOLD;
		if (config.plaque())
		{
			for (View.Peril p : v.perils)
			{
				if (p.kind == Kind.DEATHPILE)
				{
					Color c = p.ticksLeft <= config.pileWarning() * 100L ? Theme.BLOOD : Theme.EMBER;
					rows.add(new Plaque.Row("Deathpile", Format.ticks(p.ticksLeft),
						p.note != null && p.note.startsWith("Needs ") ? p.note.split(" · ")[0] : Format.coins(p.worth) + " lying on the ground", c));
					if (p.way != null)
					{
						rows.add(new Plaque.Row("Way back", "", p.way, Theme.GOLD));
					}
					tint = Theme.EMBER;
				}
				else if (p.kind == Kind.DEATHBANK)
				{
					Store bank = nomad.deathbank();
					String brief = bank == null ? null : Death.brief(bank.name);
					boolean hurt = client.getTickCount() - hurtTick <= 8;
					rows.add(new Plaque.Row(p.title, p.exact ? Format.coins(p.worth) : "?",
						hurt ? "You are taking damage: a death now wipes it" : wild ? "You are in the Wilderness: dying here wipes it"
							: brief != null ? "Reclaim: " + brief : "Any unsafe death wipes it",
						wild || hurt ? Theme.BLOOD : Theme.EMBER));
					tint = wild || hurt ? Theme.BLOOD : Theme.EMBER;
				}
			}
		}
		List<Marker.Mark> marks = new ArrayList<>();
		List<WorldPoint> points = new ArrayList<>();
		List<String> labels = new ArrayList<>();
		errand = null;
		errandUrgent = false;
		long nowMs = System.currentTimeMillis();
		Store soonest = null;
		for (Store floor : nomad.stores(Kind.FLOOR))
		{
			if (floor.world == client.getWorld())
			{
				long left = floor.until - nowMs;
				marks.add(new Marker.Mark(new WorldPoint(floor.x, floor.y, floor.plane), "Dropped " + Format.clock(left),
					left <= config.floorWarning() * 1000L ? Theme.BLOOD : Theme.EMBER));
			}
			if (soonest == null || floor.until < soonest.until)
			{
				soonest = floor;
			}
		}
		if (soonest != null && config.plaque())
		{
			long left = soonest.until - nowMs;
			rows.add(0, new Plaque.Row(soonest.world == Nomad.RAID ? "On the raid floor" : "On the floor", Format.clock(left), itemsText(soonest.items)
				+ (soonest.world != client.getWorld() && soonest.world != Nomad.RAID ? " · world " + soonest.world : ""), left <= config.floorWarning() * 1000L ? Theme.BLOOD : Theme.EMBER));
			tint = Theme.EMBER;
		}
		Store urgent = null;
		for (Store pile : nomad.stores(Kind.DEATHPILE))
		{
			WorldPoint p = new WorldPoint(pile.x, pile.y, pile.plane);
			marks.add(new Marker.Mark(p, "Deathpile " + Format.ticks(pile.ticksLeft), Theme.EMBER));
			points.add(p);
			labels.add("Deathpile");
			if (urgent == null || pile.ticksLeft < urgent.ticksLeft)
			{
				urgent = pile;
			}
		}
		long full = forecast.untilFull(nomad.played, v.invUsed);
		if (config.plaque() && full > 0 && full <= 10 * 60_000L)
		{
			rows.add(new Plaque.Row("Inventory full", "~" + Math.max(1, (full + 30_000) / 60_000) + " min",
				(28 - v.invUsed) + ((28 - v.invUsed) == 1 ? " slot" : " slots") + " left at this pace", full <= 2 * 60_000L ? Theme.EMBER : Theme.GOLD));
		}
		Trip t = nomad.activeTrip();
		Fetch f = t == null ? null : Views.plan(nomad, t, lookup(), here);
		Errand was = job;
		job = errand(urgent, f);
		if (t != null && job == null && was != null && (was.kind == Errand.Kind.FETCH || was.kind == Errand.Kind.UNNOTE))
		{
			say("Everything for " + t.name + " is packed.");
		}
		if (job != null && job.kind == Errand.Kind.FETCH && job.where != null)
		{
			marks.add(new Marker.Mark(job.where, "Nomad: " + f.next().store.name, Theme.TEAL));
			points.add(job.where);
			labels.add("Next stop: " + f.next().store.name);
		}
		if (job != null && config.pointer())
		{
			errand = job.where;
			errandUrgent = job.where != null && job.kind != Errand.Kind.STASH_AWAY;
		}
		if (job != null && config.plaque())
		{
			String way = job.where == null ? null : RouteGuide.way(here, job.where);
			rows.add(0, new Plaque.Row("Next: " + job.title, way == null ? "" : way, job.text,
				job.kind == Errand.Kind.FETCH ? Theme.TEAL : Theme.EMBER));
		}
		Route.Step step = guide.current(nomad);
		WorldPoint target = guide.target(step);
		if (target != null)
		{
			String label = step.text.length() > 40 ? step.text.substring(0, 38) + "..." : step.text;
			marks.add(new Marker.Mark(target, "Route: " + label, Theme.GOLD));
			points.add(target);
			labels.add("Route step " + (step.index + 1) + ": " + step.text);
		}
		plaqueRows = rows;
		plaqueTint = tint;
		plaque.show("Nomad", tint, rows);
		marker.show(config.pointer() ? marks : null);
		if (!config.pointer())
		{
			points.clear();
		}
		updateMap(points, labels);
	}

	/**
	 * The one thing to do next, most pressing first: save the deathpile that runs out soonest,
	 * reclaim a waiting deathbank, then fetch the next stop of the packing list. Null when none.
	 */
	private Errand errand(Store pile, Fetch f)
	{
		Views.Lookup look = lookup();
		if (pile != null)
		{
			List<Integer> order = com.codex.nomad.core.Pickup.order(pile.items, this::price, look::stackable);
			List<String> names = new ArrayList<>();
			for (int i = 0; i < Math.min(3, order.size()); i++)
			{
				names.add(name(itemManager.canonicalize(order.get(i))));
			}
			Set<Integer> take = new HashSet<>();
			order.forEach(id -> take.add(itemManager.canonicalize(id)));
			return new Errand(Errand.Kind.PILE, "save your deathpile", "Pick up " + String.join(", then ", names)
				+ (order.size() > 3 ? " and the rest" : ""), new WorldPoint(pile.x, pile.y, pile.plane), take, order, -1, null);
		}
		Store bank = nomad.deathbank();
		if (bank != null)
		{
			String claim = Death.claim(bank.name);
			long fee = Death.fee(bank.name);
			long coins = nomad.carried(Nomad.INVENTORY).getOrDefault(ItemID.COINS, 0L);
			String text = (claim != null ? claim : "Reclaim it at " + bank.name)
				+ (fee > coins ? "; bring " + Format.coins(fee - coins) + " more coins" : "");
			return new Errand(Errand.Kind.DEATHBANK, "reclaim your deathbank", text, null, null, null, -1, null);
		}
		Fetch.Stop next = f == null ? null : f.next();
		if (next == null && f != null)
		{
			return unnote(f.trip);
		}
		if (f == null)
		{
			return stashAway();
		}
		if (next == null || next.store.kind == Kind.DEATHPILE)
		{
			return null;
		}
		Store s = next.store;
		Set<Integer> take = new HashSet<>();
		List<String> names = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : next.take.entrySet())
		{
			take.add(itemManager.canonicalize(e.getKey()));
			names.add((e.getValue() > 1 ? Format.amount(e.getValue()) + " " : "") + name(itemManager.canonicalize(e.getKey())));
		}
		int object = -1;
		if (s.kind == Kind.STASH && s.key.startsWith("stash:"))
		{
			try
			{
				object = STASHUnit.valueOf(s.key.substring(6)).getObjectId();
			}
			catch (IllegalArgumentException ex)
			{
				object = -1;
			}
		}
		String furniture = s.kind == Kind.COSTUME ? s.name.replaceAll(" \\(.*", "") : null;
		String verb = s.kind == Kind.STASH ? "Search the STASH unit for " : s.kind == Kind.FLOOR ? "Pick up " : "Take ";
		String what = names.size() > 3 ? String.join(", ", names.subList(0, 3)) + " and " + (names.size() - 3) + " more" : String.join(", ", names);
		return new Errand(Errand.Kind.FETCH, s.name + " for " + f.trip.name, verb + what,
			s.located() ? new WorldPoint(s.x, s.y, s.plane) : null, take, null, object, furniture);
	}

	/**
	 * Once everything for a trip is carried, the last step: turn the banknotes it needs back into
	 * items at the nearest merchant who will, such as Phials. Null when nothing needs unnoting.
	 */
	private Errand unnote(Trip t)
	{
		Map<Integer, Long> inv = nomad.carried(Nomad.INVENTORY);
		int[] here = here();
		List<String> names = new ArrayList<>();
		Set<Integer> notesToUse = new HashSet<>();
		Notary.Desk desk = null;
		for (Trip.Want w : t.wants)
		{
			if (w.worn)
			{
				continue;
			}
			ItemComposition c = itemManager.getItemComposition(w.item);
			int noted = c == null ? -1 : c.getLinkedNoteId();
			long loose = inv.getOrDefault(w.item, 0L);
			long notes = noted > 0 ? inv.getOrDefault(noted, 0L) : 0;
			if (loose >= w.qty || notes <= 0 || c == null || c.getNote() != -1)
			{
				continue;
			}
			List<Notary.Desk> desks = Notary.desks(c.getName(), Notary.Way.UNNOTE, here);
			Notary.Desk d = desks.isEmpty() ? null : desks.get(0);
			if (d == null || d.plane < 0 || d.wilderness)
			{
				continue;
			}
			desk = desk == null ? d : desk;
			if (d == desk)
			{
				names.add(Math.min(w.qty - loose, notes) + " " + c.getName());
				notesToUse.add(noted);
			}
		}
		if (desk == null)
		{
			return null;
		}
		Errand e = new Errand(Errand.Kind.UNNOTE, "unnote at " + desk.who + " for " + t.name,
			"Use the notes on " + desk.who + ": " + String.join(", ", names) + (desk.fee > 0 ? " (" + desk.fee + " gp each)" : ""),
			new WorldPoint(desk.x, desk.y, desk.plane), notesToUse, null, -1, null);
		e.npc = desk.who;
		return e;
	}

	/**
	 * With no packing list to fetch: a full set of emote clue items carried for a STASH unit that is
	 * not yet filled. The game takes only the whole set at once, into a unit already built.
	 */
	private Errand stashAway()
	{
		Map<Integer, Long> carried = new HashMap<>();
		for (Map.Entry<Integer, Long> e : nomad.carried(Nomad.INVENTORY).entrySet())
		{
			carried.merge(itemManager.canonicalize(e.getKey()), e.getValue(), Long::sum);
		}
		for (Map.Entry<Integer, Long> e : nomad.carried(Nomad.WORN).entrySet())
		{
			carried.merge(itemManager.canonicalize(e.getKey()), e.getValue(), Long::sum);
		}
		int[] here = here();
		Errand best = null;
		int bestDistance = Integer.MAX_VALUE;
		Set<String> tried = new HashSet<>();
		for (int item : carried.keySet())
		{
			for (StashBook.Home h : stash.homes(item))
			{
				if (!tried.add(h.unit))
				{
					continue;
				}
				Store kept = nomad.store("stash:" + h.unit);
				StashBook.Unit u = stash.unit(h.unit);
				if (kept != null && !kept.isEmpty() || u == null)
				{
					continue;
				}
				Set<Integer> set = new HashSet<>();
				List<String> names = new ArrayList<>();
				boolean whole = true;
				for (StashBook.Need need : u.needs)
				{
					Integer got = null;
					for (int id : need.ids)
					{
						if (carried.containsKey(id))
						{
							got = id;
							break;
						}
					}
					if (got == null)
					{
						whole = false;
						break;
					}
					set.add(got);
					names.add(name(got));
				}
				STASHUnit unit;
				try
				{
					unit = STASHUnit.valueOf(h.unit);
				}
				catch (IllegalArgumentException ex)
				{
					continue;
				}
				if (!whole || set.isEmpty())
				{
					continue;
				}
				WorldPoint at = unit.getWorldPoints()[0];
				int d = here == null ? 0 : Math.max(Math.abs(at.getX() - here[0]), Math.abs(at.getY() - here[1]));
				if (d < bestDistance)
				{
					bestDistance = d;
					best = new Errand(Errand.Kind.STASH_AWAY, "stash a clue set at " + h.place,
						"Deposit " + String.join(", ", names) + " in the STASH unit (if built) and carry them no more",
						at, set, null, unit.getObjectId(), null);
				}
			}
		}
		return best;
	}

	/** Looks over the player's floor of the scene for the STASH unit or furniture the errand needs. */
	private void findErrandObjects()
	{
		Errand e = job;
		Player me = client.getLocalPlayer();
		if (e == null || me == null || e.object <= 0 && e.furniture == null)
		{
			if (!errandObjects.isEmpty())
			{
				errandObjects = new ArrayList<>();
			}
			return;
		}
		List<TileObject> found = new ArrayList<>();
		Tile[][] plane = client.getTopLevelWorldView().getScene().getTiles()[client.getTopLevelWorldView().getPlane()];
		for (Tile[] column : plane)
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}
				List<TileObject> here = new ArrayList<>();
				if (tile.getGameObjects() != null)
				{
					for (GameObject o : tile.getGameObjects())
					{
						if (o != null)
						{
							here.add(o);
						}
					}
				}
				if (tile.getWallObject() != null)
				{
					here.add(tile.getWallObject());
				}
				if (tile.getDecorativeObject() != null)
				{
					here.add(tile.getDecorativeObject());
				}
				for (TileObject o : here)
				{
					if (o.getId() == e.object || e.furniture != null && e.furniture.equalsIgnoreCase(objectName(o.getId())))
					{
						if (!found.contains(o))
						{
							found.add(o);
						}
					}
				}
			}
		}
		errandObjects = found;
	}

	/** An object's name, through its current form when it changes with the player's progress. */
	private String objectName(int id)
	{
		ObjectComposition c = client.getObjectDefinition(id);
		if (c != null && c.getImpostorIds() != null)
		{
			ObjectComposition i = c.getImpostor();
			c = i != null ? i : c;
		}
		return c == null ? null : c.getName();
	}

	private static int slotsUsed(ItemContainer c)
	{
		int n = 0;
		for (Item i : c.getItems())
		{
			n += i.getId() > 0 ? 1 : 0;
		}
		return n;
	}

	/** Every place each item is kept, by its common id, for the inventory tooltip. */
	private Map<Integer, List<String>> whereKept(View v)
	{
		Map<Integer, List<String>> where = new HashMap<>();
		for (View.StoreView s : v.stores)
		{
			String place = s.kind == Kind.FLOOR && s.world == Nomad.RAID ? "On the Chambers of Xeric floor"
				: s.kind == Kind.FLOOR ? "On the floor, world " + s.world
				: s.kind == Kind.DEATHPILE ? "Deathpile, " + Format.ticks(s.ticksLeft) + " left"
				: s.kind == Kind.STASH ? "STASH, " + s.name
				: s.kind == Kind.DEATHBANK ? "Deathbank, " + s.name : s.name;
			for (View.ItemLine l : s.items)
			{
				where.computeIfAbsent(itemManager.canonicalize(l.id), k -> new ArrayList<>())
					.add(l.qty > 1 ? place + ": " + Format.whole(l.qty) : place);
			}
		}
		return where;
	}

	private final List<WorldPoint> shownPoints = new ArrayList<>();

	private void updateMap(List<WorldPoint> points, List<String> labels)
	{
		if (points.equals(shownPoints))
		{
			return;
		}
		clearMap();
		shownPoints.addAll(points);
		for (int i = 0; i < points.size(); i++)
		{
			WorldMapPoint p = new WorldMapPoint(points.get(i), Sigil.icon(20));
			p.setName(labels.get(i));
			p.setTooltip("Codex Nomad: " + labels.get(i));
			p.setSnapToEdge(true);
			p.setJumpOnClick(true);
			mapPoints.add(p);
			worldMapPointManager.add(p);
		}
	}

	private void clearMap()
	{
		for (WorldMapPoint p : mapPoints)
		{
			worldMapPointManager.remove(p);
		}
		mapPoints.clear();
		shownPoints.clear();
	}

	private void say(String text)
	{
		say(text, false);
	}

	private void say(String text, boolean alarm)
	{
		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("Nomad: ")
			.append(alarm ? ChatColorType.HIGHLIGHT : ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(message).build());
	}

	// ---- trips ----

	private void saveTrip(String name)
	{
		if (nomad == null || name == null || name.trim().isEmpty())
		{
			return;
		}
		Trip t = new Trip(name.trim(), System.currentTimeMillis());
		Map<Integer, Long> worn = Items.canon(lastWorn, itemManager::canonicalize);
		Map<Integer, Long> inv = Items.canon(lastInv, itemManager::canonicalize);
		Items.add(inv, Items.canon(nomad.carried(Nomad.RUNE_POUCH), itemManager::canonicalize));
		worn.forEach((id, q) -> t.wants.add(new Trip.Want(id, name(id), q, true)));
		inv.forEach((id, q) ->
		{
			if (!LOOTING_BAGS.contains(id) && id != ItemID.COINS)
			{
				t.wants.add(new Trip.Want(id, name(id), q, false));
			}
		});
		if (t.wants.isEmpty())
		{
			return;
		}
		nomad.save(t);
		nomad.active = t.name;
		unsaved = true;
		publish();
	}

	// ---- items ----

	private Map<Integer, Long> contents(ItemContainer container)
	{
		Map<Integer, Long> items = new LinkedHashMap<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				items.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		return items;
	}

	private String name(int id)
	{
		return names.computeIfAbsent(id, i ->
		{
			ItemComposition c = itemManager.getItemComposition(i);
			return c == null ? "Item " + i : c.getMembersName();
		});
	}

	private long price(int id)
	{
		if (id == ItemID.COINS)
		{
			return 1;
		}
		return itemManager.getItemPrice(itemManager.canonicalize(id));
	}

	private Views.Lookup lookup()
	{
		return new Views.Lookup()
		{
			@Override
			public String name(int id)
			{
				return CodexNomadPlugin.this.name(itemManager.canonicalize(id));
			}

			@Override
			public long price(int id)
			{
				return CodexNomadPlugin.this.price(id);
			}

			@Override
			public boolean stackable(int id)
			{
				ItemComposition c = itemManager.getItemComposition(id);
				return c != null && (c.isStackable() || c.getNote() != -1);
			}

			@Override
			public boolean noted(int id)
			{
				ItemComposition c = itemManager.getItemComposition(id);
				return c != null && c.getNote() != -1;
			}

			@Override
			public int canon(int id)
			{
				return itemManager.canonicalize(id);
			}
		};
	}

	// ---- saving ----

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		nomad = null;
		if (profile == null)
		{
			return;
		}
		String saved = configManager.getRSProfileConfiguration(CodexNomadConfig.GROUP, SAVE_KEY);
		Nomad.Loaded read = Nomad.read(gson, saved);
		if (read.damaged)
		{
			log.warn("The saved Nomad data was damaged; kept what still reads and set the save as it was aside");
			configManager.setConfiguration(CodexNomadConfig.GROUP, profile, DAMAGED_KEY, saved);
		}
		nomad = read.nomad;
		unsaved = false;
		dirty = true;
	}

	private boolean save()
	{
		if (profile == null || nomad == null || !unsaved)
		{
			return false;
		}
		unsaved = false;
		configManager.setConfiguration(CodexNomadConfig.GROUP, profile, SAVE_KEY, nomad.write(gson));
		String holdings = Holdings.write(gson, nomad.holdings(), System.currentTimeMillis());
		configManager.setConfiguration(CodexNomadConfig.GROUP, profile, HOLDINGS_KEY, holdings);
		if (config.shareHoldings() && nomad.account == 2)
		{
			String steward = configManager.getConfiguration(STEWARD_GROUP, profile, STEWARD_KEY);
			if (Holdings.ours(gson, steward))
			{
				configManager.setConfiguration(STEWARD_GROUP, profile, STEWARD_KEY, holdings);
			}
		}
		return true;
	}
}

package com.codex.nomad;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * The farming compost bins, read from the game's bin varbit while you stand near one. Only
 * finished compost and rotten tomatoes count: a bin still filling or rotting holds neither yet.
 * Regions and values follow Dude, Where's My Stuff (BSD 2-Clause).
 */
final class CompostBins
{
	static final class Bin
	{
		final String key;
		final String name;
		final boolean big;
		final int varbit;

		Bin(String area, boolean big, int varbit)
		{
			this.key = "compost:" + area.toLowerCase().replace(' ', '-');
			this.name = "Compost bin, " + area;
			this.big = big;
			this.varbit = varbit;
		}
	}

	private static final Map<Integer, Bin> BY_REGION = new HashMap<>();

	static
	{
		bin(new Bin("Ardougne", false, VarbitID.FARMING_TRANSMIT_E), 10548);
		bin(new Bin("Catherby", false, VarbitID.FARMING_TRANSMIT_E), 11062);
		bin(new Bin("Falador", false, VarbitID.FARMING_TRANSMIT_E), 12083);
		bin(new Bin("Kourend", false, VarbitID.FARMING_TRANSMIT_E), 6967, 6711);
		bin(new Bin("Morytania", false, VarbitID.FARMING_TRANSMIT_E), 14391, 14390);
		bin(new Bin("Farming Guild", true, VarbitID.FARMING_TRANSMIT_N), 4922, 5177, 5178, 5179, 4921, 4923, 4665, 4666, 4667);
		bin(new Bin("Prifddinas", false, VarbitID.FARMING_TRANSMIT_D), 13151, 12895, 12894, 13150, 12994, 12993, 12737, 12738,
			12126, 12127, 13250);
	}

	private CompostBins()
	{
	}

	private static void bin(Bin b, int... regions)
	{
		for (int r : regions)
		{
			BY_REGION.put(r, b);
		}
	}

	/** The bin whose varbit is meaningful in this region, or null. */
	static Bin near(int region)
	{
		return BY_REGION.get(region);
	}

	/** What a bin holds for the varbit's value. */
	static Map<Integer, Long> read(boolean big, int v)
	{
		Map<Integer, Long> out = new LinkedHashMap<>();
		int compost = 0;
		int superCompost = 0;
		int ultra = 0;
		int tomatoes = 0;
		if (v >= 16 && v <= 30)
		{
			compost = v - 15;
		}
		else if (v >= 48 && v <= 62)
		{
			superCompost = v - 47;
		}
		else if (v >= 144 && v <= 158)
		{
			tomatoes = v - 143;
		}
		else if (big)
		{
			if (v >= 78 && v <= 92)
			{
				compost = 15 + v - 77;
			}
			else if (v == 93)
			{
				compost = 30;
			}
			else if (v == 99)
			{
				superCompost = 30;
			}
			else if (v >= 100 && v <= 114)
			{
				superCompost = 15 + v - 99;
			}
			else if (v >= 176 && v <= 205)
			{
				ultra = v - 175;
			}
			else if (v >= 207 && v <= 221)
			{
				tomatoes = 15 + v - 206;
			}
			else if (v == 222)
			{
				tomatoes = 30;
			}
		}
		else if (v == 94)
		{
			compost = 15;
		}
		else if (v == 126)
		{
			superCompost = 15;
		}
		else if (v == 160)
		{
			tomatoes = 15;
		}
		else if (v >= 176 && v <= 190)
		{
			ultra = v - 175;
		}
		put(out, ItemID.BUCKET_COMPOST, compost);
		put(out, ItemID.BUCKET_SUPERCOMPOST, superCompost);
		put(out, ItemID.BUCKET_ULTRACOMPOST, ultra);
		put(out, ItemID.ROTTEN_TOMATO, tomatoes);
		return out.isEmpty() ? Collections.emptyMap() : out;
	}

	private static void put(Map<Integer, Long> out, int id, int n)
	{
		if (n > 0)
		{
			out.put(id, (long) n);
		}
	}
}

package com.codex.nomad;

import java.util.Collections;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * The one thing to do next that is not a route step, guided the way Quest Helper guides a quest:
 * where to go, what to click there, and which items to take in the interface or off the floor.
 * Nomad picks it each refresh, most pressing first: save a deathpile, reclaim a deathbank, fetch
 * what the packing list needs. It goes away by itself once done, since it is worked out afresh.
 */
final class Errand
{
	enum Kind
	{
		PILE, DEATHBANK, FETCH, UNNOTE, STASH_AWAY
	}

	final Kind kind;
	/** The step in a few words, for the plaque: "Save your deathpile". */
	final String title;
	/** What to do there: "Take Abyssal whip first, then Dragon boots". */
	final String text;
	/** Where to go, or null when it is not known. */
	final WorldPoint where;
	/** Items to highlight in an open interface and on the floor, by common id. */
	final Set<Integer> take;
	/** For a pile, the order to pick it up in, by item id. */
	final List<Integer> order;
	/** A STASH unit's object id to outline, or -1. */
	final int object;
	/** A house furniture name to outline, such as "Armour case", or null. */
	final String furniture;
	/** A person to outline, by name, such as "Phials", or null. */
	String npc;

	Errand(Kind kind, String title, String text, WorldPoint where, Set<Integer> take, List<Integer> order, int object, String furniture)
	{
		this.kind = kind;
		this.title = title;
		this.text = text;
		this.where = where;
		this.take = take == null ? Collections.emptySet() : take;
		this.order = order == null ? Collections.emptyList() : order;
		this.object = object;
		this.furniture = furniture;
	}
}

package com.codex.nomad;

import com.codex.nomad.core.Items;
import com.codex.nomad.core.Nomad;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Follows the herb sack from what the game says about it: checking it lists every herb, picking a
 * herb up or filling it adds, and emptying it takes out. Adapted from Dude, Where's My Stuff (BSD
 * 2-Clause).
 */
final class HerbSack
{
	static final String NAME = "Herb sack";
	static final int[] HERBS = {
		ItemID.UNIDENTIFIED_GUAM, ItemID.UNIDENTIFIED_MARENTILL, ItemID.UNIDENTIFIED_TARROMIN,
		ItemID.UNIDENTIFIED_HARRALANDER, ItemID.UNIDENTIFIED_RANARR, ItemID.UNIDENTIFIED_TOADFLAX,
		ItemID.UNIDENTIFIED_IRIT, ItemID.UNIDENTIFIED_AVANTOE, ItemID.UNIDENTIFIED_KWUARM, ItemID.UNIDENTIFIED_HUASCA,
		ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.UNIDENTIFIED_CADANTINE, ItemID.UNIDENTIFIED_LANTADYME,
		ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.UNIDENTIFIED_TORSTOL};
	/** A herb sack holds up to 30 of each herb. */
	static final long MOST = 30;
	private static final Pattern LISTED = Pattern.compile("(\\d+) x (.*)");
	private static final Pattern PICKED = Pattern.compile("You put the (.*) herb into your herb sack");
	private static final Pattern ADDED = Pattern.compile("You add the (.*) to your sack");

	private enum Pending
	{
		NONE, ADD, TAKE
	}

	private final IntFunction<String> names;
	private Map<String, Integer> byName;
	private boolean listing;
	private Pending pending = Pending.NONE;

	HerbSack(IntFunction<String> names)
	{
		this.names = names;
	}

	private int herb(String name)
	{
		if (byName == null)
		{
			byName = new HashMap<>();
			for (int id : HERBS)
			{
				byName.put(names.apply(id).toLowerCase(Locale.ENGLISH), id);
			}
		}
		Integer id = byName.get(name.trim().toLowerCase(Locale.ENGLISH));
		return id == null ? -1 : id;
	}

	/**
	 * Hears a game message.
	 *
	 * @return true if the sack changed now
	 */
	boolean heard(String message, Nomad n, long now)
	{
		if (message.startsWith("The herb sack is empty"))
		{
			listing = false;
			n.carry(NAME, new HashMap<>(), now);
			return true;
		}
		if (message.startsWith("You look in your herb sack"))
		{
			listing = true;
			n.carry(NAME, new HashMap<>(), now);
			return true;
		}
		if (listing)
		{
			Matcher m = LISTED.matcher(message);
			if (m.matches())
			{
				int id = herb(m.group(2));
				if (id > 0)
				{
					Map<Integer, Long> held = new LinkedHashMap<>(n.carried(NAME));
					held.put(id, Long.parseLong(m.group(1)));
					n.carry(NAME, held, now);
					return true;
				}
			}
			return false;
		}
		Matcher picked = PICKED.matcher(message);
		if (picked.find())
		{
			int id = herb(picked.group(1));
			if (id > 0)
			{
				Map<Integer, Long> held = new LinkedHashMap<>(n.carried(NAME));
				held.merge(id, 1L, (a, b) -> Math.min(MOST, a + b));
				n.carry(NAME, held, now);
				return true;
			}
			return false;
		}
		if (ADDED.matcher(message).find() || message.startsWith("You add the herbs to your sack"))
		{
			pending = Pending.ADD;
		}
		else if (message.startsWith("You rummage around to see if you can extract any herbs from your herb sack"))
		{
			pending = Pending.TAKE;
		}
		return false;
	}

	/**
	 * One tick passes: what left the inventory went into the sack, or what arrived came out of it.
	 *
	 * @return true if the sack changed
	 */
	boolean tick(Map<Integer, Long> removed, Map<Integer, Long> gained, Nomad n, long now)
	{
		listing = false;
		Pending p = pending;
		pending = Pending.NONE;
		if (p == Pending.NONE)
		{
			return false;
		}
		Map<Integer, Long> held = new LinkedHashMap<>(n.carried(NAME));
		Map<Integer, Long> moved = p == Pending.ADD ? removed : gained;
		for (int id : HERBS)
		{
			long q = moved.getOrDefault(id, 0L);
			if (q > 0)
			{
				held.merge(id, p == Pending.ADD ? q : -q, Long::sum);
			}
		}
		n.carry(NAME, Items.clean(held), now);
		return true;
	}
}

package com.codex.nomad;

import com.codex.nomad.core.Death;
import com.codex.nomad.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Highlights in the world what the route step in hand asks you to click: the people it names, the
 * objects to use and the items to pick up, each outlined in gold with a word above it.
 */
class Highlights extends Overlay
{
	private static final String HOLDS = "Your deathbank";

	private final Client client;
	private final ModelOutlineRenderer outlines;
	private final RouteGuide guide;
	private final Supplier<List<TileObject>> warnAt;
	private final Supplier<String> warning;
	private final Supplier<String> bank;
	private final Supplier<List<TileObject>> holders;
	private final Supplier<Errand> errand;
	private final Supplier<List<TileObject>> errandObjects;
	private final java.util.function.IntFunction<String> name;

	/**
	 * @param warnAt objects to mark in red, such as the ways out of a raid with things left on its floor
	 * @param warning the words above them
	 */
	Highlights(Client client, ModelOutlineRenderer outlines, RouteGuide guide, Supplier<List<TileObject>> warnAt, Supplier<String> warning,
		Supplier<String> bank, Supplier<List<TileObject>> holders, Supplier<Errand> errand, Supplier<List<TileObject>> errandObjects,
		java.util.function.IntFunction<String> name)
	{
		this.errand = errand;
		this.errandObjects = errandObjects;
		this.name = name;
		this.bank = bank;
		this.holders = holders;
		this.client = client;
		this.outlines = outlines;
		this.guide = guide;
		this.warnAt = warnAt;
		this.warning = warning;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<TileObject> danger = warnAt.get();
		if (!danger.isEmpty())
		{
			String words = warning.get();
			for (TileObject o : danger)
			{
				outlines.drawOutline(o, 2, Theme.BLOOD, 4);
				Point at = o.getCanvasTextLocation(g, words, 200);
				if (at != null)
				{
					OverlayUtil.renderTextLocation(g, at, words, Theme.BLOOD);
				}
			}
		}
		Errand job = errand.get();
		if (job != null)
		{
			for (TileObject o : errandObjects.get())
			{
				outlines.drawOutline(o, 2, Theme.TEAL, 4);
				String words = job.kind == Errand.Kind.STASH_AWAY ? "Deposit" : job.kind == Errand.Kind.FETCH && job.object > 0 ? "Search" : "Take from here";
				Point at = o.getCanvasTextLocation(g, words, 150);
				if (at != null)
				{
					OverlayUtil.renderTextLocation(g, at, words, Theme.TEAL);
				}
			}
			if (job.npc != null)
			{
				for (NPC npc : client.getTopLevelWorldView().npcs())
				{
					if (job.npc.equalsIgnoreCase(npc.getName()))
					{
						outlines.drawOutline(npc, 2, Theme.TEAL, 4);
						label(g, npc.getCanvasTextLocation(g, "Use the notes", npc.getLogicalHeight() + 40), "Use the notes");
					}
				}
			}
			if (job.kind == Errand.Kind.PILE && job.where != null)
			{
				pile(g, job);
			}
		}
		String lair = bank.get();
		if (lair != null)
		{
			for (NPC npc : client.getTopLevelWorldView().npcs())
			{
				if (Death.holds(lair, npc.getId(), false))
				{
					outlines.drawOutline(npc, 2, Theme.EMBER, 4);
					Point at = npc.getCanvasTextLocation(g, HOLDS, npc.getLogicalHeight() + 40);
					if (at != null)
					{
						OverlayUtil.renderTextLocation(g, at, HOLDS, Theme.EMBER);
					}
				}
			}
			for (TileObject o : holders.get())
			{
				if (Death.holds(lair, o.getId(), true))
				{
					outlines.drawOutline(o, 2, Theme.EMBER, 4);
					Point at = o.getCanvasTextLocation(g, HOLDS, 150);
					if (at != null)
					{
						OverlayUtil.renderTextLocation(g, at, HOLDS, Theme.EMBER);
					}
				}
			}
		}
		if (guide.lead().isEmpty())
		{
			return null;
		}
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (!guide.wanted(npc))
			{
				continue;
			}
			outlines.drawOutline(npc, 2, Theme.GOLD, 4);
			label(g, npc.getCanvasTextLocation(g, npc.getName(), npc.getLogicalHeight() + 40), npc.getName());
		}
		for (TileObject o : guide.objects())
		{
			outlines.drawOutline(o, 2, Theme.GOLD, 4);
			Shape box = o.getClickbox();
			if (box != null)
			{
				g.setColor(Theme.alpha(Theme.GOLD, 40));
				g.fill(box);
			}
			label(g, o.getCanvasTextLocation(g, "Click", 150), "Click");
		}
		for (Object[] lying : guide.ground())
		{
			Tile t = (Tile) lying[0];
			String name = (String) lying[1];
			LocalPoint lp = t.getLocalLocation();
			Polygon poly = lp == null ? null : Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				g.setColor(Theme.alpha(Theme.GOLD, 40));
				g.fill(poly);
				g.setColor(Theme.GOLD);
				g.setStroke(new BasicStroke(2));
				g.draw(poly);
			}
			label(g, lp == null ? null : Perspective.getCanvasTextLocation(client, g, lp, "Take " + name, 40), "Take " + name);
		}
		return null;
	}

	/** Marks the deathpile's tile and names the most valuable thing still on it, to take first. */
	private void pile(Graphics2D g, Errand job)
	{
		LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), job.where);
		if (lp == null)
		{
			return;
		}
		Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
		int plane = job.where.getPlane();
		if (plane < 0 || plane >= tiles.length)
		{
			return;
		}
		Tile t = tiles[plane][lp.getSceneX()][lp.getSceneY()];
		List<net.runelite.api.TileItem> lying = t == null ? null : t.getGroundItems();
		if (lying == null || lying.isEmpty())
		{
			return;
		}
		String first = null;
		for (int id : job.order)
		{
			for (net.runelite.api.TileItem i : lying)
			{
				if (i.getId() == id)
				{
					first = name.apply(id);
					break;
				}
			}
			if (first != null)
			{
				break;
			}
		}
		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly != null)
		{
			g.setColor(Theme.alpha(Theme.EMBER, 40));
			g.fill(poly);
			g.setColor(Theme.EMBER);
			g.setStroke(new BasicStroke(2));
			g.draw(poly);
		}
		if (first != null)
		{
			String words = "Take first: " + first;
			Point at = Perspective.getCanvasTextLocation(client, g, lp, words, 40);
			if (at != null)
			{
				OverlayUtil.renderTextLocation(g, at, words, Theme.EMBER);
			}
		}
	}

	private static void label(Graphics2D g, Point at, String text)
	{
		if (at != null && text != null)
		{
			OverlayUtil.renderTextLocation(g, at, text, Theme.GOLD);
		}
	}
}

package com.codex.nomad;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Map;
import java.util.TreeMap;

/**
 * What the account holds, written for the rest of the Codex suite in the same shape as Codex Bank
 * Steward's bank: {version, savedAt, items{id: qty}, truncated}. An ultimate ironman has no bank,
 * so this stands in for one, marked with its source so a real bank copy is never overwritten.
 */
final class Holdings
{
	static final int VERSION = 1;
	static final int MAX_ITEMS = 2000;
	static final String SOURCE = "nomad";

	/** The written form. Field order is the contract's. */
	static final class Snapshot
	{
		int version = VERSION;
		long savedAt;
		Map<Integer, Long> items = new TreeMap<>();
		boolean truncated;
		String source = SOURCE;
	}

	private Holdings()
	{
	}

	static String write(Gson gson, Map<Integer, Long> items, long now)
	{
		Snapshot s = new Snapshot();
		s.savedAt = now;
		for (Map.Entry<Integer, Long> e : new TreeMap<>(items).entrySet())
		{
			if (e.getKey() <= 0 || e.getValue() <= 0)
			{
				continue;
			}
			if (s.items.size() >= MAX_ITEMS)
			{
				s.truncated = true;
				break;
			}
			s.items.put(e.getKey(), e.getValue());
		}
		return gson.toJson(s);
	}

	/** True when a saved bank copy is absent or one Nomad wrote, so Nomad may write over it. */
	static boolean ours(Gson gson, String saved)
	{
		if (saved == null || saved.trim().isEmpty())
		{
			return true;
		}
		try
		{
			JsonElement e = new JsonParser().parse(saved);
			if (!e.isJsonObject())
			{
				return false;
			}
			JsonObject o = e.getAsJsonObject();
			return o.has("source") && SOURCE.equals(o.get("source").getAsString());
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}
}

package com.codex.nomad;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.MenuAction;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

/**
 * The floor of the Chambers of Xeric, which ultimate ironmen use as storage: what is dropped there
 * stays for the whole raid and is destroyed when the player leaves. Nomad keeps it as a store with no
 * timer, finds the ways out and pushes their left-click down while anything is left behind. The exit
 * objects follow UIM Utilities (BSD 2-Clause).
 */
class RaidFloor
{
	private static final Set<Integer> EXITS = new HashSet<>(Arrays.asList(
		49999, 50000, ObjectID.RAIDS_BOSSEXIT, ObjectID.RAIDS_EXIT_STEPS));
	/** The in-raid varbit reads 0 for a moment on each room load, so leaving takes this long to count. */
	private static final int TICKS_OUT = 5;

	private final Client client;
	private final List<TileObject> exits = new ArrayList<>();
	private boolean scanned;
	private int ticksOut;

	RaidFloor(Client client)
	{
		this.client = client;
	}

	boolean inRaid()
	{
		return client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
	}

	static boolean exit(int object)
	{
		return EXITS.contains(object);
	}

	static boolean objectAction(MenuAction action)
	{
		return action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	List<TileObject> exits()
	{
		return exits;
	}

	void spawned(GameObject o)
	{
		if (o != null && exit(o.getId()) && !exits.contains(o) && inRaid())
		{
			exits.add(o);
		}
	}

	void despawned(GameObject o)
	{
		exits.remove(o);
	}

	void sceneLoading()
	{
		exits.clear();
		scanned = false;
	}

	/**
	 * Called each tick. Reads the scene once per load for exits that spawned before the raid varbit
	 * was set.
	 *
	 * @return true on the tick the player is judged to have left the raid
	 */
	boolean tick()
	{
		if (inRaid())
		{
			ticksOut = 0;
			if (!scanned)
			{
				scanned = true;
				for (Tile[][] plane : client.getTopLevelWorldView().getScene().getTiles())
				{
					for (Tile[] column : plane)
					{
						for (Tile tile : column)
						{
							if (tile != null && tile.getGameObjects() != null)
							{
								for (GameObject o : tile.getGameObjects())
								{
									spawned(o);
								}
							}
						}
					}
				}
			}
			return false;
		}
		exits.clear();
		return ++ticksOut == TICKS_OUT;
	}
}

package com.codex.nomad;

