	static final List<Read> ALL;
	private static final Map<Integer, List<Read>> BY_BIT = new HashMap<>();
	private static final Map<Integer, List<Read>> BY_PLAYER = new HashMap<>();

	static
	{
		int[] none = {};
		List<Read> all = new ArrayList<>();
		all.add(new Read("plank sack", "Plank sack", true, null, null, PLANK_BITS, none, (v, out) -> pairs(v, PLANK_BITS, PLANKS, 1, out)));
		all.add(new Read("bolt pouch", "Bolt pouch", true, null, null, concat(BOLT_SLOTS, BOLT_COUNTS), none, (v, out) ->
		{
			for (int i = 0; i < BOLT_SLOTS.length; i++)
			{
				int type = v.bit(BOLT_SLOTS[i]);
				int item = type > 0 && type < BOLTS.length ? BOLTS[type] : -1;
				if (item > 0)
				{
					out.merge(item, (long) v.bit(BOLT_COUNTS[i]), Long::sum);
				}
			}
		}));
		all.add(new Read("scroll book", "Master scroll book", true, null, null, SCROLL_BITS, none, (v, out) -> pairs(v, SCROLL_BITS, SCROLLS, 1, out)));
		all.add(new Read("spool", "Bow string spool", true, null, null, new int[]{VarbitID.BOWSTRING_SPOOL_CHARGES}, none,
			(v, out) -> put(out, ItemID.BOW_STRING, v.bit(VarbitID.BOWSTRING_SPOOL_CHARGES))));
		all.add(new Read("quiver", "Dizana's quiver", true, null, null, none,
			new int[]{VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO, VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT},
			(v, out) -> put(out, v.player(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO), v.player(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT))));

		all.add(new Read("essence", "Essence pouches", true, null, null, concat(POUCH_COUNTS, POUCH_TYPES), none, (v, out) ->
		{
			for (int i = 0; i < POUCH_COUNTS.length; i++)
			{
				int type = v.bit(POUCH_TYPES[i]);
				put(out, type > 0 && type < ESSENCES.length ? ESSENCES[type] : ItemID.BLANKRUNE_HIGH, v.bit(POUCH_COUNTS[i]));
			}
		}));

		all.add(new Read("kept:leprechaun", "Tool leprechaun", false, Kind.KEPT, null, LEPRECHAUN_BITS, none, Reads::leprechaun));
		all.add(new Read("kept:furnace", "Blast Furnace", false, Kind.KEPT, new int[]{1940, 4962, 0}, FURNACE_BITS, none,
			(v, out) -> pairs(v, FURNACE_BITS, FURNACE, 1, out)));
		all.add(new Read("kept:fossils", "Fossil storage", false, Kind.KEPT, new int[]{3741, 3803, 0}, FOSSIL_BITS, none,
			(v, out) -> pairs(v, FOSSIL_BITS, FOSSILS, 1, out)));
		all.add(new Read("kept:well", "Vyre well", false, Kind.KEPT, new int[]{3672, 3219, 0}, new int[]{VarbitID.TOB_LOBBY_WELL_CONTENTS}, none, (v, out) ->
		{
			int vials = v.bit(VarbitID.TOB_LOBBY_WELL_CONTENTS);
			put(out, ItemID.VIAL_BLOOD, vials);
			put(out, ItemID.BLOODRUNE, vials * 200);
		}));
		all.add(new Read("kept:elnock", "Elnock Inquisitor", false, Kind.KEPT, null,
			new int[]{VarbitID.II_STORED_NET, VarbitID.II_STORED_REPELLENT, VarbitID.II_STORED_IMPLING_JARS}, none, (v, out) ->
		{
			int net = v.bit(VarbitID.II_STORED_NET);
			put(out, net == 1 ? ItemID.HUNTING_BUTTERFLY_NET : ItemID.II_MAGIC_BUTTERFLY_NET, net == 0 ? 0 : 1);
			put(out, ItemID.II_IMP_REPELLENT, v.bit(VarbitID.II_STORED_REPELLENT));
			put(out, ItemID.II_IMPLING_JAR, v.bit(VarbitID.II_STORED_IMPLING_JARS));
		}));
		all.add(new Read("kept:annette", "Annette's drift nets", false, Kind.KEPT, null, new int[]{VarbitID.FOSSIL_DRIFTNET_STORE}, none,
			(v, out) -> put(out, ItemID.FOSSIL_DRIFT_NET, v.bit(VarbitID.FOSSIL_DRIFTNET_STORE))));
		all.add(new Read("kept:statue", "Pickaxe statue", false, Kind.KEPT, null, new int[]{VarbitID.TOA_PICKAXE_STORED}, none, (v, out) ->
		{
			int t = v.bit(VarbitID.TOA_PICKAXE_STORED);
			if (t > 0 && t < PICKAXES.length)
			{
				put(out, PICKAXES[t], 1);
			}
		}));

		all.add(coffer("coffer:nmz", "Nightmare Zone coffer", new int[]{2608, 3115, 0}, VarbitID.NZONE_CASH, 1000));
		all.add(coffer("coffer:furnace", "Blast Furnace coffer", new int[]{1940, 4962, 0}, VarbitID.BLAST_FURNACE_COFFER, 1));
		all.add(coffer("coffer:miscellania", "Miscellania coffer", new int[]{2501, 3859, 1}, VarbitID.MISC_COFFERS, 1));
		all.add(coffer("coffer:lms", "Last Man Standing coffer", new int[]{3138, 3635, 0}, VarbitID.BR_COFFER, 1000));
		all.add(new Read("coffer:scar", "Scar essence mine coffer", false, Kind.COFFER, null, none, new int[]{VarPlayerID.SCAR_ESSENCEMINE_COFFER},
			(v, out) -> put(out, ItemID.COINS, v.player(VarPlayerID.SCAR_ESSENCEMINE_COFFER))));
		ALL = Collections.unmodifiableList(all);
		for (Read r : ALL)
		{
			r.bits.forEach(b -> BY_BIT.computeIfAbsent(b, k -> new ArrayList<>()).add(r));
			r.players.forEach(p -> BY_PLAYER.computeIfAbsent(p, k -> new ArrayList<>()).add(r));
		}
	}

	private Reads()
	{
	}

	/** Whether a store is read from the game's counters rather than from what it said. */
	static boolean live(String key)
	{
		for (Read r : ALL)
		{
			if (r.key.equals(key))
			{
				return true;
			}
		}
		return false;
	}

	/** The reads a changed variable touches: a varbit id, or -1 and a varp id. */
	static List<Read> touched(int bit, int player)
	{
		List<Read> l = bit >= 0 ? BY_BIT.get(bit) : BY_PLAYER.get(player);
		return l == null ? Collections.emptyList() : l;
	}

	private static Read coffer(String key, String name, int[] at, int bit, int times)
	{
		return new Read(key, name, false, Kind.COFFER, at, new int[]{bit}, new int[]{},
			(v, out) -> put(out, ItemID.COINS, (long) v.bit(bit) * times));
	}

	private static void leprechaun(Vars v, Map<Integer, Long> out)
	{
		put(out, ItemID.RAKE, v.bit(VarbitID.FARMING_TOOLS_RAKE) + v.bit(VarbitID.FARMING_TOOLS_EXTRARAKES) * 2);
		put(out, ItemID.DIBBER, v.bit(VarbitID.FARMING_TOOLS_DIBBER) + v.bit(VarbitID.FARMING_TOOLS_EXTRADIBBERS) * 2);
		put(out, ItemID.SPADE, v.bit(VarbitID.FARMING_TOOLS_SPADE) + v.bit(VarbitID.FARMING_TOOLS_EXTRASPADES) * 2);
		put(out, v.bit(VarbitID.FARMING_TOOLS_FAIRYSECATEURS) == 1 ? ItemID.FAIRY_ENCHANTED_SECATEURS : ItemID.SECATEURS,
			v.bit(VarbitID.FARMING_TOOLS_SECATEURS) + v.bit(VarbitID.FARMING_TOOLS_EXTRASECATEURS) * 2);
		int can = v.bit(VarbitID.FARMING_TOOLS_WATERINGCAN);
		if (can > 0 && can < WATERING_CANS.length)
		{
			put(out, WATERING_CANS[can], 1);
		}
		put(out, ItemID.GARDENING_TROWEL, v.bit(VarbitID.FARMING_TOOLS_TROWEL) + v.bit(VarbitID.FARMING_TOOLS_EXTRATROWELS) * 2);
		put(out, ItemID.PLANT_CURE, v.bit(VarbitID.FARMING_TOOLS_PLANTCURE));
		put(out, ItemID.BUCKET_EMPTY, v.bit(VarbitID.FARMING_TOOLS_BUCKETS) + v.bit(VarbitID.FARMING_TOOLS_EXTRABUCKETS) * 32
			+ v.bit(VarbitID.FARMING_TOOLS_EXTRA2BUCKETS) * 256);
		put(out, ItemID.BUCKET_COMPOST, v.bit(VarbitID.FARMING_TOOLS_COMPOST) + v.bit(VarbitID.FARMING_TOOLS_EXTRACOMPOST) * 256);
		put(out, ItemID.BUCKET_SUPERCOMPOST, v.bit(VarbitID.FARMING_TOOLS_SUPERCOMPOST) + v.bit(VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST) * 256);
		put(out, ItemID.BUCKET_ULTRACOMPOST, v.bit(VarbitID.FARMING_TOOLS_ULTRACOMPOST));
		int bucket = v.bit(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE);
		if (bucket > 0)
		{
			put(out, bucket == 1 ? ItemID.BOTTOMLESS_COMPOST_BUCKET : ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 1);
		}
	}

	private static void pairs(Vars v, int[] bits, int[] items, int times, Map<Integer, Long> out)
	{
		for (int i = 0; i < bits.length; i++)
		{
			put(out, items[i], (long) v.bit(bits[i]) * times);
		}
	}

	private static void put(Map<Integer, Long> out, int item, long qty)
	{
		if (item > 0 && qty > 0)
		{
			out.merge(item, qty, Long::sum);
		}
	}

	private static int[] concat(int[] a, int[] b)
	{
		int[] c = Arrays.copyOf(a, a.length + b.length);
		System.arraycopy(b, 0, c, a.length, b.length);
		return c;
	}
}

package com.codex.nomad;

import com.codex.nomad.core.Nomad;
import com.codex.nomad.core.Route;
import com.codex.nomad.core.Store;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Scene;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Reads the game for the route: what is true for good (quests, levels, unlocks) and what is true
 * this moment (items, place, coins, chat, furniture), ticks the step in hand when it holds, and
 * guides the player to it with the hint arrow, outlines on everything to click and the Shortest Path plugin.
 */
final class RouteGuide
{
	/** Ticks a game message counts as heard for a chat check. */
	private static final int HEARD_TICKS = 10;
	/** Ticks a reading of quests and levels is reused before it is taken again. */
	private static final int ACCOUNT_TICKS = 5;
	private static final String[][] TIERS = {
		{"easy", String.valueOf(VarbitID.CA_THRESHOLD_EASY)},
		{"medium", String.valueOf(VarbitID.CA_THRESHOLD_MEDIUM)},
		{"hard", String.valueOf(VarbitID.CA_THRESHOLD_HARD)},
		{"elite", String.valueOf(VarbitID.CA_THRESHOLD_ELITE)},
		{"master", String.valueOf(VarbitID.CA_THRESHOLD_MASTER)},
		{"grandmaster", String.valueOf(VarbitID.CA_THRESHOLD_GRANDMASTER)},
	};

	private final Client client;
	private final EventBus eventBus;
	private final Route route;
	private final IntFunction<String> name;
	private final Map<String, Quest> quests = new HashMap<>();
	private final Map<String, Skill> skills = new HashMap<>();
	private final Deque<Object[]> heard = new ArrayDeque<>();

	private Route.Account account;
	private int accountTick = Integer.MIN_VALUE;
	private WorldPoint pathed;
	private WorldPoint arrowPoint;
	private NPC arrowNpc;
	/** What to click for the step in hand, for the overlays. */
	private Route.Lead lead = new Route.Lead();
	/** Objects in the scene to click, found by the last scan. */
	private List<TileObject> objects = Collections.emptyList();
	/** Ground items to pick up, found by the last scan: the tile and the item's name. */
	private List<Object[]> ground = Collections.emptyList();

	RouteGuide(Client client, EventBus eventBus, Route route, IntFunction<String> name)
	{
		this.client = client;
		this.eventBus = eventBus;
		this.route = route;
		this.name = name;
		for (Quest q : Quest.values())
		{
			quests.put(q.getName(), q);
		}
		for (Skill s : Skill.values())
		{
			skills.put(s.getName(), s);
		}
	}

	/** Forget the last reading, so the next one is fresh. */
	void stale()
	{
		accountTick = Integer.MIN_VALUE;
	}

	void heard(String message)
	{
		heard.addLast(new Object[]{client.getTickCount(), message.toLowerCase(Locale.ENGLISH)});
		while (heard.size() > 40)
		{
			heard.removeFirst();
		}
	}

	Route.Account account()
	{
		int now = client.getTickCount();
		if (account != null && now - accountTick < ACCOUNT_TICKS && now >= accountTick)
		{
			return account;
		}
		accountTick = now;
		boolean in = client.getGameState() == GameState.LOGGED_IN;
		Map<String, QuestState> states = new HashMap<>();
		account = new Route.Account()
		{
			private QuestState state(String quest)
			{
				Quest q = quests.get(quest);
				if (!in || q == null)
				{
					return QuestState.NOT_STARTED;
				}
				return states.computeIfAbsent(quest, k -> q.getState(client));
			}

			@Override
			public boolean questDone(String quest)
			{
				return state(quest) == QuestState.FINISHED;
			}

			@Override
			public boolean questStarted(String quest)
			{
				return state(quest) != QuestState.NOT_STARTED;
			}

			@Override
			public int level(String skill)
			{
				Skill s = skills.get(skill);
				return in && s != null ? client.getRealSkillLevel(s) : 0;
			}

			@Override
			public int questPoints()
			{
				return in ? client.getVarpValue(VarPlayerID.QP) : 0;
			}

			@Override
			public int combat()
			{
				Player me = client.getLocalPlayer();
				return in && me != null ? me.getCombatLevel() : 0;
			}

			@Override
			public int varbit(int id)
			{
				return in ? client.getVarbitValue(id) : 0;
			}

			@Override
			public int varp(int id)
			{
				return in ? client.getVarpValue(id) : 0;
			}

			@Override
			public boolean tierDone(String tier)
			{
				for (String[] t : TIERS)
				{
					if (t[0].equals(tier))
					{
						int need = client.getVarbitValue(Integer.parseInt(t[1]));
						return in && need > 0 && client.getVarbitValue(VarbitID.CA_POINTS) >= need;
					}
				}
				return false;
			}
		};
		return account;
	}

	Route.Moment moment(Nomad n, int[] here)
	{
		Set<String> held = new HashSet<>();
		for (int id : n.carried().keySet())
		{
			held.add(name.apply(id).toLowerCase(Locale.ENGLISH));
		}
		int now = client.getTickCount();
		return new Route.Moment()
		{
			private Set<Integer> seen;
			private Set<String> owned;

			@Override
			public boolean held(String item)
			{
				return held.contains(item);
			}

			@Override
			public boolean owned(String item)
			{
				if (owned == null)
				{
					owned = new HashSet<>(held);
					for (Store s : n.stores())
					{
						for (int id : s.items.keySet())
						{
							owned.add(name.apply(id).toLowerCase(Locale.ENGLISH));
						}
					}
				}
				return owned.contains(item);
			}

			@Override
			public int[] here()
			{
				return here;
			}

			@Override
			public List<String> inventory()
			{
				List<String> out = new ArrayList<>();
				ItemContainer inv = client.getItemContainer(InventoryID.INV);
				if (inv != null)
				{
					for (Item i : inv.getItems())
					{
						if (i.getId() > 0 && i.getQuantity() > 0)
						{
							out.add(name.apply(i.getId()).toLowerCase(Locale.ENGLISH));
						}
					}
				}
				return out;
			}

			@Override
			public long coins()
			{
				ItemContainer inv = client.getItemContainer(InventoryID.INV);
				return inv == null ? 0 : inv.count(ItemID.COINS);
			}

			@Override
			public boolean heard(String text)
			{
				String t = text.toLowerCase(Locale.ENGLISH);
				for (Object[] h : heard)
				{
					if (now - (int) h[0] <= HEARD_TICKS && ((String) h[1]).contains(t))
					{
						return true;
					}
				}
				return false;
			}

			@Override
			public boolean deathbank()
			{
				return n.deathbank() != null;
			}

			@Override
			public boolean sees(int[] objects)
			{
				if (seen == null)
				{
					seen = sceneObjects();
				}
				for (int id : objects)
				{
					if (seen.contains(id))
					{
						return true;
					}
				}
				return false;
			}
		};
	}

	/** Every game object id in the scene on the player's plane. */
	private Set<Integer> sceneObjects()
	{
		Set<Integer> out = new HashSet<>();
		Scene scene = client.getTopLevelWorldView().getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		int plane = client.getTopLevelWorldView().getPlane();
		if (tiles == null || plane < 0 || plane >= tiles.length)
		{
			return out;
		}
		for (Tile[] row : tiles[plane])
		{
			for (Tile t : row)
			{
				if (t == null)
				{
					continue;
				}
				for (GameObject o : t.getGameObjects())
				{
					if (o != null)
					{
						out.add(o.getId());
					}
				}
				if (t.getWallObject() != null)
				{
					out.add(t.getWallObject().getId());
				}
				if (t.getDecorativeObject() != null)
				{
					out.add(t.getDecorativeObject().getId());
				}
				if (t.getGroundObject() != null)
				{
					out.add(t.getGroundObject().getId());
				}
			}
		}
		return out;
	}

	/** Steps in hand that hold now; the caller ticks them. */
	List<Route.Step> observe(Nomad n, int[] here)
	{
		if (n == null || !n.following || client.getGameState() != GameState.LOGGED_IN)
		{
			return Collections.emptyList();
		}
		return route.observe(n.ticked(), account(), moment(n, here));
	}

	/** The step in hand, or null when not following or finished. */
	Route.Step current(Nomad n)
	{
		return n == null || !n.following ? null : route.current(n.ticked(), account());
	}

	WorldPoint target(Route.Step s)
	{
		int[] t = s == null ? null : route.target(s, account());
		return t == null ? null : new WorldPoint(t[0], t[1], t[2]);
	}

	Route.Lead lead()
	{
		return lead;
	}

	List<TileObject> objects()
	{
		return objects;
	}

	List<Object[]> ground()
	{
		return ground;
	}

	/** True when this NPC is one the step in hand names. */
	boolean wanted(NPC npc)
	{
		return wanted(npc, lead);
	}

	private static boolean wanted(NPC npc, Route.Lead lead)
	{
		if (lead.npcIds.contains(npc.getId()))
		{
			return true;
		}
		String n = npc.getName();
		if (n == null)
		{
			return false;
		}
		for (String want : lead.npcs)
		{
			if (want.equalsIgnoreCase(n))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Points the way to the step in hand: the hint arrow at a named person in sight, else the thing
	 * to click, else the place; outlines everything to click; and asks Shortest Path for the way.
	 */
	void guide(Route.Step s, boolean arrow, boolean outline, boolean path)
	{
		WorldPoint target = target(s);
		Route.Lead l = route.lead(s, account());
		lead = outline ? l : new Route.Lead();
		scan(l);
		Player me = client.getLocalPlayer();
		NPC npc = null;
		int best = Integer.MAX_VALUE;
		if (me != null && (!l.npcs.isEmpty() || !l.npcIds.isEmpty()))
		{
			for (NPC c : client.getTopLevelWorldView().npcs())
			{
				if (wanted(c, l))
				{
					int d = c.getWorldLocation().distanceTo(me.getWorldLocation());
					if (d < best)
					{
						best = d;
						npc = c;
					}
				}
			}
		}
		WorldPoint point = near(target);
		if (npc == null && me != null)
		{
			best = Integer.MAX_VALUE;
			for (TileObject o : objects)
			{
				int d = o.getWorldLocation().distanceTo(me.getWorldLocation());
				if (d < best)
				{
					best = d;
					point = o.getWorldLocation();
				}
			}
		}
		if (!outline)
		{
			objects = Collections.emptyList();
			ground = Collections.emptyList();
		}
		pointArrow(arrow ? npc : null, arrow && npc == null ? point : null);
		pathTo(path ? target : null);
	}

	/** Points the way to a place off the route: a deathpile to save, or the next stop for a packing list. */
	void head(WorldPoint target, boolean arrow, boolean path)
	{
		lead = new Route.Lead();
		objects = Collections.emptyList();
		ground = Collections.emptyList();
		pointArrow(null, arrow ? near(target) : null);
		pathTo(path ? target : null);
	}

	/** Finds the objects and ground items the step asks for in the scene, on the player's plane. */
	private void scan(Route.Lead l)
	{
		if (l.objects.isEmpty() && l.ground.isEmpty())
		{
			objects = Collections.emptyList();
			ground = Collections.emptyList();
			return;
		}
		if (client.getTickCount() % 2 != 0 && (!objects.isEmpty() || !ground.isEmpty()))
		{
			return;
		}
		Set<Integer> ids = new HashSet<>(l.objects);
		Set<String> items = new HashSet<>();
		for (String g : l.ground)
		{
			items.add(g.toLowerCase(Locale.ENGLISH));
		}
		List<TileObject> found = new ArrayList<>();
		List<Object[]> lying = new ArrayList<>();
		Scene scene = client.getTopLevelWorldView().getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		int plane = client.getTopLevelWorldView().getPlane();
		if (tiles != null && plane >= 0 && plane < tiles.length)
		{
			for (Tile[] row : tiles[plane])
			{
				for (Tile t : row)
				{
					if (t == null)
					{
						continue;
					}
					if (!ids.isEmpty())
					{
						for (GameObject o : t.getGameObjects())
						{
							if (o != null && ids.contains(o.getId()) && !found.contains(o))
							{
								found.add(o);
							}
						}
						for (TileObject o : new TileObject[]{t.getWallObject(), t.getDecorativeObject(), t.getGroundObject()})
						{
							if (o != null && ids.contains(o.getId()))
							{
								found.add(o);
							}
						}
					}
					if (!items.isEmpty() && t.getGroundItems() != null)
					{
						for (TileItem i : t.getGroundItems())
						{
							String n = name.apply(i.getId()).toLowerCase(Locale.ENGLISH);
							if (items.contains(n))
							{
								lying.add(new Object[]{t, name.apply(i.getId())});
							}
						}
					}
				}
			}
		}
		objects = found;
		ground = lying;
	}

	/** The target, if it is close enough for the hint arrow to show. */
	private WorldPoint near(WorldPoint target)
	{
		Player me = client.getLocalPlayer();
		if (target == null || me == null)
		{
			return null;
		}
		WorldPoint at = me.getWorldLocation();
		if (at.getPlane() != target.getPlane() || at.distanceTo2D(target) > 60 || at.distanceTo2D(target) <= 1)
		{
			return null;
		}
		return target;
	}

	private void pointArrow(NPC npc, WorldPoint point)
	{
		boolean ours = arrowNpc != null && arrowNpc == client.getHintArrowNpc()
			|| arrowPoint != null && arrowPoint.equals(client.getHintArrowPoint());
		if (npc != null)
		{
			if (npc != arrowNpc || !ours)
			{
				if (ours || !client.hasHintArrow())
				{
					client.setHintArrow(npc);
					arrowNpc = npc;
					arrowPoint = null;
				}
			}
			return;
		}
		if (point != null)
		{
			if (!point.equals(arrowPoint) || !ours)
			{
				if (ours || !client.hasHintArrow())
				{
					client.setHintArrow(point);
					arrowPoint = point;
					arrowNpc = null;
				}
			}
			return;
		}
		if (ours)
		{
			client.clearHintArrow();
		}
		arrowNpc = null;
		arrowPoint = null;
	}

	private void pathTo(WorldPoint target)
	{
		if (target == null ? pathed == null : target.equals(pathed))
		{
			return;
		}
		if (target == null)
		{
			eventBus.post(new PluginMessage("shortestpath", "clear"));
		}
		else
		{
			Map<String, Object> data = new HashMap<>();
			data.put("target", target);
			eventBus.post(new PluginMessage("shortestpath", "path", data));
		}
		pathed = target;
	}

	/** Takes down the arrow and the path. */
	void stop()
	{
		pointArrow(null, null);
		pathTo(null);
		lead = new Route.Lead();
		objects = Collections.emptyList();
		ground = Collections.emptyList();
	}

	/** "212 tiles north-east", or null. */
	static String way(int[] here, WorldPoint target)
	{
		if (here == null || target == null)
		{
			return null;
		}
		int dx = target.getX() - here[0];
		int dy = target.getY() - here[1];
		int d = Math.max(Math.abs(dx), Math.abs(dy));
		if (d <= 2 && here[2] == target.getPlane())
		{
			return "Here";
		}
		if (d <= 2)
		{
			return target.getPlane() > here[2] ? "Upstairs" : "Downstairs";
		}
		String ns = dy > d / 2 ? "north" : dy < -d / 2 ? "south" : "";
		String ew = dx > d / 2 ? "east" : dx < -d / 2 ? "west" : "";
		String dir = ns.isEmpty() ? ew : ew.isEmpty() ? ns : ns + "-" + ew;
		return d + " tiles " + dir;
	}
}

package com.codex.nomad;

import com.codex.nomad.core.Kind;
import com.codex.nomad.core.Nomad;
import com.codex.nomad.core.Store;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Places that keep things for you and only say so in words: Bert's Sandstorm machine in Yanille,
 * the balloon log crates, the Forestry log storage, Nulodion holding a decayed cannon and
 * Eyatlalli holding a frozen weapon. The wording follows Dude, Where's My Stuff (BSD 2-Clause).
 */
final class Sayings
{
	static final String SANDSTORM = "kept:sandstorm";
	static final String BALLOON = "kept:balloon";
	static final String FORESTRY = "kept:forestry";
	static final String NULODION = "kept:nulodion";
	static final String EYATLALLI = "kept:eyatlalli";

	private static final Pattern SAND_CHECK = Pattern.compile(
		"I have (\\d+) of your buckets and you've ground enough sandstone for (\\d+) buckets of sand");
	private static final Pattern SAND_STONE = Pattern.compile("sandstone (?:equivalent to|for) (\\d+|one) buckets? of sand");
	private static final Pattern SAND_BUCKETS = Pattern.compile("holding onto (\\d+|one) buckets? for ya");
	private static final Pattern CRATE_CHECK = Pattern.compile(
		"This crate currently contains (\\d+) logs,? (\\d+) oak logs,? (\\d+) willow logs,? (\\d+) yew logs and (\\d+) magic logs");
	private static final Pattern CRATE_PUT = Pattern.compile("You put the (.*) in the crate\\. You now have (\\d+) stored");
	private static final Pattern CRATE_LEFT = Pattern.compile("You have (\\d+) sets of (.*) left in storage");
	private static final Pattern FROZEN = Pattern.compile("Eyatlalli is holding onto your ([^.]+)\\.");
	private static final int[] CRATE_LOGS = {ItemID.LOGS, ItemID.OAK_LOGS, ItemID.WILLOW_LOGS, ItemID.YEW_LOGS, ItemID.MAGIC_LOGS};
	private static final String[] CRATE_NAMES = {"logs", "oak logs", "willow logs", "yew logs", "magic logs"};
	private static final Map<String, Integer> FORESTRY_LOGS = new LinkedHashMap<>();

	static
	{
		FORESTRY_LOGS.put("Oak", ItemID.OAK_LOGS);
		FORESTRY_LOGS.put("Willow", ItemID.WILLOW_LOGS);
		FORESTRY_LOGS.put("Yew", ItemID.YEW_LOGS);
		FORESTRY_LOGS.put("Maple", ItemID.MAPLE_LOGS);
		FORESTRY_LOGS.put("Magic", ItemID.MAGIC_LOGS);
		FORESTRY_LOGS.put("Teak", ItemID.TEAK_LOGS);
		FORESTRY_LOGS.put("Mahogany", ItemID.MAHOGANY_LOGS);
		FORESTRY_LOGS.put("Redwood", ItemID.REDWOOD_LOGS);
		FORESTRY_LOGS.put("Arctic pine", ItemID.ARCTIC_PINE_LOG);
	}

	private Sayings()
	{
	}

	private static String plain(String text)
	{
		return text.replace("<br>", " ").replaceAll("<[^>]+>", "").replace(",", "").replaceAll("\\s+", " ").trim();
	}

	private static long count(String s)
	{
		return s.equals("one") ? 1 : Long.parseLong(s);
	}

	/**
	 * Reads words shown in a dialogue or message box.
	 *
	 * @param gained what arrived in the inventory this tick, for a withdrawal from the Sandstorm
	 * @return true if a store changed
	 */
	static boolean shown(String text, Map<Integer, Long> gained, Nomad n, long now)
	{
		if (text == null || text.isEmpty())
		{
			return false;
		}
		String t = plain(text);
		Matcher m = SAND_CHECK.matcher(t);
		if (m.find())
		{
			return sand(n, now, Long.parseLong(m.group(1)), Long.parseLong(m.group(2)));
		}
		m = SAND_STONE.matcher(t);
		if (m.find())
		{
			return sand(n, now, held(n, SANDSTORM, ItemID.BUCKET_EMPTY), count(m.group(1)));
		}
		m = SAND_BUCKETS.matcher(t);
		if (m.find())
		{
			return sand(n, now, count(m.group(1)), held(n, SANDSTORM, ItemID.BUCKET_SAND));
		}
		if (t.startsWith("If ya need any more sand"))
		{
			long took = gained.getOrDefault(ItemID.BUCKET_SAND, 0L);
			return took > 0 && n.store(SANDSTORM) != null && sand(n, now,
				Math.max(0, held(n, SANDSTORM, ItemID.BUCKET_EMPTY) - took), Math.max(0, held(n, SANDSTORM, ItemID.BUCKET_SAND) - took));
		}
		m = CRATE_CHECK.matcher(t);
		if (m.find())
		{
			Map<Integer, Long> items = new LinkedHashMap<>();
			for (int i = 0; i < CRATE_LOGS.length; i++)
			{
				items.put(CRATE_LOGS[i], Long.parseLong(m.group(i + 1)));
			}
			return file(n, BALLOON, "Balloon log crates", items, now);
		}
		m = CRATE_PUT.matcher(t);
		if (m.find())
		{
			return crate(n, m.group(1), Long.parseLong(m.group(2)), now);
		}
		if (t.startsWith("Your log storage contains:"))
		{
			Map<Integer, Long> items = new LinkedHashMap<>();
			for (Map.Entry<String, Integer> e : FORESTRY_LOGS.entrySet())
			{
				Matcher l = Pattern.compile(e.getKey().replace(" ", "\\s+") + "\\s+logs?:\\s+(\\d+)").matcher(t);
				if (l.find())
				{
					items.put(e.getValue(), Long.parseLong(l.group(1)));
				}
			}
			return file(n, FORESTRY, "Forestry log storage", items, now);
		}
		return false;
	}

	/**
	 * Hears a game message.
	 *
	 * @param weapon the item in the weapon slot now, or -1
	 * @param byName finds an item by its exact name, or -1
	 * @return true if a store changed
	 */
	static boolean heard(String message, int weapon, Function<String, Integer> byName, Nomad n, long now)
	{
		Matcher m = CRATE_LEFT.matcher(message);
		if (m.find())
		{
			return crate(n, m.group(2), Long.parseLong(m.group(1)), now);
		}
		if (message.startsWith("Your cannon has decayed"))
		{
			Map<Integer, Long> parts = new LinkedHashMap<>();
			parts.put(ItemID.TWPART1, 1L);
			parts.put(ItemID.TWPART2, 1L);
			parts.put(ItemID.TWPART3, 1L);
			parts.put(ItemID.TWPART4, 1L);
			return file(n, NULODION, "Nulodion (decayed cannon)", parts, now);
		}
		if (message.startsWith("The dwarf gives you a new cannon"))
		{
			return file(n, NULODION, "Nulodion (decayed cannon)", new HashMap<>(), now);
		}
		if (message.contains("Your weapon freezes over."))
		{
			Map<Integer, Long> held = new HashMap<>();
			if (weapon > 0)
			{
				held.put(weapon, 1L);
			}
			return file(n, EYATLALLI, "Eyatlalli (frozen weapon)", held, now);
		}
		if (message.startsWith("Eyatlalli returns your lost weapon") || message.startsWith("Eyatlalli retrieves your weapon")
			|| message.startsWith("You retrieve your weapon") || message.startsWith("As the icicle bursts, your weapon"))
		{
			return file(n, EYATLALLI, "Eyatlalli (frozen weapon)", new HashMap<>(), now);
		}
		m = FROZEN.matcher(message);
		if (m.find())
		{
			int id = byName.apply(m.group(1));
			Store s = n.store(EYATLALLI);
			if (id <= 0 && s != null && !s.items.isEmpty())
			{
				return false;
			}
			Map<Integer, Long> held = new HashMap<>();
			if (id > 0)
			{
				held.put(id, 1L);
			}
			return file(n, EYATLALLI, "Eyatlalli (frozen weapon)", held, now);
		}
		return false;
	}

	private static long held(Nomad n, String key, int id)
	{
		Store s = n.store(key);
		return s == null ? 0 : s.items.getOrDefault(id, 0L);
	}

	private static boolean sand(Nomad n, long now, long buckets, long sand)
	{
		Map<Integer, Long> items = new LinkedHashMap<>();
		items.put(ItemID.BUCKET_EMPTY, buckets);
		items.put(ItemID.BUCKET_SAND, sand);
		return file(n, SANDSTORM, "Bert's Sandstorm", items, now);
	}

	private static boolean crate(Nomad n, String name, long qty, long now)
	{
		for (int i = 0; i < CRATE_NAMES.length; i++)
		{
			if (CRATE_NAMES[i].equalsIgnoreCase(name))
			{
				Store s = n.store(BALLOON);
				Map<Integer, Long> items = s == null ? new LinkedHashMap<>() : new LinkedHashMap<>(s.items);
				items.put(CRATE_LOGS[i], qty);
				return file(n, BALLOON, "Balloon log crates", items, now);
			}
		}
		return false;
	}

	/** Files what a place holds, dropping the place once it holds nothing. */
	private static boolean file(Nomad n, String key, String name, Map<Integer, Long> items, long now)
	{
		items.values().removeIf(q -> q == null || q <= 0);
		Store s = n.store(key);
		if (items.isEmpty())
		{
			if (s == null)
			{
				return false;
			}
			n.remove(key);
			return true;
		}
		if (s == null)
		{
			s = new Store(key, Kind.KEPT, name);
			n.put(s);
		}
		else if (items.equals(s.items))
		{
			s.seen = now;
			return false;
		}
		s.fill(items, now);
		return true;
	}
}

package com.codex.nomad;

import com.codex.nomad.core.Death;
import com.codex.nomad.core.Fetch;
import com.codex.nomad.core.Idle;
import com.codex.nomad.core.Items;
import com.codex.nomad.core.Kept;
import com.codex.nomad.core.Kind;
import com.codex.nomad.core.Nomad;
import com.codex.nomad.core.Notary;
import com.codex.nomad.core.Route;
import com.codex.nomad.core.StashBook;
import com.codex.nomad.core.Store;
import com.codex.nomad.core.Trip;
import com.codex.nomad.ui.Format;
import com.codex.nomad.ui.View;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Builds the panel's {@link View} from the account's data, on the client thread. */
final class Views
{
	/** What the game knows about items, asked through the plugin. */
	interface Lookup
	{
		String name(int id);

		long price(int id);

		boolean stackable(int id);

		boolean noted(int id);

		/** The item's common form: unnoted, no placeholder. */
		int canon(int id);
	}

	/** Items never called dead weight: the containers themselves. */
	static final java.util.Set<Integer> CONTAINERS = new java.util.HashSet<>(java.util.Arrays.asList(
		net.runelite.api.gameval.ItemID.LOOTING_BAG, net.runelite.api.gameval.ItemID.LOOTING_BAG_OPEN,
		net.runelite.api.gameval.ItemID.BH_RUNE_POUCH, net.runelite.api.gameval.ItemID.BH_RUNE_POUCH_TROUVER,
		net.runelite.api.gameval.ItemID.DIVINE_RUNE_POUCH, net.runelite.api.gameval.ItemID.DIVINE_RUNE_POUCH_TROUVER,
		net.runelite.api.gameval.ItemID.COINS, net.runelite.api.gameval.ItemID.SLAYER_HERB_SACK,
		net.runelite.api.gameval.ItemID.SLAYER_HERB_SACK_OPEN, net.runelite.api.gameval.ItemID.SEED_BOX,
		net.runelite.api.gameval.ItemID.SEED_BOX_OPEN, net.runelite.api.gameval.ItemID.TACKLE_BOX,
		net.runelite.api.gameval.ItemID.HUNTSMANS_KIT, net.runelite.api.gameval.ItemID.FORESTRY_KIT,
		net.runelite.api.gameval.ItemID.PLANK_SACK, net.runelite.api.gameval.ItemID.XBOWS_BOLT_POUCH,
		net.runelite.api.gameval.ItemID.BOOKOFSCROLLS_CHARGED, net.runelite.api.gameval.ItemID.BOOKOFSCROLLS_EMPTY,
		net.runelite.api.gameval.ItemID.BOWSTRING_SPOOL, net.runelite.api.gameval.ItemID.MM_PREPOT_DEVICE,
		net.runelite.api.gameval.ItemID.RCU_POUCH_SMALL, net.runelite.api.gameval.ItemID.RCU_POUCH_MEDIUM,
		net.runelite.api.gameval.ItemID.RCU_POUCH_LARGE, net.runelite.api.gameval.ItemID.RCU_POUCH_GIANT,
		net.runelite.api.gameval.ItemID.RCU_POUCH_COLOSSAL, net.runelite.api.gameval.ItemID.COAL_BAG,
		net.runelite.api.gameval.ItemID.COAL_BAG_OPEN, net.runelite.api.gameval.ItemID.GEM_BAG,
		net.runelite.api.gameval.ItemID.GEM_BAG_OPEN, net.runelite.api.gameval.ItemID.FISH_BARREL_CLOSED,
		net.runelite.api.gameval.ItemID.FISH_BARREL_OPEN, net.runelite.api.gameval.ItemID.LOG_BASKET_CLOSED,
		net.runelite.api.gameval.ItemID.LOG_BASKET_OPEN,
		net.runelite.api.gameval.ItemID.BOTTOMLESS_COMPOST_BUCKET, net.runelite.api.gameval.ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED));

	/** The bags read from what the game says, with the items that are the bag itself. */
	private static final Map<String, int[]> HEARD = new LinkedHashMap<>();

	static
	{
		HEARD.put(HerbSack.NAME, new int[]{net.runelite.api.gameval.ItemID.SLAYER_HERB_SACK, net.runelite.api.gameval.ItemID.SLAYER_HERB_SACK_OPEN});
		HEARD.put(Bags.COAL, new int[]{net.runelite.api.gameval.ItemID.COAL_BAG, net.runelite.api.gameval.ItemID.COAL_BAG_OPEN});
		HEARD.put(Bags.GEMS, new int[]{net.runelite.api.gameval.ItemID.GEM_BAG, net.runelite.api.gameval.ItemID.GEM_BAG_OPEN});
		HEARD.put(Bags.FISH, new int[]{net.runelite.api.gameval.ItemID.FISH_BARREL_CLOSED, net.runelite.api.gameval.ItemID.FISH_BARREL_OPEN});
		HEARD.put(Bags.BUCKET, new int[]{net.runelite.api.gameval.ItemID.BOTTOMLESS_COMPOST_BUCKET, net.runelite.api.gameval.ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED});
		HEARD.put(Bags.LOGS, new int[]{net.runelite.api.gameval.ItemID.LOG_BASKET_CLOSED, net.runelite.api.gameval.ItemID.LOG_BASKET_OPEN});
	}

	private Views()
	{
	}

	private static boolean carries(Nomad n, int[] ids)
	{
		for (int id : ids)
		{
			if (n.carried(Nomad.INVENTORY).getOrDefault(id, 0L) > 0)
			{
				return true;
			}
		}
		return false;
	}

	static View build(Nomad n, Lookup look, StashBook stash, Route route, Route.Account account, int[] here, int keep,
		long idleAfter, long now)
	{
		View v = new View();
		v.now = now;
		v.account = n.account;

		// ---- pack ----
		Map<Integer, Long> inv = n.carried(Nomad.INVENTORY);
		v.inventory = lines(inv, look);
		v.worn = lines(n.carried(Nomad.WORN), look);
		v.pouch = lines(n.carried(Nomad.RUNE_POUCH), look);
		List<View.Vessel> vessels = new ArrayList<>();
		for (String name : n.containers())
		{
			if (!name.equals(Nomad.INVENTORY) && !name.equals(Nomad.WORN) && !name.equals(Nomad.LOOTING_BAG)
				&& !name.equals(Nomad.RUNE_POUCH) && !n.carried(name).isEmpty())
			{
				View.Vessel vessel = new View.Vessel();
				vessel.name = name;
				vessel.items = lines(n.carried(name), look);
				vessel.seen = n.seenAt(name);
				vessels.add(vessel);
			}
		}
		// A bag the game only describes in words stays unknown until it is first checked.
		for (Map.Entry<String, int[]> bag : HEARD.entrySet())
		{
			if (!n.seen(bag.getKey()) && carries(n, bag.getValue()))
			{
				View.Vessel vessel = new View.Vessel();
				vessel.name = bag.getKey();
				vessel.unchecked = true;
				vessels.add(vessel);
			}
		}
		vessels.sort((a, b) -> a.name.compareTo(b.name));
		v.vessels = vessels;
		v.bagKnown = n.seen(Nomad.LOOTING_BAG);
		v.bag = lines(n.carried(Nomad.LOOTING_BAG), look);
		v.bagUsed = n.carried(Nomad.LOOTING_BAG).size();
		v.bagSeen = n.seenAt(Nomad.LOOTING_BAG);
		v.invUsed = slots(inv, look);
		Map<Integer, Long> carried = n.carried();
		v.carriedWorth = Items.worth(carried, look::price);
		v.keepCount = keep;
		Kept k = Kept.of(n.loose(), look::price, keep);
		v.dropNow = k.droppedWorth + Items.worth(n.inside(), look::price);
		v.keepNow = k.keptWorth;
		v.kept = lines(k.kept, look);

		// ---- perils ----
		List<View.Peril> perils = new ArrayList<>();
		for (Store s : n.stores(Kind.FLOOR))
		{
			View.Peril p = new View.Peril();
			p.kind = Kind.FLOOR;
			p.key = s.key;
			p.title = s.world == Nomad.RAID ? "Chambers of Xeric floor" : "On the floor, world " + s.world;
			p.note = roomNote(s.world == Nomad.RAID ? "Lost when you leave the raid" : "Gone when its timer runs out", room(s.items, inv, look), 28 - v.invUsed);
			p.note = shedNote(p.note, s.items, inv, look, room(s.items, inv, look) - (28 - v.invUsed));
			p.worth = Items.worth(s.items, look::price);
			p.until = s.until;
			p.count = s.items.size();
			perils.add(p);
		}
		perils.sort((a, b) -> Long.compare(a.until, b.until));
		for (Store s : n.stores(Kind.DEATHPILE))
		{
			View.Peril p = new View.Peril();
			p.kind = Kind.DEATHPILE;
			p.key = s.key;
			p.title = "Deathpile";
			p.note = roomNote("Lost when its timer runs out", room(s.items, inv, look), 28 - v.invUsed);
			p.note = shedNote(p.note, s.items, inv, look, room(s.items, inv, look) - (28 - v.invUsed));
			p.worth = Items.worth(s.items, look::price);
			p.ticksLeft = s.ticksLeft;
			p.count = s.items.size();
			perils.add(p);
		}
		Store bank = n.deathbank();
		if (bank != null)
		{
			View.Peril p = new View.Peril();
			p.kind = Kind.DEATHBANK;
			p.key = bank.key;
			p.title = "Deathbank: " + bank.name;
			String claim = Death.claim(bank.name);
			long fee = Death.fee(bank.name);
			long coins = n.carried(Nomad.INVENTORY).getOrDefault(net.runelite.api.gameval.ItemID.COINS, 0L);
			p.note = claim == null ? "Any unsafe death wipes it"
				: fee > coins ? claim + "; you carry " + Format.coins(coins) : claim + " · any unsafe death wipes it";
			p.worth = Items.worth(bank.items, look::price);
			p.exact = bank.exact;
			p.count = bank.items.size();
			perils.add(p);
		}
		long bagWorth = Items.worth(n.carried(Nomad.LOOTING_BAG), look::price);
		if (bagWorth > 0)
		{
			View.Peril p = new View.Peril();
			p.kind = Kind.OTHER;
			p.key = "bag";
			p.title = "Looting bag";
			p.note = "Empties only on death, or destroyed deep enough in the Wilderness";
			p.worth = bagWorth;
			p.count = v.bagUsed;
			perils.add(p);
		}
		v.perils = perils;

		// ---- dead weight ----
		Map<Integer, Long> idleSet = new LinkedHashMap<>(inv);
		v.idleAfter = idleAfter;
		List<View.IdleLine> idle = new ArrayList<>();
		for (Idle i : Idle.find(n, idleSet, look::stackable, CONTAINERS::contains, idleAfter))
		{
			View.IdleLine line = new View.IdleLine();
			line.item = line(i.item, i.qty, look);
			line.idleMs = i.idleMs;
			line.slots = i.slots;
			List<StashBook.Home> homes = stash.homes(look.canon(i.item));
			line.home = homes.isEmpty() ? null : homes.get(0).place;
			idle.add(line);
		}
		v.idle = idle;
		v.losses = losses(n, look);
		v.lostWorth = n.lostWorth;
		v.idleSlots = 0;
		for (View.IdleLine i : idle)
		{
			v.idleSlots += i.slots;
		}

		// ---- noting ----
		List<View.NoteLine> notes = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : inv.entrySet())
		{
			int id = e.getKey();
			boolean noted = look.noted(id);
			int plain = look.canon(id);
			long count = e.getValue();
			if (!noted && !look.stackable(id))
			{
				count = inv.getOrDefault(id, 0L);
			}
			Notary.Advice a = Notary.advise(plain, look.name(plain), count, noted, here);
			if (a == null)
			{
				continue;
			}
			Notary.Desk d = a.best();
			View.NoteLine line = new View.NoteLine();
			line.item = line(id, count, look);
			line.item.noted = noted;
			line.unnote = noted;
			line.who = d.who;
			line.where = d.where;
			line.fee = d.fee;
			line.wilderness = d.wilderness;
			line.frees = look.stackable(id) ? 0 : a.frees;
			line.distance = d.distance(here);
			if (noted || line.frees > 0)
			{
				notes.add(line);
			}
		}
		notes.sort((a, b) -> Integer.compare(b.frees, a.frees));
		v.notes = notes;

		// ---- stores ----
		List<View.StoreView> stores = new ArrayList<>();
		long kept = 0;
		for (Store s : n.stores())
		{
			View.StoreView sv = new View.StoreView();
			sv.key = s.key;
			sv.kind = s.kind;
			sv.name = s.name;
			sv.items = lines(s.items, look);
			sv.worth = Items.worth(s.items, look::price);
			sv.seen = s.seen;
			sv.exact = s.exact;
			sv.live = s.kind.automatic() && Reads.live(s.key);
			sv.ticksLeft = s.ticksLeft;
			sv.until = s.until;
			sv.world = s.world;
			if (here != null && s.located() && s.plane == here[2])
			{
				sv.distance = Math.max(Math.abs(s.x - here[0]), Math.abs(s.y - here[1]));
			}
			kept += sv.worth;
			stores.add(sv);
		}
		stores.sort((a, b) -> a.kind != b.kind ? Integer.compare(a.kind.ordinal(), b.kind.ordinal()) : Long.compare(b.worth, a.worth));
		v.stores = stores;
		v.keptWorth = kept;

		// ---- trips ----
		List<String> names = new ArrayList<>();
		for (Trip t : n.trips())
		{
			names.add(t.name);
		}
		v.trips = names;
		Trip active = n.activeTrip();
		if (active != null)
		{
			v.active = active.name;
			v.fetch = fetch(n, active, look, here);
		}

		// ---- route ----
		v.route = route(n, route, account);
		return v;
	}

	static Fetch plan(Nomad n, Trip trip, Lookup look, int[] here)
	{
		Map<Integer, Long> pocket = Items.canon(n.carried(Nomad.INVENTORY), look::canon);
		Items.add(pocket, Items.canon(n.carried(Nomad.WORN), look::canon));
		Map<Integer, Long> pouch = Items.canon(n.carried(Nomad.RUNE_POUCH), look::canon);
		Items.add(pocket, pouch);
		Map<Integer, Long> bag = Items.canon(n.carried(Nomad.LOOTING_BAG), look::canon);
		return Fetch.plan(trip, pocket, bag, n.stores(), look::canon, look::stackable, here,
			id -> CONTAINERS.contains(id) || pouch.containsKey(id), look::name);
	}

	private static View.FetchView fetch(Nomad n, Trip trip, Lookup look, int[] here)
	{
		Fetch f = plan(n, trip, look, here);
		View.FetchView fv = new View.FetchView();
		fv.name = trip.name;
		fv.ready = f.ready;
		fv.total = f.lines.size();
		fv.missing = f.missing;
		fv.slots = f.slots;
		List<View.FetchLine> lines = new ArrayList<>();
		for (Fetch.Line l : f.lines)
		{
			View.FetchLine fl = new View.FetchLine();
			fl.want = line(l.want.item, l.want.qty, look);
			fl.have = l.have;
			fl.missing = l.missing;
			fl.bagged = l.bagged;
			fl.worn = l.want.worn;
			List<String> where = new ArrayList<>();
			for (Map.Entry<String, Long> e : l.from.entrySet())
			{
				Store s = n.store(e.getKey());
				where.add((s == null ? "?" : s.name) + (l.from.size() > 1 ? " " + e.getValue() : ""));
			}
			fl.from = where.isEmpty() ? null : String.join(", ", where);
			lines.add(fl);
		}
		fv.lines = lines;
		List<View.StopView> stops = new ArrayList<>();
		for (Fetch.Stop s : f.stops)
		{
			View.StopView sv = new View.StopView();
			sv.name = s.store.name;
			sv.kind = s.store.kind;
			sv.distance = s.distance;
			sv.take = lines(s.take, look);
			stops.add(sv);
		}
		fv.stops = stops;
		fv.extra = lines(f.extra, look);
		return fv;
	}

	private static View.RouteView route(Nomad n, Route route, Route.Account account)
	{
		View.RouteView rv = new View.RouteView();
		rv.following = n.following;
		rv.total = route.size();
		List<View.StepView> steps = new ArrayList<>();
		Route.Step current = route.current(n.ticked(), account);
		rv.current = current == null ? -1 : current.index;
		for (Route.Step s : route.steps())
		{
			View.StepView sv = new View.StepView();
			sv.index = s.index;
			sv.key = s.key();
			sv.section = s.section;
			sv.text = s.text;
			sv.tips = s.tips;
			sv.met = Route.met(s, account);
			sv.done = route.done(s, n.ticked(), account);
			sv.passed = sv.done && !sv.met && !n.ticked().contains(s.key());
			sv.optional = s.optional;
			if (sv.done)
			{
				rv.done++;
			}
			sv.check = check(s);
			if (current != null && s.index == current.index)
			{
				sv.clicks = clicks(route.lead(s, account));
			}
			steps.add(sv);
		}
		rv.steps = steps;
		rv.sections = route.sections();
		List<int[]> progress = new ArrayList<>();
		for (String sec : route.sections())
		{
			progress.add(route.section(sec, n.ticked(), account));
		}
		rv.progress = progress;
		return rv;
	}

	/** What the in-game highlights point at, in words. */
	static String clicks(Route.Lead l)
	{
		List<String> parts = new ArrayList<>();
		if (!l.npcs.isEmpty())
		{
			parts.add("Talk to " + String.join(" or ", l.npcs));
		}
		else if (!l.npcIds.isEmpty())
		{
			parts.add("Talk to the outlined person");
		}
		if (!l.objects.isEmpty())
		{
			parts.add("Click the outlined object");
		}
		if (!l.shop.isEmpty())
		{
			parts.add("Buy " + String.join(", ", l.shop));
		}
		if (!l.ground.isEmpty())
		{
			parts.add("Pick up " + String.join(", ", l.ground));
		}
		if (!l.use.isEmpty())
		{
			parts.add("Use " + String.join(", ", l.use));
		}
		for (String say : l.say)
		{
			parts.add("Choose \"" + say + "\"");
		}
		return parts.isEmpty() ? null : String.join(" · ", parts);
	}

	/** What the game watches to tick a step, in a few words. */
	static String check(Route.Step s)
	{
		List<String> parts = new ArrayList<>();
		if (!s.quests.isEmpty())
		{
			parts.add(s.quests.size() == 1 ? "Quest" : s.quests.size() + " quests");
		}
		if (!s.started.isEmpty())
		{
			parts.add("Quest started");
		}
		for (Map.Entry<String, Integer> e : s.skills.entrySet())
		{
			parts.add(e.getValue() + " " + e.getKey());
		}
		if (s.questPoints > 0)
		{
			parts.add(s.questPoints + " quest points");
		}
		if (s.combat > 0)
		{
			parts.add(s.combat + " combat");
		}
		if (s.tier != null)
		{
			parts.add(Character.toUpperCase(s.tier.charAt(0)) + s.tier.substring(1) + " combat achievements");
		}
		if (!s.varbits.isEmpty() || !s.varps.isEmpty())
		{
			parts.add("Unlock");
		}
		if (!s.items.isEmpty() || !s.owned.isEmpty())
		{
			int n = s.items.size() + s.owned.size();
			parts.add(n == 1 ? "Holding it" : "Holding all " + n);
		}
		if (!s.gone.isEmpty())
		{
			parts.add(s.gone.size() == 1 ? "Without " + s.gone.get(0) : "Without " + s.gone.size() + " items");
		}
		if (s.at != null || s.area != null)
		{
			parts.add("Being there");
		}
		if (s.emptyBut != null)
		{
			parts.add(s.emptyBut.isEmpty() ? "Empty inventory" : "Inventory cleared");
		}
		if (s.coins >= 0)
		{
			parts.add(s.coinsAtMost ? (s.coins == 0 ? "No coins on you" : "At most " + Format.coins(s.coins) + " on you")
				: Format.coins(s.coins) + " on you");
		}
		if (!s.chat.isEmpty())
		{
			parts.add("The game's message");
		}
		if (s.deathbank != null)
		{
			parts.add(s.deathbank ? "A deathbank" : "Deathbank emptied");
		}
		if (s.house >= 0)
		{
			parts.add("House moved");
		}
		if (!s.built.isEmpty())
		{
			parts.add("Seen built in your house");
		}
		return parts.isEmpty() ? "Ticks when the next checked step is done" : String.join(" · ", parts);
	}

	static int slots(Map<Integer, Long> items, Lookup look)
	{
		int n = 0;
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			n += look.stackable(e.getKey()) ? 1 : (int) Math.min(28, e.getValue());
		}
		return Math.min(28, n);
	}

	static List<View.LossLine> losses(Nomad n, Lookup look)
	{
		List<View.LossLine> out = new ArrayList<>();
		for (com.codex.nomad.core.Loss l : n.losses())
		{
			View.LossLine line = new View.LossLine();
			line.at = l.at;
			line.cause = l.cause;
			line.worth = l.worth;
			List<Map.Entry<Integer, Long>> items = new ArrayList<>(l.items.entrySet());
			items.sort((a, b) -> Long.compare(look.price(b.getKey()) * b.getValue(), look.price(a.getKey()) * a.getValue()));
			line.item = items.isEmpty() ? -1 : items.get(0).getKey();
			line.what = what(items, look);
			out.add(line);
		}
		return out;
	}

	/** The two most valuable things by name, and how many more. */
	static String what(List<Map.Entry<Integer, Long>> byWorth, Lookup look)
	{
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < Math.min(2, byWorth.size()); i++)
		{
			Map.Entry<Integer, Long> e = byWorth.get(i);
			b.append(i == 0 ? "" : byWorth.size() == 2 ? " and " : ", ").append(look.name(e.getKey()))
				.append(e.getValue() > 1 ? " x" + Format.amount(e.getValue()) : "");
		}
		if (byWorth.size() > 2)
		{
			b.append(" and ").append(byWorth.size() - 2).append(" more");
		}
		return b.toString();
	}

	/** Inventory slots it takes to pick a pile up, counting stacks you already carry as free. */
	static int room(Map<Integer, Long> pile, Map<Integer, Long> inv, Lookup look)
	{
		int n = 0;
		for (Map.Entry<Integer, Long> e : pile.entrySet())
		{
			boolean stacks = look.stackable(e.getKey());
			if (stacks && inv.getOrDefault(e.getKey(), 0L) > 0)
			{
				continue;
			}
			n += stacks ? 1 : (int) Math.min(28, e.getValue());
		}
		return n;
	}

	/** "Needs 21 slots; you have 3 free", or the plain note when there is room. */
	static String roomNote(String note, int need, int free)
	{
		if (need <= 0)
		{
			return note;
		}
		return need > free ? "Needs " + need + (need == 1 ? " slot" : " slots") + "; you have " + free + " free"
			: note + " · needs " + need + (need == 1 ? " slot" : " slots");
	}

	/**
	 * What to drop to make room for a pile: carried items worth less per slot than the pile itself,
	 * cheapest first, until {@code short} slots are free. Each entry is "3 Logs" or a stack's name.
	 */
	static List<String> shed(Map<Integer, Long> pile, Map<Integer, Long> inv, Lookup look, int shortBy)
	{
		List<String> out = new ArrayList<>();
		int slots = 0;
		for (Map.Entry<Integer, Long> e : pile.entrySet())
		{
			slots += look.stackable(e.getKey()) ? 1 : (int) Math.min(28, e.getValue());
		}
		if (shortBy <= 0 || slots == 0)
		{
			return out;
		}
		double pileRate = (double) Items.worth(pile, look::price) / slots;
		List<Map.Entry<Integer, Long>> carried = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : inv.entrySet())
		{
			if (!CONTAINERS.contains(e.getKey()) && !pile.containsKey(e.getKey()) && rate(e, look) < pileRate)
			{
				carried.add(e);
			}
		}
		carried.sort((a, b) -> Double.compare(rate(a, look), rate(b, look)));
		int freed = 0;
		for (Map.Entry<Integer, Long> e : carried)
		{
			if (freed >= shortBy)
			{
				break;
			}
			String name = look.name(e.getKey());
			if (look.stackable(e.getKey()))
			{
				freed++;
				out.add(name);
			}
			else
			{
				int n = (int) Math.min(e.getValue(), shortBy - freed);
				freed += n;
				out.add(n == 1 ? name : n + " " + name);
			}
		}
		return out;
	}

	/** Worth per inventory slot. */
	private static double rate(Map.Entry<Integer, Long> e, Lookup look)
	{
		return look.stackable(e.getKey()) ? (double) look.price(e.getKey()) * e.getValue() : look.price(e.getKey());
	}

	/** Adds "drop 3 Logs, Feathers first" to a pile's note when you lack the room. */
	static String shedNote(String note, Map<Integer, Long> pile, Map<Integer, Long> inv, Lookup look, int shortBy)
	{
		List<String> drop = shed(pile, inv, look, shortBy);
		return drop.isEmpty() ? note : note + " · drop " + String.join(", ", drop) + " first";
	}

	static View.ItemLine line(int id, long qty, Lookup look)
	{
		View.ItemLine l = new View.ItemLine(id, look.name(id), qty, look.price(id) * qty);
		l.noted = look.noted(id);
		return l;
	}

	static List<View.ItemLine> lines(Map<Integer, Long> items, Lookup look)
	{
		if (items == null || items.isEmpty())
		{
			return Collections.emptyList();
		}
		List<View.ItemLine> out = new ArrayList<>();
		items.forEach((id, q) -> out.add(line(id, q, look)));
		out.sort((a, b) -> Long.compare(b.worth, a.worth));
		return out;
	}
}

package com.codex.nomad.core;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The costume room's furniture and what each piece holds. The game shows every piece through the
 * same window, so the piece open is the one most of the shown items belong to.
 */
public final class Costume
{
	private final Map<String, Set<Integer>> pieces = new LinkedHashMap<>();

	Costume(Map<String, List<Integer>> data)
	{
		data.forEach((k, v) -> pieces.put(k, new HashSet<>(v)));
	}

	public static Costume load(Gson gson)
	{
		Type type = new TypeToken<LinkedHashMap<String, List<Integer>>>()
		{
		}.getType();
		try (InputStream in = Costume.class.getResourceAsStream("/com/codex/nomad/costume.json"))
		{
			Map<String, List<Integer>> data = in == null ? null : gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
			return new Costume(data == null ? Collections.emptyMap() : data);
		}
		catch (Exception e)
		{
			return new Costume(Collections.emptyMap());
		}
	}

	public int size()
	{
		return pieces.size();
	}

	/**
	 * @param shown what the costume room window shows, by item
	 * @return the piece of furniture open, or null when nothing shown belongs to any
	 */
	public String piece(Map<Integer, Long> shown)
	{
		String best = null;
		int most = 0;
		for (Map.Entry<String, Set<Integer>> e : pieces.entrySet())
		{
			int n = 0;
			for (int id : shown.keySet())
			{
				if (e.getValue().contains(id))
				{
					n++;
				}
			}
			if (n > most)
			{
				most = n;
				best = e.getKey();
			}
		}
		return best;
	}

	/** What of the shown items the piece holds. */
	public Map<Integer, Long> held(String piece, Map<Integer, Long> shown)
	{
		Set<Integer> ids = pieces.get(piece);
		Map<Integer, Long> out = new LinkedHashMap<>();
		if (ids != null)
		{
			shown.forEach((k, v) ->
			{
				if (ids.contains(k))
				{
					out.put(k, v);
				}
			});
		}
		return out;
	}
}

