	private static void claim(String lair, String who, long fee, String note)
	{
		CLAIMS.put(lair, "Reclaim from " + who + (note != null ? ", " + note
			: fee > 0 ? " for " + (fee >= 1000 ? fee / 1000 + "k" : String.valueOf(fee)) : ""));
		if (fee >= 0)
		{
			FEES.put(lair, fee);
		}
		String who2 = who.startsWith("the ") ? Character.toUpperCase(who.charAt(4)) + who.substring(5) : who;
		BRIEFS.put(lair, who2.replaceAll(" (on|past|north of) .*", "") + ", "
			+ (fee > 0 ? (fee >= 1000 ? fee / 1000 + "k" : String.valueOf(fee)) : fee == 0 ? "free" : note));
	}

	private static void holder(String lair, int[] npcs, int[] objects)
	{
		if (npcs != null)
		{
			HOLDER_NPCS.put(lair, npcs);
		}
		if (objects != null)
		{
			HOLDER_OBJECTS.put(lair, objects);
		}
	}

	/** Whether this npc or object (by id) holds the lair's deathbank. */
	public static boolean holds(String lair, int id, boolean object)
	{
		int[] ids = lair == null ? null : (object ? HOLDER_OBJECTS : HOLDER_NPCS).get(lair);
		if (ids != null)
		{
			for (int i : ids)
			{
				if (i == id)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Every object that holds some deathbank. */
	public static boolean holderObject(int id)
	{
		for (int[] ids : HOLDER_OBJECTS.values())
		{
			for (int i : ids)
			{
				if (i == id)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Who holds a lair's deathbank and the price, in a few words, or null. */
	public static String brief(String lair)
	{
		return lair == null ? null : BRIEFS.get(lair);
	}

	/** How to get a lair's deathbank back: "Reclaim from Torfinn for 100k", or null. */
	public static String claim(String lair)
	{
		return lair == null ? null : CLAIMS.get(lair);
	}

	/** The fee in coins to reclaim a lair's deathbank, or -1 when unknown or not paid in coins. */
	public static long fee(String lair)
	{
		return lair == null ? -1 : FEES.getOrDefault(lair, -1L);
	}

	private static void lair(String name, int... regions)
	{
		for (int r : regions)
		{
			LAIRS.put(r, name);
		}
	}

	/** The lair a region belongs to, or null. */
	public static String lair(int region)
	{
		return LAIRS.get(region);
	}

	public final Kind kind;
	/** Where it went: the lair's name for a deathbank. */
	public final String place;
	public final Map<Integer, Long> lost;

	private Death(Kind kind, String place, Map<Integer, Long> lost)
	{
		this.kind = kind;
		this.place = place;
		this.lost = lost;
	}

	/**
	 * @param before everything carried a tick before the death, looting bag included
	 * @param after everything carried once respawned
	 * @param region the map region the player died in
	 * @param instanced true when the death was in an instance, whose deaths go to a retrieval service
	 */
	public static Death of(Map<Integer, Long> before, Map<Integer, Long> after, int region, boolean instanced)
	{
		Map<Integer, Long> lost = Items.minus(before, after);
		if (lost.isEmpty())
		{
			return new Death(Kind.SAFE, null, Collections.emptyMap());
		}
		String lair = lair(region);
		if (lair != null)
		{
			return new Death(Kind.DEATHBANK, lair, lost);
		}
		if (instanced)
		{
			return new Death(Kind.DEATHBANK, "an instance", lost);
		}
		return new Death(Kind.PILE, null, lost);
	}
}

package com.codex.nomad.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;

/**
 * Checks a packing list against what is carried and every place things are kept, and works out
 * the stops to make, in order: perishable places first, then the nearest. The first stop is the
 * one the player is pointed at.
 */
public final class Fetch
{
	public static final int SLOTS = 28;

	/** One line of the list, checked. */
	public static final class Line
	{
		public Trip.Want want;
		public long have;
		/** Where the shortfall can come from, by store key. */
		public Map<String, Long> from = new LinkedHashMap<>();
		/** Sitting in the looting bag, which only a death or the Wilderness opens. */
		public long bagged;
		/** Still short once every place has given what it holds. */
		public long missing;

		public long shortfall()
		{
			return Math.max(0, want.qty - have);
		}

		public boolean ready()
		{
			return have >= want.qty;
		}
	}

	/** One place to call at, with what to take. */
	public static final class Stop
	{
		public Store store;
		public Map<Integer, Long> take = new LinkedHashMap<>();
		/** Tiles away as the crow flies, or -1 when unknown or on another plane. */
		public int distance = -1;

		public long count()
		{
			long n = 0;
			for (long v : take.values())
			{
				n += v;
			}
			return n;
		}
	}

	public final Trip trip;
	public final List<Line> lines = new ArrayList<>();
	public final List<Stop> stops = new ArrayList<>();
	/** Carried items that are not on the list, by item: candidates to leave somewhere first. */
	public final Map<Integer, Long> extra = new LinkedHashMap<>();
	public int ready;
	public int missing;
	/** Inventory slots the list takes once packed. */
	public int slots;

	private Fetch(Trip trip)
	{
		this.trip = trip;
	}

	public boolean done()
	{
		return ready == lines.size();
	}

	public boolean fits()
	{
		return slots <= SLOTS;
	}

	public Stop next()
	{
		return stops.isEmpty() ? null : stops.get(0);
	}

	/**
	 * @param pocket what is carried and usable (inventory and worn), by common item id
	 * @param bag what is in the looting bag, by common item id
	 * @param stores every place things are kept
	 * @param canon turns an item into its common form: noted and unnoted alike
	 * @param stackable whether an item stacks in one slot
	 * @param here the player's x, y and plane, or null
	 * @param always items never called extra, such as the rune pouch and coins
	 */
	public static Fetch plan(Trip trip, Map<Integer, Long> pocket, Map<Integer, Long> bag, List<Store> stores,
		IntUnaryOperator canon, IntPredicate stackable, int[] here, IntPredicate always)
	{
		return plan(trip, pocket, bag, stores, canon, stackable, here, always, null);
	}

	/** "Super restore(3)": the potion or jewellery and how many doses or charges it holds. */
	private static final Pattern USES = Pattern.compile("^(.+)\\((\\d)\\)$");

	/** The name without its doses or charges, and how many it holds, or null. */
	static Object[] uses(IntFunction<String> name, int id)
	{
		String n = name == null ? null : name.apply(id);
		Matcher m = n == null ? null : USES.matcher(n);
		return m != null && m.matches() ? new Object[]{m.group(1).trim(), Integer.parseInt(m.group(2))} : null;
	}

	/**
	 * As above; with item names, a potion or charged jewellery wanted at one dose count is met by
	 * the same thing at any other, dose for dose: four super restore(3) stand in for three (4).
	 */
	public static Fetch plan(Trip trip, Map<Integer, Long> pocket, Map<Integer, Long> bag, List<Store> stores,
		IntUnaryOperator canon, IntPredicate stackable, int[] here, IntPredicate always, IntFunction<String> name)
	{
		Fetch f = new Fetch(trip);
		List<Store> order = new ArrayList<>();
		Map<Store, Map<Integer, Long>> left = new LinkedHashMap<>();
		Map<Store, Integer> distance = new LinkedHashMap<>();
		for (Store s : stores)
		{
			if (s.isEmpty())
			{
				continue;
			}
			order.add(s);
			left.put(s, Items.canon(s.items, canon));
			distance.put(s, distance(s, here));
		}
		order.sort((a, b) ->
		{
			int k = Integer.compare(a.kind.ordinal(), b.kind.ordinal());
			if (k != 0)
			{
				return k;
			}
			int da = distance.get(a);
			int db = distance.get(b);
			if (da < 0 || db < 0)
			{
				return Boolean.compare(da < 0, db < 0);
			}
			return Integer.compare(da, db);
		});

		Map<Store, Stop> byStore = new LinkedHashMap<>();
		Map<Integer, Long> wanted = new LinkedHashMap<>();
		for (Trip.Want w : trip.wants)
		{
			Line line = new Line();
			line.want = w;
			long carried = pocket.getOrDefault(w.item, 0L) - wanted.getOrDefault(w.item, 0L);
			line.have = Math.max(0, Math.min(w.qty, carried));
			wanted.merge(w.item, line.have, Long::sum);
			long need = line.shortfall();
			for (Store s : order)
			{
				if (need <= 0)
				{
					break;
				}
				Map<Integer, Long> there = left.get(s);
				long n = Math.min(need, there.getOrDefault(w.item, 0L));
				if (n > 0)
				{
					there.put(w.item, there.get(w.item) - n);
					line.from.put(s.key, n);
					Stop stop = byStore.computeIfAbsent(s, k ->
					{
						Stop st = new Stop();
						st.store = k;
						st.distance = distance.get(k);
						return st;
					});
					stop.take.merge(w.item, n, Long::sum);
					need -= n;
				}
			}
			Object[] wantUses = need > 0 ? uses(name, w.item) : null;
			if (wantUses != null && (int) wantUses[1] > 0)
			{
				int each = (int) wantUses[1];
				long doses = need * each;
				// Carried first: other dose counts in the pack count as had.
				for (Map.Entry<Integer, Long> e : pocket.entrySet())
				{
					Object[] u = e.getKey() == w.item || doses <= 0 ? null : uses(name, e.getKey());
					if (u == null || !u[0].equals(wantUses[0]) || (int) u[1] <= 0)
					{
						continue;
					}
					long free = e.getValue() - wanted.getOrDefault(e.getKey(), 0L);
					long k = Math.min(free, (doses + (int) u[1] - 1) / (int) u[1]);
					if (k > 0)
					{
						wanted.merge(e.getKey(), k, Long::sum);
						doses -= k * (int) u[1];
					}
				}
				long fromPocket = need - Math.max(0, (doses + each - 1) / each);
				line.have = Math.min(w.qty, line.have + fromPocket);
				for (Store st : order)
				{
					if (doses <= 0)
					{
						break;
					}
					Map<Integer, Long> there = left.get(st);
					for (Map.Entry<Integer, Long> e : new ArrayList<>(there.entrySet()))
					{
						Object[] u = e.getKey() == w.item || doses <= 0 ? null : uses(name, e.getKey());
						if (u == null || !u[0].equals(wantUses[0]) || (int) u[1] <= 0 || e.getValue() <= 0)
						{
							continue;
						}
						long k = Math.min(e.getValue(), (doses + (int) u[1] - 1) / (int) u[1]);
						there.put(e.getKey(), e.getValue() - k);
						doses -= k * (int) u[1];
						line.from.merge(st.key, k, Long::sum);
						Stop stop = byStore.computeIfAbsent(st, x ->
						{
							Stop sp = new Stop();
							sp.store = x;
							sp.distance = distance.get(x);
							return sp;
						});
						stop.take.merge(e.getKey(), k, Long::sum);
					}
				}
				need = Math.max(0, (doses + each - 1) / each);
			}
			if (need > 0)
			{
				line.bagged = Math.min(need, bag.getOrDefault(w.item, 0L));
			}
			line.missing = need;
			if (line.ready())
			{
				f.ready++;
			}
			else if (line.missing > 0)
			{
				f.missing++;
			}
			if (!w.worn)
			{
				f.slots += stackable.test(w.item) ? 1 : (int) Math.min(SLOTS + 1, w.qty);
			}
			f.lines.add(line);
		}
		for (Store s : order)
		{
			Stop stop = byStore.get(s);
			if (stop != null)
			{
				f.stops.add(stop);
			}
		}
		for (Map.Entry<Integer, Long> e : pocket.entrySet())
		{
			long beyond = e.getValue() - wanted.getOrDefault(e.getKey(), 0L);
			boolean listed = wanted.getOrDefault(e.getKey(), 0L) > 0;
			for (Trip.Want w : trip.wants)
			{
				listed |= w.item == e.getKey();
			}
			if (beyond > 0 && !listed && !always.test(e.getKey()))
			{
				f.extra.put(e.getKey(), beyond);
			}
		}
		return f;
	}

	static int distance(Store s, int[] here)
	{
		if (here == null || !s.located() || s.plane != here[2])
		{
			return -1;
		}
		return Math.max(Math.abs(s.x - here[0]), Math.abs(s.y - here[1]));
	}

	public List<Line> lines()
	{
		return Collections.unmodifiableList(lines);
	}
}

package com.codex.nomad.core;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * When the inventory will be full at the pace it is filling: skilling, looting or picking things up.
 * Watches slots used over the last few minutes of play; any fall (dropping, noting, eating) starts
 * the watch again, so the pace is only ever of filling.
 */
public final class Forecast
{
	static final long WINDOW = 5 * 60_000L;
	static final long LEAST = 60_000L;

	private final Deque<long[]> seen = new ArrayDeque<>();

	/** Notes the slots used at this much play time, ms. */
	public void note(long played, int used)
	{
		long[] last = seen.peekLast();
		if (last != null && used < last[1])
		{
			seen.clear();
		}
		if (last == null || used != last[1] || seen.size() == 1)
		{
			seen.addLast(new long[]{played, used});
		}
		while (seen.size() > 2 && played - seen.peekFirst()[0] > WINDOW)
		{
			seen.removeFirst();
		}
	}

	/** Ms of play until all 28 slots are used, or -1 when not filling or not yet known. */
	public long untilFull(long played, int used)
	{
		long[] first = seen.peekFirst();
		if (first == null || used >= 28)
		{
			return -1;
		}
		long span = played - first[0];
		long gained = used - first[1];
		if (span < LEAST || gained <= 0)
		{
			return -1;
		}
		return (28 - used) * span / gained;
	}
}

package com.codex.nomad.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.IntPredicate;

/**
 * Dead weight: carried items that have sat untouched for hours of play, each with the slots it
 * takes, so the player can see what to leave in a STASH, the costume room or a deathpile.
 */
public final class Idle
{
	public final int item;
	public final long qty;
	/** Play time since it last changed, ms. */
	public final long idleMs;
	public final int slots;

	Idle(int item, long qty, long idleMs, int slots)
	{
		this.item = item;
		this.qty = qty;
		this.idleMs = idleMs;
		this.slots = slots;
	}

	/**
	 * @param carried the inventory, by item
	 * @param keep items never called dead weight, such as the looting bag and rune pouch
	 * @param after play time untouched before an item counts, ms
	 */
	public static List<Idle> find(Nomad n, Map<Integer, Long> carried, IntPredicate stackable, IntPredicate keep, long after)
	{
		List<Idle> out = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : carried.entrySet())
		{
			int item = e.getKey();
			if (keep.test(item))
			{
				continue;
			}
			long idle = n.played - n.touched(item);
			if (idle >= after)
			{
				int slots = stackable.test(item) ? 1 : (int) Math.min(28, e.getValue());
				out.add(new Idle(item, e.getValue(), idle, slots));
			}
		}
		out.sort((a, b) -> b.slots != a.slots ? Integer.compare(b.slots, a.slots) : Long.compare(b.idleMs, a.idleMs));
		return out;
	}

	public static int slots(List<Idle> list)
	{
		int n = 0;
		for (Idle i : list)
		{
			n += i.slots;
		}
		return n;
	}
}

package com.codex.nomad.core;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/** Small sums over item maps. */
public final class Items
{
	private Items()
	{
	}

	/** Positive counts only, no empty slots, held to what one stack can hold. */
	public static Map<Integer, Long> clean(Map<Integer, Long> in)
	{
		Map<Integer, Long> out = new LinkedHashMap<>();
		if (in == null)
		{
			return out;
		}
		in.forEach((k, v) ->
		{
			if (k != null && k > 0 && v != null && v > 0)
			{
				out.merge(k, Math.min(Integer.MAX_VALUE, v), (a, b) -> Math.min(Integer.MAX_VALUE, a + b));
			}
		});
		return out;
	}

	/** Adds every count in b into a. */
	public static void add(Map<Integer, Long> into, Map<Integer, Long> b)
	{
		if (b != null)
		{
			b.forEach((k, v) -> into.merge(k, v, Long::sum));
		}
	}

	/** What a holds beyond b: the items lost or spent when a became b. */
	public static Map<Integer, Long> minus(Map<Integer, Long> a, Map<Integer, Long> b)
	{
		Map<Integer, Long> out = new LinkedHashMap<>();
		a.forEach((k, v) ->
		{
			long d = v - b.getOrDefault(k, 0L);
			if (d > 0)
			{
				out.put(k, d);
			}
		});
		return out;
	}

	/** The same items keyed by a common form, such as noted and unnoted counted together. */
	public static Map<Integer, Long> canon(Map<Integer, Long> in, IntUnaryOperator canon)
	{
		Map<Integer, Long> out = new HashMap<>();
		in.forEach((k, v) -> out.merge(canon.applyAsInt(k), v, Long::sum));
		return out;
	}

	public static long worth(Map<Integer, Long> items, Prices prices)
	{
		long sum = 0;
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			sum += prices.each(e.getKey()) * e.getValue();
		}
		return sum;
	}
}

package com.codex.nomad.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * What a death would keep and drop right now: the most valuable items are kept one by one (three,
 * four with Protect Item, none while skulled) and the rest fall.
 */
public final class Kept
{
	public final Map<Integer, Long> kept = new LinkedHashMap<>();
	public final Map<Integer, Long> dropped = new LinkedHashMap<>();
	public long keptWorth;
	public long droppedWorth;

	public static Kept of(Map<Integer, Long> carried, Prices prices, int keep)
	{
		Kept k = new Kept();
		List<Map.Entry<Integer, Long>> list = new ArrayList<>(carried.entrySet());
		list.sort((a, b) -> Long.compare(prices.each(b.getKey()), prices.each(a.getKey())));
		int left = Math.max(0, keep);
		for (Map.Entry<Integer, Long> e : list)
		{
			long n = e.getValue();
			long each = prices.each(e.getKey());
			long keepN = Math.min(left, n);
			left -= keepN;
			if (keepN > 0)
			{
				k.kept.put(e.getKey(), keepN);
				k.keptWorth += keepN * each;
			}
			if (n - keepN > 0)
			{
				k.dropped.put(e.getKey(), n - keepN);
				k.droppedWorth += (n - keepN) * each;
			}
		}
		return k;
	}
}

package com.codex.nomad.core;

/**
 * The kinds of place an ultimate ironman keeps things, in the order a trip should visit them:
 * what can be lost first comes first.
 */
public enum Kind
{
	FLOOR("On the floor", "Dropped items vanish when their timer runs out"),
	DEATHPILE("Deathpile", "Lost when its timer runs out"),
	DEATHBANK("Deathbank", "Wiped by any unsafe death"),
	COSTUME("Costume room", "Safe in your house"),
	STASH("STASH unit", "Safe, one outfit per unit"),
	SEED_VAULT("Seed vault", "Safe at the Farming Guild"),
	KEPT("Kept for you", "Safe; the game keeps the count, so Nomad reads it any time"),
	COFFER("Coffers", "Coins held for you; the game keeps the count"),
	OTHER("Elsewhere", "Remembered by hand");

	private final String label;
	private final String safety;

	Kind(String label, String safety)
	{
		this.label = label;
		this.safety = safety;
	}

	public String getLabel()
	{
		return label;
	}

	/** One line on how safe things are there. */
	public String getSafety()
	{
		return safety;
	}

	/** True for places the game counts by itself, so they are always exact. */
	public boolean automatic()
	{
		return this == KEPT || this == COFFER;
	}

	/** True for places whose contents can be lost. */
	public boolean perilous()
	{
		return this == FLOOR || this == DEATHPILE || this == DEATHBANK;
	}
}

package com.codex.nomad.core;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;

/**
 * Turns the kits saved in Codex Quartermaster into packing lists. A kit names supplies, not items:
 * "200 hp of food", "12 doses of prayer restore". Each becomes the items you own that cover it,
 * richest first, and whatever is still short asks for the best item of that kind.
 */
public final class Kits
{
	/** Packing lists made from Quartermaster kits start with this. */
	public static final String PREFIX = "Quartermaster: ";
	public static final String GROUP = "codexquartermaster";
	public static final String KEY = "kitsV1";

	private Kits()
	{
	}

	/**
	 * @param json the kitsV1 value, or null
	 * @param owned how many of an item you own anywhere Nomad knows
	 * @param name an item's name
	 */
	public static List<Trip> read(String json, Map<Integer, Long> owned, IntFunction<String> name)
	{
		List<Trip> out = new ArrayList<>();
		JsonElement root;
		try
		{
			root = json == null ? null : new JsonParser().parse(json);
		}
		catch (RuntimeException e)
		{
			return out;
		}
		if (root == null || !root.isJsonObject() || !root.getAsJsonObject().has("kits")
			|| !root.getAsJsonObject().get("kits").isJsonArray())
		{
			return out;
		}
		String active = string(root.getAsJsonObject(), "active");
		for (JsonElement k : root.getAsJsonObject().getAsJsonArray("kits"))
		{
			if (!k.isJsonObject())
			{
				continue;
			}
			JsonObject kit = k.getAsJsonObject();
			String kitName = string(kit, "name");
			boolean preset = kit.has("preset") && kit.get("preset").isJsonPrimitive() && kit.get("preset").getAsBoolean();
			if (kitName == null || preset && !String.valueOf(string(kit, "id")).equals(active))
			{
				continue;
			}
			Trip trip = new Trip(PREFIX + kitName, 0);
			if (kit.has("needs") && kit.get("needs").isJsonArray())
			{
				for (JsonElement n : kit.getAsJsonArray("needs"))
				{
					if (n.isJsonObject())
					{
						need(trip, n.getAsJsonObject(), owned, name);
					}
				}
			}
			if (!trip.wants.isEmpty())
			{
				out.add(trip);
			}
		}
		return out;
	}

	private static void need(Trip trip, JsonObject need, Map<Integer, Long> owned, IntFunction<String> name)
	{
		if (!need.has("items") || !need.get("items").isJsonObject())
		{
			return;
		}
		List<long[]> items = new ArrayList<>();
		for (Map.Entry<String, JsonElement> e : need.getAsJsonObject("items").entrySet())
		{
			try
			{
				int id = Integer.parseInt(e.getKey());
				long unit = e.getValue().getAsLong();
				if (id > 0 && unit > 0)
				{
					items.add(new long[]{id, unit});
				}
			}
			catch (RuntimeException ignored)
			{
				// Not an item: skipped.
			}
		}
		if (items.isEmpty())
		{
			return;
		}
		long wanted = need.has("perTrip") && need.get("perTrip").isJsonPrimitive() ? need.get("perTrip").getAsLong() : 0;
		// Richest first, as Quartermaster lists them; owned items before ones you would have to find.
		items.sort((a, b) -> Long.compare(b[1], a[1]));
		List<long[]> mine = new ArrayList<>();
		for (long[] i : items)
		{
			if (owned.getOrDefault((int) i[0], 0L) > 0)
			{
				mine.add(i);
			}
		}
		if (wanted <= 0)
		{
			long[] pick = mine.isEmpty() ? items.get(0) : mine.get(0);
			add(trip, (int) pick[0], 1, name);
			return;
		}
		long left = wanted;
		for (long[] i : mine)
		{
			if (left <= 0)
			{
				break;
			}
			long take = Math.min(owned.get((int) i[0]), (left + i[1] - 1) / i[1]);
			add(trip, (int) i[0], take, name);
			left -= take * i[1];
		}
		if (left > 0)
		{
			long[] best = items.get(0);
			add(trip, (int) best[0], (left + best[1] - 1) / best[1], name);
		}
	}

	private static void add(Trip trip, int id, long qty, IntFunction<String> name)
	{
		for (Trip.Want w : trip.wants)
		{
			if (w.item == id)
			{
				w.qty += qty;
				return;
			}
		}
		trip.wants.add(new Trip.Want(id, name.apply(id), qty, false));
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}

	/** Lists made from kits that Quartermaster no longer has. */
	public static List<String> stale(List<Trip> saved, List<Trip> fresh)
	{
		List<String> gone = new ArrayList<>();
		for (Trip t : saved)
		{
			if (t.name.startsWith(PREFIX) && fresh.stream().noneMatch(f -> f.name.equalsIgnoreCase(t.name)))
			{
				gone.add(t.name);
			}
		}
		return gone.isEmpty() ? Collections.emptyList() : gone;
	}
}

package com.codex.nomad.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.IntPredicate;

/**
 * The looting bag's rules for an ultimate ironman, as the OSRS Wiki has them: its contents come out
 * only on death, or by destroying it in the Wilderness, which drops them on the floor. Destroying it
 * anywhere else deletes them, and so does destroying it in the Ferox Enclave or within the first two
 * tiles past the Wilderness ditch. Food, potions and vials of water inside are lost either way.
 */
public final class LootingBag
{
	/** The first surface row of the Wilderness, just north of the ditch. */
	private static final int DITCH_Y = 3523;

	private LootingBag()
	{
	}

	/**
	 * Whether destroying the bag here drops its contents rather than deleting them.
	 *
	 * @param wild the game says the player is in the Wilderness
	 */
	public static boolean dropsHere(boolean wild, int x, int y, int plane)
	{
		if (!wild)
		{
			return false;
		}
		if (plane == 0 && x >= 2944 && x <= 3392 && y >= DITCH_Y && y < DITCH_Y + 2)
		{
			return false;
		}
		return !ferox(x, y, plane);
	}

	/** The Ferox Enclave, generously drawn: wilderness levels 13 to 16 around the town's walls. */
	static boolean ferox(int x, int y, int plane)
	{
		return x >= 3121 && x <= 3158 && y >= 3614 && y <= 3648 && plane <= 1;
	}

	/** The things in the bag that destroying it would not drop: food, potions and vials of water. */
	public static List<Integer> perishable(Map<Integer, Long> bag, IntPredicate perishes)
	{
		List<Integer> out = new ArrayList<>();
		for (int item : bag.keySet())
		{
			if (perishes.test(item))
			{
				out.add(item);
			}
		}
		return out;
	}
}

package com.codex.nomad.core;

import java.util.LinkedHashMap;
import java.util.Map;

/** Something gone for good: a deathpile that ran out, a wiped deathbank, a floor that vanished. */
public final class Loss
{
	/** When, epoch ms. */
	public long at;
	/** What happened, in a few words: "Deathpile ran out". */
	public String cause;
	public Map<Integer, Long> items = new LinkedHashMap<>();
	/** What it was worth when it went. */
	public long worth;

	public Loss()
	{
	}

	public Loss(long at, String cause, Map<Integer, Long> items, long worth)
	{
		this.at = at;
		this.cause = cause;
		this.items = new LinkedHashMap<>(items);
		this.worth = worth;
	}
}

package com.codex.nomad.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything Nomad keeps for one account: what is carried, every place things are kept, the
 * deathpiles and deathbank, the packing lists, and how long each carried item has sat untouched.
 * Saved as one blob per RuneScape profile.
 */
public final class Nomad
{
	public static final int VERSION = 1;
	/** A deathpile lasts an hour of logged-in time: 6,000 game ticks. */
	public static final long PILE_TICKS = 6_000;
	public static final String INVENTORY = "Inventory";
	public static final String WORN = "Worn";
	public static final String LOOTING_BAG = "Looting bag";
	public static final String RUNE_POUCH = "Rune pouch";
	public static final String DEATHBANK = "deathbank";
	static final int TRIPS = 30;
	static final int PILES = 6;
	static final int FLOORS = 20;
	static final int LOSSES = 40;

	int version = VERSION;
	/** The ironman varbit: 2 is ultimate; -1 not yet read. */
	public int account = -1;
	/** Milliseconds played in all, counted while logged in. */
	public long played;
	/** What is carried, by container name. */
	Map<String, Map<Integer, Long>> pack = new LinkedHashMap<>();
	/** When each container was last read, epoch ms; a looting bag is only known once checked. */
	Map<String, Long> packSeen = new HashMap<>();
	/** Every place things are kept, by key. */
	Map<String, Store> stores = new LinkedHashMap<>();
	/** Play time, in ms of {@link #played}, when each carried item last changed. */
	Map<Integer, Long> touched = new HashMap<>();
	List<Trip> trips = new ArrayList<>();
	/** The packing list being fetched, by name, or null. */
	public String active;
	/** Route steps ticked by hand or by holding their items, by step key. */
	Set<String> ticked = new HashSet<>();
	/** True while the player follows the route to Prifddinas. */
	public boolean following;
	/** What was lost for good, newest last, the latest {@link #LOSSES}. */
	List<Loss> losses = new ArrayList<>();
	/** All that was ever lost, in coins at the time, including losses too old to list. */
	public long lostWorth;

	// ---- what is carried ----

	public void carry(String container, Map<Integer, Long> items, long now)
	{
		pack.put(container, Items.clean(items));
		packSeen.put(container, now);
	}

	public Map<Integer, Long> carried(String container)
	{
		Map<Integer, Long> m = pack.get(container);
		return m == null ? Collections.emptyMap() : Collections.unmodifiableMap(m);
	}

	/** The names of every container ever read, in the order first read. */
	public List<String> containers()
	{
		return new ArrayList<>(pack.keySet());
	}

	public boolean seen(String container)
	{
		return pack.containsKey(container);
	}

	public long seenAt(String container)
	{
		return packSeen.getOrDefault(container, 0L);
	}

	/** Everything carried, every container together. */
	public Map<Integer, Long> carried()
	{
		Map<Integer, Long> all = new LinkedHashMap<>();
		pack.values().forEach(m -> Items.add(all, m));
		return all;
	}

	/** The inventory and worn items: the only things a death can keep. */
	public Map<Integer, Long> loose()
	{
		Map<Integer, Long> all = new LinkedHashMap<>();
		Items.add(all, carried(INVENTORY));
		Items.add(all, carried(WORN));
		return all;
	}

	/** Everything carried inside something else: the looting bag, pouches, sacks and boxes. */
	public Map<Integer, Long> inside()
	{
		Map<Integer, Long> all = new LinkedHashMap<>();
		pack.forEach((k, m) ->
		{
			if (!k.equals(INVENTORY) && !k.equals(WORN))
			{
				Items.add(all, m);
			}
		});
		return all;
	}

	/**
	 * Notes when carried items change, so items that sit untouched for hours of play can be told
	 * apart from the ones in use. Worn items count as in use.
	 */
	public void touch(Map<Integer, Long> before, Map<Integer, Long> after)
	{
		for (Map.Entry<Integer, Long> e : after.entrySet())
		{
			if (!e.getValue().equals(before.get(e.getKey())))
			{
				touched.put(e.getKey(), played);
			}
		}
		touched.keySet().retainAll(after.keySet());
	}

	/** Play time when an item last changed, or the current play time if it never has. */
	public long touched(int item)
	{
		return touched.getOrDefault(item, played);
	}

	// ---- stores ----

	public Store store(String key)
	{
		return stores.get(key);
	}

	public void put(Store s)
	{
		stores.put(s.key, s);
	}

	public Store remove(String key)
	{
		return stores.remove(key);
	}

	public List<Store> stores()
	{
		return new ArrayList<>(stores.values());
	}

	public List<Store> stores(Kind kind)
	{
		List<Store> out = new ArrayList<>();
		for (Store s : stores.values())
		{
			if (s.kind == kind)
			{
				out.add(s);
			}
		}
		return out;
	}

	public Store deathbank()
	{
		return stores.get(DEATHBANK);
	}

	/** Leaves a deathpile where the player died; the oldest goes if there are already too many. */
	public Store pile(Map<Integer, Long> items, int x, int y, int plane, long now)
	{
		List<Store> piles = stores(Kind.DEATHPILE);
		while (piles.size() >= PILES)
		{
			stores.remove(piles.remove(0).key);
		}
		Store pile = new Store("pile:" + now, Kind.DEATHPILE, "Deathpile").at(x, y, plane);
		pile.items = Items.clean(items);
		pile.seen = now;
		pile.since = now;
		pile.ticksLeft = PILE_TICKS;
		pile.exact = true;
		put(pile);
		return pile;
	}

	/**
	 * One logged-in game tick passes: every deathpile's timer runs down.
	 *
	 * @return the piles that ran out on this tick, now gone
	 */
	public List<Store> tick()
	{
		List<Store> gone = new ArrayList<>();
		for (Store s : stores(Kind.DEATHPILE))
		{
			if (s.ticksLeft > 0)
			{
				s.ticksLeft--;
			}
			if (s.ticksLeft == 0 || s.isEmpty())
			{
				stores.remove(s.key);
				if (!s.isEmpty())
				{
					gone.add(s);
				}
			}
		}
		return gone;
	}

	// ---- losses ----

	/** Notes something gone for good. */
	public void lose(String cause, Map<Integer, Long> items, long worth, long now)
	{
		if (items == null || items.isEmpty())
		{
			return;
		}
		losses.add(new Loss(now, cause, items, worth));
		lostWorth += worth;
		while (losses.size() > LOSSES)
		{
			losses.remove(0);
		}
	}

	/** Losses, newest first. */
	public List<Loss> losses()
	{
		List<Loss> out = new ArrayList<>(losses);
		Collections.reverse(out);
		return out;
	}

	// ---- dropped items ----

	/** The "world" of things dropped on the Chambers of Xeric floor, kept by raid map position. */
	public static final int RAID = -1;

	public static String floorKey(int world, int x, int y, int plane)
	{
		return "floor:" + world + ":" + x + ":" + y + ":" + plane;
	}

	/** Notes items the player dropped, with when they vanish; one store per tile and world. */
	public Store drop(int world, int x, int y, int plane, int item, long qty, long until, long now)
	{
		String key = floorKey(world, x, y, plane);
		Store s = stores.get(key);
		if (s == null)
		{
			List<Store> floors = stores(Kind.FLOOR);
			floors.removeIf(f -> f.world == RAID);
			floors.sort((a, b) -> Long.compare(a.until, b.until));
			while (floors.size() >= FLOORS)
			{
				stores.remove(floors.remove(0).key);
			}
			s = new Store(key, Kind.FLOOR, world == RAID ? "Chambers of Xeric floor" : "Dropped on world " + world).at(x, y, plane);
			s.world = world;
			s.since = now;
			put(s);
		}
		if (s.expires == null)
		{
			s.expires = new LinkedHashMap<>();
		}
		s.items.merge(item, qty, Long::sum);
		s.expires.merge(item, until, Math::max);
		s.until = soonest(s);
		s.seen = now;
		s.exact = true;
		return s;
	}

	/**
	 * Forgets the raid floor once the player has left the raid, which destroys it.
	 *
	 * @return what was left behind
	 */
	public Map<Integer, Long> endRaid()
	{
		Map<Integer, Long> lost = new LinkedHashMap<>();
		for (Store s : stores(Kind.FLOOR))
		{
			if (s.world == RAID)
			{
				s.items.forEach((item, qty) -> lost.merge(item, qty, Long::sum));
				stores.remove(s.key);
			}
		}
		return lost;
	}

	/** Takes items off the floor: picked up, or seen to vanish. */
	public void lift(int world, int x, int y, int plane, int item, long qty)
	{
		Store s = stores.get(floorKey(world, x, y, plane));
		if (s == null)
		{
			return;
		}
		s.take(item, qty);
		if (s.isEmpty())
		{
			stores.remove(s.key);
		}
		else
		{
			s.until = soonest(s);
		}
	}

	/**
	 * Lets dropped items whose time has come go.
	 *
	 * @return what vanished, by the store it lay in
	 */
	public Map<Store, Map<Integer, Long>> expire(long now)
	{
		Map<Store, Map<Integer, Long>> gone = new LinkedHashMap<>();
		for (Store s : stores(Kind.FLOOR))
		{
			Map<Integer, Long> lost = new LinkedHashMap<>();
			if (s.expires != null)
			{
				for (Map.Entry<Integer, Long> e : new ArrayList<>(s.expires.entrySet()))
				{
					if (e.getValue() <= now)
					{
						lost.put(e.getKey(), s.take(e.getKey(), Long.MAX_VALUE));
					}
				}
			}
			if (s.isEmpty() || s.expires == null || s.expires.isEmpty())
			{
				stores.remove(s.key);
			}
			else
			{
				s.until = soonest(s);
			}
			lost.values().removeIf(q -> q <= 0);
			if (!lost.isEmpty())
			{
				gone.put(s, lost);
			}
		}
		return gone;
	}

	private static long soonest(Store s)
	{
		long t = Long.MAX_VALUE;
		for (long u : s.expires.values())
		{
			t = Math.min(t, u);
		}
		return t == Long.MAX_VALUE ? 0 : t;
	}

	/** Everything the account holds, carried and kept, for the rest of the suite. */
	public Map<Integer, Long> holdings()
	{
		Map<Integer, Long> all = carried();
		for (Store s : stores.values())
		{
			Items.add(all, s.items);
		}
		return all;
	}

	// ---- packing lists ----

	public List<Trip> trips()
	{
		return Collections.unmodifiableList(trips);
	}

	public Trip trip(String name)
	{
		for (Trip t : trips)
		{
			if (t.name.equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}

	/** Saves a packing list, replacing one of the same name. */
	public void save(Trip trip)
	{
		trips.removeIf(t -> t.name.equalsIgnoreCase(trip.name));
		trips.add(0, trip);
		while (trips.size() > TRIPS)
		{
			trips.remove(trips.size() - 1);
		}
	}

	public void forget(String name)
	{
		trips.removeIf(t -> t.name.equalsIgnoreCase(name));
		if (name.equalsIgnoreCase(active))
		{
			active = null;
		}
	}

	public Trip activeTrip()
	{
		return active == null ? null : trip(active);
	}

	// ---- the route ----

	public Set<String> ticked()
	{
		return Collections.unmodifiableSet(ticked);
	}

	public void tick(String step, boolean done)
	{
		if (done)
		{
			ticked.add(step);
		}
		else
		{
			ticked.remove(step);
		}
	}

	// ---- saving ----

	public String write(Gson gson)
	{
		return gson.toJson(this);
	}

	/** What reading a save gave: the account's data, and whether any part of it had to be dropped. */
	public static final class Loaded
	{
		public final Nomad nomad;
		public final boolean damaged;

		Loaded(Nomad nomad, boolean damaged)
		{
			this.nomad = nomad;
			this.damaged = damaged;
		}
	}

	/**
	 * Reads a save part by part, so one damaged part costs only that part: the rest of the
	 * account's places and lists come back as they were.
	 */
	public static Loaded read(Gson gson, String saved)
	{
		Nomad n = new Nomad();
		if (saved == null || saved.trim().isEmpty())
		{
			return new Loaded(n, false);
		}
		JsonObject o;
		try
		{
			JsonElement e = new JsonParser().parse(saved);
			if (!e.isJsonObject())
			{
				return new Loaded(n, true);
			}
			o = e.getAsJsonObject();
		}
		catch (RuntimeException ex)
		{
			return new Loaded(n, true);
		}
		boolean damaged = false;
		try
		{
			n.account = o.has("account") ? o.get("account").getAsInt() : -1;
			n.played = o.has("played") ? Math.max(0, o.get("played").getAsLong()) : 0;
		}
		catch (RuntimeException ex)
		{
			damaged = true;
		}
		try
		{
			n.following = o.has("following") && o.get("following").getAsBoolean();
			if (o.has("ticked") && o.get("ticked").isJsonArray())
			{
				for (JsonElement e : o.getAsJsonArray("ticked"))
				{
					if (e.isJsonPrimitive())
					{
						n.ticked.add(e.getAsString());
					}
				}
			}
		}
		catch (RuntimeException ex)
		{
			damaged = true;
		}
		try
		{
			n.active = o.has("active") && o.get("active").isJsonPrimitive() ? o.get("active").getAsString() : null;
		}
		catch (RuntimeException ex)
		{
			damaged = true;
		}
		Type packType = new TypeToken<Map<String, Map<Integer, Long>>>()
		{
		}.getType();
		Type longs = new TypeToken<Map<String, Long>>()
		{
		}.getType();
		Type touchedType = new TypeToken<Map<Integer, Long>>()
		{
		}.getType();
		try
		{
			Map<String, Map<Integer, Long>> pack = gson.fromJson(o.get("pack"), packType);
			if (pack != null)
			{
				pack.forEach((k, v) ->
				{
					if (k != null)
					{
						n.pack.put(k, Items.clean(v));
					}
				});
			}
			Map<String, Long> seen = gson.fromJson(o.get("packSeen"), longs);
			if (seen != null)
			{
				seen.forEach((k, v) ->
				{
					if (k != null && v != null)
					{
						n.packSeen.put(k, v);
					}
				});
			}
		}
		catch (RuntimeException ex)
		{
			damaged = true;
		}
		if (o.has("stores") && o.get("stores").isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("stores").entrySet())
			{
				try
				{
					Store s = gson.fromJson(e.getValue(), Store.class);
					if (s != null && s.key != null && s.kind != null)
					{
						s.items = Items.clean(s.items);
						if (s.expires == null)
						{
							s.expires = new LinkedHashMap<>();
						}
						n.stores.put(s.key, s);
					}
					else
					{
						damaged = true;
					}
				}
				catch (RuntimeException ex)
				{
					damaged = true;
				}
			}
		}
		try
		{
			Map<Integer, Long> touched = gson.fromJson(o.get("touched"), touchedType);
			if (touched != null)
			{
				touched.forEach((k, v) ->
				{
					if (k != null && v != null)
					{
						n.touched.put(k, v);
					}
				});
			}
		}
		catch (RuntimeException ex)
		{
			damaged = true;
		}
		if (o.has("losses") && o.get("losses").isJsonArray())
		{
			for (JsonElement e : o.getAsJsonArray("losses"))
			{
				try
				{
					Loss l = gson.fromJson(e, Loss.class);
					if (l != null && l.items != null && l.cause != null)
					{
						n.losses.add(l);
					}
				}
				catch (RuntimeException ex)
				{
					damaged = true;
				}
			}
		}
		try
		{
			if (o.has("lostWorth"))
			{
				n.lostWorth = o.get("lostWorth").getAsLong();
			}
		}
		catch (RuntimeException ex)
		{
			damaged = true;
		}
		if (o.has("trips") && o.get("trips").isJsonArray())
		{
			for (JsonElement e : o.getAsJsonArray("trips"))
			{
				try
				{
					Trip t = gson.fromJson(e, Trip.class);
					if (t != null && t.name != null && t.wants != null)
					{
						t.wants.removeIf(w -> w == null || w.item <= 0 || w.qty <= 0);
						n.trips.add(t);
					}
					else
					{
						damaged = true;
					}
				}
				catch (RuntimeException ex)
				{
					damaged = true;
				}
			}
		}
		return new Loaded(n, damaged);
	}
}

package com.codex.nomad.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;

/**
 * The noting atlas: everyone outside a bank who turns items into banknotes or back, and which
 * items they take. For each stack an ultimate ironman carries it finds the nearest way to note or
 * unnote it.
 */
public final class Notary
{
	/** Which way a merchant turns items. */
	public enum Way
	{
		NOTE, UNNOTE
	}

	/** One merchant. */
	public static final class Desk
	{
		public final String who;
		public final String where;
		public final Way way;
		/** Coins per item, -1 when the fee is small but not known, 0 when free. */
		public final int fee;
		public final boolean wilderness;
		/** Map tile, or plane -1 for many places (any farming patch, your house). */
		public final int x;
		public final int y;
		public final int plane;
		final Predicate<String> takes;
		public final String takesText;

		Desk(String who, String where, Way way, int fee, boolean wilderness, int x, int y, int plane, String takesText, Predicate<String> takes)
		{
			this.who = who;
			this.where = where;
			this.way = way;
			this.fee = fee;
			this.wilderness = wilderness;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.takesText = takesText;
			this.takes = takes;
		}

		public boolean takes(String item)
		{
			return item != null && takes.test(item.toLowerCase(Locale.ENGLISH));
		}

		public int distance(int[] here)
		{
			if (here == null || plane < 0 || here[2] != plane)
			{
				return -1;
			}
			return Math.max(Math.abs(x - here[0]), Math.abs(y - here[1]));
		}
	}

	/** Advice for one carried stack. */
	public static final class Advice
	{
		public final int item;
		public final String name;
		public final long qty;
		public final Way way;
		/** Merchants that take it, nearest first. */
		public final List<Desk> desks;
		/** Inventory slots noting it would free, or 0 for unnoting. */
		public final int frees;

		Advice(int item, String name, long qty, Way way, List<Desk> desks, int frees)
		{
			this.item = item;
			this.name = name;
			this.qty = qty;
			this.way = way;
			this.desks = desks;
			this.frees = frees;
		}

		public Desk best()
		{
			return desks.isEmpty() ? null : desks.get(0);
		}
	}

	private static final Set<String> RESOURCE_AREA = set("coal", "iron ore", "gold ore", "mithril ore", "adamantite ore",
		"runite ore", "yew logs", "magic logs", "raw dark crab", "bronze bar", "iron bar", "steel bar", "gold bar",
		"mithril bar", "adamantite bar", "runite bar", "silver bar");
	private static final Set<String> PRODUCE = set("potato", "onion", "cabbage", "tomato", "sweetcorn", "strawberry",
		"watermelon", "snape grass", "marigolds", "rosemary", "nasturtiums", "woad leaf", "limpwurt root", "white lily",
		"barley", "hammerstone hops", "asgarnian hops", "jute fibre", "yanillian hops", "krandorian hops", "wildblood hops",
		"redberries", "cadava berries", "dwellberries", "jangerberries", "whiteberries", "poison ivy berries",
		"cooking apple", "banana", "orange", "curry leaf", "pineapple", "papaya fruit", "coconut", "dragonfruit",
		"giant seaweed", "mushroom", "cactus spine", "potato cactus", "calquat fruit", "grapes", "white tree fruit");

	public static final List<Desk> DESKS = Collections.unmodifiableList(Arrays.asList(
		new Desk("Tool leprechaun", "any farming patch", Way.NOTE, 0, false, 0, 0, -1,
			"Crops, herbs and fruit you grew", n -> PRODUCE.contains(n) || n.startsWith("grimy ")),
		new Desk("Piles", "Wilderness Resource Area", Way.NOTE, 50, true, 3184, 3934, 0,
			"Ores, coal, bars, yew and magic logs, dark crabs", RESOURCE_AREA::contains),
		new Desk("Phials", "Rimmington", Way.UNNOTE, 5, false, 2949, 3213, 0, "Any noted item", n -> true),
		new Desk("Banknote exchange merchant", "Pollnivneach", Way.UNNOTE, -1, false, 3359, 2972, 0, "Any noted item", n -> true),
		new Desk("Tiles", "the Bandit Camp", Way.UNNOTE, -1, false, 3172, 2978, 0, "Any noted item", n -> true),
		new Desk("Elder Chaos druid", "the Chaos Temple, Wilderness", Way.UNNOTE, 50, true, 3239, 3619, 0, "Bones only",
			n -> n.endsWith("bones")),
		new Desk("Your servant", "your house", Way.UNNOTE, -1, false, 0, 0, -1, "Anything but bones",
			n -> !n.endsWith("bones"))
	));

	private static Set<String> set(String... names)
	{
		return new HashSet<>(Arrays.asList(names));
	}

	private Notary()
	{
	}

	/** Merchants that turn an item the given way, nearest first; ones with no fixed place last. */
	public static List<Desk> desks(String name, Way way, int[] here)
	{
		List<Desk> out = new ArrayList<>();
		for (Desk d : DESKS)
		{
			if (d.way == way && d.takes(name))
			{
				out.add(d);
			}
		}
		out.sort((a, b) ->
		{
			int da = a.distance(here);
			int db = b.distance(here);
			if (da < 0 || db < 0)
			{
				return Boolean.compare(da < 0, db < 0);
			}
			return Integer.compare(da, db);
		});
		return out;
	}

	/**
	 * @param name the item's name, unnoted
	 * @param qty how many are carried
	 * @param noted true when the stack is banknotes
	 * @param here the player's tile, or null
	 * @return what to do with the stack, or null when nothing applies or it is not worth a trip
	 */
	public static Advice advise(int item, String name, long qty, boolean noted, int[] here)
	{
		if (noted)
		{
			List<Desk> d = desks(name, Way.UNNOTE, here);
			return d.isEmpty() ? null : new Advice(item, name, qty, Way.UNNOTE, d, 0);
		}
		if (qty < 2)
		{
			return null;
		}
		List<Desk> d = desks(name, Way.NOTE, here);
		return d.isEmpty() ? null : new Advice(item, name, qty, Way.NOTE, d, (int) Math.min(27, qty - 1));
	}
}

package com.codex.nomad.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;

/** The order to pick a pile up in: the most worth for each inventory slot first. */
public final class Pickup
{
	private Pickup()
	{
	}

	public static List<Integer> order(Map<Integer, Long> pile, IntToLongFunction price, IntPredicate stackable)
	{
		List<Integer> out = new ArrayList<>(pile.keySet());
		out.sort((a, b) -> Long.compare(perSlot(b, pile.get(b), price, stackable), perSlot(a, pile.get(a), price, stackable)));
		return out;
	}

	static long perSlot(int item, long qty, IntToLongFunction price, IntPredicate stackable)
	{
		return stackable.test(item) ? price.applyAsLong(item) * qty : price.applyAsLong(item);
	}
}

package com.codex.nomad.core;

/** What one of an item is worth, in coins. */
public interface Prices
{
	long each(int item);

	Prices NONE = item -> 0;
}

package com.codex.nomad.core;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The ultimate ironman route to Prifddinas, step by step, paraphrased from the OSRS Wiki's
 * walkthrough. Each step says how the game shows it is done:
 * <ul>
 * <li>lasting checks (quests, levels, quest points, unlocks, diaries, combat achievements) are read
 * from the game at any time;</li>
 * <li>moment checks (items held or owned, a place reached, an empty inventory, coins carried, a chat
 * line, a deathbank, where your house is) are watched while the step is in hand and tick it the
 * moment they all hold;</li>
 * <li>a step with no check of its own counts as done once the next step the game can confirm is
 * done, since the route is followed in order.</li>
 * </ul>
 * Each step can also name where to go and who to talk to, for the in-game guidance.
 */
public final class Route
{
	public static final String SOURCE = "https://oldschool.runescape.wiki/w/Guide:Ultimate_Ironman_Walkthrough_Guide_To_Prifddinas";

	/** A varbit or varp test: id, then the value it must reach (or equal, when exact). */
	public static final class Var
	{
		public final int id;
		public final int value;
		public final boolean exact;
		/** A bit that must be set, written id&amp;bit, as the diaries keep their tasks; -1 for a value. */
		public final int bit;

		Var(int id, int value, boolean exact)
		{
			this(id, value, exact, -1);
		}

		Var(int id, int value, boolean exact, int bit)
		{
			this.id = id;
			this.value = value;
			this.exact = exact;
			this.bit = bit;
		}

		boolean test(int now)
		{
			if (bit >= 0)
			{
				return (now >> bit & 1) == 1;
			}
			return exact ? now == value : now >= value;
		}
	}

	/** One step. */
	public static final class Step
	{
		public final int index;
		public final String section;
		public final String text;
		public final List<String> tips = new ArrayList<>();

		// lasting checks
		public final List<String> quests = new ArrayList<>();
		public final List<String> started = new ArrayList<>();
		/** Skill name to level. */
		public final Map<String, Integer> skills = new LinkedHashMap<>();
		public int questPoints;
		public int combat;
		public final List<Var> varbits = new ArrayList<>();
		public final List<Var> varps = new ArrayList<>();
		/** Combat achievement tier that must be complete: easy, medium... */
		public String tier;

		// moment checks
		public final List<String> items = new ArrayList<>();
		public final List<String> owned = new ArrayList<>();
		public final List<String> gone = new ArrayList<>();
		/** x, y, plane, reach. */
		public int[] at;
		/** x1, y1, x2, y2, plane (-1 any). */
		public int[] area;
		/** Inventory empty but for these names; null when not checked. */
		public List<String> emptyBut;
		/** Coins carried at least this many (or at most, when coinsAtMost). */
		public long coins = -1;
		public boolean coinsAtMost;
		public final List<String> chat = new ArrayList<>();
		/** True: a deathbank must exist; false: none may; null: not checked. */
		public Boolean deathbank;
		/** The POH_HOUSE_LOCATION value the house must be in, or -1. */
		public int house = -1;
		/** Furniture to see built in your house: each entry is a set of object ids, any of which will do. */
		public final List<int[]> built = new ArrayList<>();

		// guidance
		/** x, y, plane to head for, or null. */
		public int[] go;
		/** Head for your house portal, wherever the house is. */
		public boolean goHouse;
		public final List<String> npcs = new ArrayList<>();
		public final List<Integer> npcIds = new ArrayList<>();
		/** Objects to click, by id. */
		public final List<Integer> objects = new ArrayList<>();
		/** Items to click in the inventory, by name. */
		public final List<String> use = new ArrayList<>();
		/** Items to buy in a shop, by name. */
		public final List<String> shop = new ArrayList<>();
		/** Items to pick up off the ground, by name. */
		public final List<String> ground = new ArrayList<>();
		/** Chat options to choose, by their text. */
		public final List<String> say = new ArrayList<>();
		public boolean optional;

		Step(int index, String section, String text)
		{
			this.index = index;
			this.section = section;
			this.text = text;
		}

		/** A key that survives steps being added elsewhere in the route. */
		public String key()
		{
			return Integer.toHexString((section + "|" + text).toLowerCase(Locale.ENGLISH).hashCode());
		}

		/** True when the step has a check the game can read at any time. */
		public boolean lasting()
		{
			return !quests.isEmpty() || !started.isEmpty() || !skills.isEmpty() || questPoints > 0 || combat > 0
				|| !varbits.isEmpty() || !varps.isEmpty() || tier != null;
		}

		/** True when the step has a check that only holds in the moment. */
		public boolean moment()
		{
			return !items.isEmpty() || !owned.isEmpty() || !gone.isEmpty() || at != null || area != null || emptyBut != null
				|| coins >= 0 || !chat.isEmpty() || deathbank != null || house >= 0 || !built.isEmpty();
		}

		/** True when the game confirms the step for good, so it cannot be unticked. */
		public boolean checkable()
		{
			return lasting() && !moment();
		}

		/** True when the game ticks this step by any means. */
		public boolean watched()
		{
			return lasting() || moment();
		}
	}

	/** Everything to click for a step: people, objects, items in the inventory, a shop or on the ground, chat options. */
	public static final class Lead
	{
		public final List<String> npcs = new ArrayList<>();
		public final List<Integer> npcIds = new ArrayList<>();
		public final List<Integer> objects = new ArrayList<>();
		public final List<String> use = new ArrayList<>();
		public final List<String> shop = new ArrayList<>();
		public final List<String> ground = new ArrayList<>();
		public final List<String> say = new ArrayList<>();

		public boolean isEmpty()
		{
			return npcs.isEmpty() && npcIds.isEmpty() && objects.isEmpty() && use.isEmpty() && shop.isEmpty() && ground.isEmpty() && say.isEmpty();
		}
	}

	/** What the game says about the player for good. */
	public interface Account
	{
		boolean questDone(String quest);

		int level(String skill);

		default boolean questStarted(String quest)
		{
			return questDone(quest);
		}

		default int questPoints()
		{
			return 0;
		}

		default int combat()
		{
			return 0;
		}

		default int varbit(int id)
		{
			return 0;
		}

		default int varp(int id)
		{
			return 0;
		}

		default boolean tierDone(String tier)
		{
			return false;
		}
	}

	/** What is true this moment, for the checks watched while a step is in hand. */
	public interface Moment
	{
		/** Carried, worn, in the looting bag or rune pouch, by name in lower case. */
		boolean held(String name);

		/** Held or kept in any store Nomad knows. */
		default boolean owned(String name)
		{
			return held(name);
		}

		/** x, y, plane, or null when not logged in. */
		int[] here();

		/** Names in the inventory, in lower case. */
		List<String> inventory();

		long coins();

		/** True when a game message containing this text arrived lately. */
		boolean heard(String text);

		boolean deathbank();

		/** True when one of these objects is in the scene now. */
		default boolean sees(int[] objects)
		{
			return false;
		}
	}

	private final List<Step> steps;
	private final List<String> sections;
	/** For each step, the index of the next lasting step after it, or -1. */
	private final int[] nextLasting;
	private final Map<String, int[]> questStarts;
	/** Who or what starts each quest: npc or object ids, the first entry 0 for npcs and 1 for objects. */
	private final Map<String, int[]> questLeads;

	private Route(List<Step> steps, Map<String, int[]> questStarts, Map<String, int[]> questLeads)
	{
		this.steps = steps;
		this.questStarts = questStarts;
		this.questLeads = questLeads;
		List<String> s = new ArrayList<>();
		for (Step step : steps)
		{
			if (!s.contains(step.section))
			{
				s.add(step.section);
			}
		}
		sections = s;
		nextLasting = new int[steps.size()];
		int next = -1;
		for (int i = steps.size() - 1; i >= 0; i--)
		{
			nextLasting[i] = next;
			if (steps.get(i).checkable() && !steps.get(i).optional)
			{
				next = i;
			}
		}
	}

	public static Route load()
	{
		List<String> starts = lines("/com/codex/nomad/quest-starts.txt");
		return parse(lines("/com/codex/nomad/route.txt"), starts(starts), leads(starts));
	}

	private static List<String> lines(String resource)
	{
		List<String> lines = new ArrayList<>();
		try (InputStream in = Route.class.getResourceAsStream(resource))
		{
			if (in != null)
			{
				BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
				String line;
				while ((line = r.readLine()) != null)
				{
					lines.add(line);
				}
			}
		}
		catch (Exception ignored)
		{
			// A missing resource leaves the route empty.
		}
		return lines;
	}

	/** Lines of "quest | x,y,plane | npc:ids or obj:ids". */
	static Map<String, int[]> starts(List<String> lines)
	{
		Map<String, int[]> out = new HashMap<>();
		for (String line : lines)
		{
			String[] parts = line.split("\\|");
			if (line.startsWith("#") || parts.length < 2)
			{
				continue;
			}
			try
			{
				int[] p = ints(parts[1]);
				if (p.length == 3)
				{
					out.put(parts[0].trim(), p);
				}
			}
			catch (RuntimeException ignored)
			{
				// A malformed line names no place.
			}
		}
		return out;
	}

	static Map<String, int[]> leads(List<String> lines)
	{
		Map<String, int[]> out = new HashMap<>();
		for (String line : lines)
		{
			String[] parts = line.split("\\|");
			if (line.startsWith("#") || parts.length < 3)
			{
				continue;
			}
			String lead = parts[2].trim();
			int colon = lead.indexOf(':');
			try
			{
				int[] ids = ints(lead.substring(colon + 1));
				int[] entry = new int[ids.length + 1];
				entry[0] = lead.startsWith("obj") ? 1 : 0;
				System.arraycopy(ids, 0, entry, 1, ids.length);
				out.put(parts[0].trim(), entry);
			}
			catch (RuntimeException ignored)
			{
				// A malformed lead names no one.
			}
		}
		return out;
	}

	static Route parse(List<String> lines)
	{
		return parse(lines, Collections.emptyMap(), Collections.emptyMap());
	}

	static Route parse(List<String> lines, Map<String, int[]> questStarts, Map<String, int[]> questLeads)
	{
		List<Step> steps = new ArrayList<>();
		for (String raw : lines)
		{
			String line = raw.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			if (line.startsWith("~"))
			{
				if (!steps.isEmpty())
				{
					steps.get(steps.size() - 1).tips.add(line.substring(1).trim());
				}
				continue;
			}
			String[] parts = line.split("\\|", -1);
			if (parts.length < 2)
			{
				continue;
			}
			Step step = new Step(steps.size(), parts[0].trim(), parts[1].trim());
			if (parts.length > 2)
			{
				for (String tag : parts[2].split(";"))
				{
					tag(step, tag.trim());
				}
			}
			steps.add(step);
		}
		return new Route(steps, questStarts, questLeads);
	}

	private static void tag(Step step, String tag)
	{
		int colon = tag.indexOf(':');
		String kind = colon < 0 ? tag : tag.substring(0, colon).trim();
		String value = colon < 0 ? "" : tag.substring(colon + 1).trim();
		try
		{
			switch (kind)
			{
				case "quest":
					step.quests.add(value);
					break;
				case "started":
					step.started.add(value);
					break;
				case "skill":
				{
					int space = value.lastIndexOf(' ');
					step.skills.put(value.substring(0, space).trim(), Integer.parseInt(value.substring(space + 1).trim()));
					break;
				}
				case "qp":
					step.questPoints = Integer.parseInt(value);
					break;
				case "combat":
					step.combat = Integer.parseInt(value);
					break;
				case "varbit":
					step.varbits.add(var(value));
					break;
				case "varp":
					step.varps.add(var(value));
					break;
				case "ca":
					step.tier = value.toLowerCase(Locale.ENGLISH);
					break;
				case "item":
					step.items.add(value);
					break;
				case "owned":
					step.owned.add(value);
					break;
				case "gone":
					step.gone.add(value);
					break;
				case "at":
				{
					int[] p = ints(value);
					step.at = new int[]{p[0], p[1], p.length > 2 ? p[2] : 0, p.length > 3 ? p[3] : 8};
					break;
				}
				case "area":
				{
					int[] p = ints(value);
					step.area = new int[]{Math.min(p[0], p[2]), Math.min(p[1], p[3]), Math.max(p[0], p[2]), Math.max(p[1], p[3]),
						p.length > 4 ? p[4] : -1};
					break;
				}
				case "empty":
				{
					List<String> allow = new ArrayList<>();
					for (String a : value.split(","))
					{
						if (!a.trim().isEmpty())
						{
							allow.add(a.trim().toLowerCase(Locale.ENGLISH));
						}
					}
					step.emptyBut = allow;
					break;
				}
				case "coins":
					step.coinsAtMost = value.startsWith("<");
					step.coins = Long.parseLong(value.replace("<", "").replace(">", "").replace("=", "").trim());
					break;
				case "chat":
					step.chat.add(value);
					break;
				case "deathbank":
					step.deathbank = true;
					break;
				case "nodeathbank":
					step.deathbank = false;
					break;
				case "built":
				{
					List<Integer> ids = new ArrayList<>();
					for (String part : value.split(","))
					{
						String[] range = part.trim().split("-");
						int from = Integer.parseInt(range[0].trim());
						int to = range.length > 1 ? Integer.parseInt(range[1].trim()) : from;
						for (int id = from; id <= to; id++)
						{
							ids.add(id);
						}
					}
					int[] set = new int[ids.size()];
					for (int i = 0; i < set.length; i++)
					{
						set[i] = ids.get(i);
					}
					step.built.add(set);
					break;
				}
				case "house":
					step.house = Integer.parseInt(value);
					break;
				case "go":
				{
					if (value.equals("house"))
					{
						step.goHouse = true;
						break;
					}
					int[] p = ints(value);
					step.go = new int[]{p[0], p[1], p.length > 2 ? p[2] : 0};
					break;
				}
				case "npc":
					step.npcs.add(value);
					break;
				case "npcid":
					for (int id : ids(value))
					{
						step.npcIds.add(id);
					}
					break;
				case "obj":
					for (int id : ids(value))
					{
						step.objects.add(id);
					}
					break;
				case "use":
					step.use.add(value);
					break;
				case "shop":
					step.shop.add(value);
					break;
				case "ground":
					step.ground.add(value);
					break;
				case "say":
					step.say.add(value);
					break;
				case "optional":
					step.optional = true;
					break;
				default:
					break;
			}
		}
		catch (RuntimeException ignored)
		{
			// A malformed tag checks nothing.
		}
	}

	private static Var var(String value)
	{
		String v = value.replace(" ", "");
		if (v.contains("&"))
		{
			String[] p = v.split("&");
			return new Var(Integer.parseInt(p[0]), 1, false, Integer.parseInt(p[1]));
		}
		boolean exact = v.contains("=") && !v.contains(">=");
		String[] p = v.split(">=|=");
		return new Var(Integer.parseInt(p[0]), p.length > 1 ? Integer.parseInt(p[1]) : 1, exact);
	}

	/** Ids separated by commas, with ranges written a-b. */
	private static int[] ids(String value)
	{
		List<Integer> ids = new ArrayList<>();
		for (String part : value.split(","))
		{
			String[] range = part.trim().split("-");
			int from = Integer.parseInt(range[0].trim());
			int to = range.length > 1 ? Integer.parseInt(range[1].trim()) : from;
			for (int id = from; id <= to; id++)
			{
				ids.add(id);
			}
		}
		int[] out = new int[ids.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = ids.get(i);
		}
		return out;
	}

	private static int[] ints(String s)
	{
		String[] p = s.split(",");
		int[] out = new int[p.length];
		for (int i = 0; i < p.length; i++)
		{
			out[i] = Integer.parseInt(p[i].trim());
		}
		return out;
	}

	public List<Step> steps()
	{
		return Collections.unmodifiableList(steps);
	}

	public List<String> sections()
	{
		return Collections.unmodifiableList(sections);
	}

	public int size()
	{
		return steps.size();
	}

	/** True when every lasting check of a step holds; false for a step with none. */
	public static boolean lastingMet(Step s, Account a)
	{
		if (!s.lasting() || a == null)
		{
			return false;
		}
		for (String q : s.quests)
		{
			if (!a.questDone(q))
			{
				return false;
			}
		}
		for (String q : s.started)
		{
			if (!a.questStarted(q))
			{
				return false;
			}
		}
		for (Map.Entry<String, Integer> e : s.skills.entrySet())
		{
			if (a.level(e.getKey()) < e.getValue())
			{
				return false;
			}
		}
		if (s.questPoints > 0 && a.questPoints() < s.questPoints || s.combat > 0 && a.combat() < s.combat)
		{
			return false;
		}
		for (Var v : s.varbits)
		{
			if (!v.test(a.varbit(v.id)))
			{
				return false;
			}
		}
		for (Var v : s.varps)
		{
			if (!v.test(a.varp(v.id)))
			{
				return false;
			}
		}
		return s.tier == null || a.tierDone(s.tier);
	}

	/** True when the game confirms a step for good: lasting checks only, all holding. */
	public static boolean met(Step s, Account a)
	{
		return s.checkable() && lastingMet(s, a);
	}

	/** True when every check of a step holds right now. */
	public static boolean now(Step s, Account a, Moment m)
	{
		if (!s.watched() || m == null || s.lasting() && !lastingMet(s, a))
		{
			return false;
		}
		for (String i : s.items)
		{
			if (!m.held(i.toLowerCase(Locale.ENGLISH)))
			{
				return false;
			}
		}
		for (String i : s.owned)
		{
			if (!m.owned(i.toLowerCase(Locale.ENGLISH)))
			{
				return false;
			}
		}
		for (String i : s.gone)
		{
			if (m.held(i.toLowerCase(Locale.ENGLISH)))
			{
				return false;
			}
		}
		int[] here = m.here();
		if ((s.at != null || s.area != null) && here == null)
		{
			return false;
		}
		if (s.at != null && (here[2] != s.at[2] || Math.max(Math.abs(here[0] - s.at[0]), Math.abs(here[1] - s.at[1])) > s.at[3]))
		{
			return false;
		}
		if (s.area != null && (here[0] < s.area[0] || here[0] > s.area[2] || here[1] < s.area[1] || here[1] > s.area[3]
			|| s.area[4] >= 0 && here[2] != s.area[4]))
		{
			return false;
		}
		if (s.emptyBut != null)
		{
			for (String i : m.inventory())
			{
				if (!s.emptyBut.contains(i))
				{
					return false;
				}
			}
		}
		if (s.coins >= 0 && (s.coinsAtMost ? m.coins() > s.coins : m.coins() < s.coins))
		{
			return false;
		}
		for (String c : s.chat)
		{
			if (!m.heard(c))
			{
				return false;
			}
		}
		if (s.deathbank != null && m.deathbank() != s.deathbank)
		{
			return false;
		}
		for (int[] set : s.built)
		{
			if (!m.sees(set))
			{
				return false;
			}
		}
		return s.house < 0 || a != null && a.varbit(HOUSE_VARBIT) == s.house;
	}

	/** VarbitID.POH_HOUSE_LOCATION. */
	public static final int HOUSE_VARBIT = 2187;
	/** The house portal for each POH_HOUSE_LOCATION value. */
	static final Map<Integer, int[]> HOUSE_PORTALS = new HashMap<>();

	static
	{
		HOUSE_PORTALS.put(1, new int[]{2954, 3224, 0});
		HOUSE_PORTALS.put(2, new int[]{2894, 3465, 0});
		HOUSE_PORTALS.put(3, new int[]{3340, 3004, 0});
		HOUSE_PORTALS.put(4, new int[]{2670, 3632, 0});
		HOUSE_PORTALS.put(5, new int[]{2758, 3178, 0});
		HOUSE_PORTALS.put(6, new int[]{2544, 3096, 0});
		HOUSE_PORTALS.put(8, new int[]{1743, 3517, 0});
	}

	/** True when the step is done: ticked by hand or in the moment, met in game, or passed. */
	public boolean done(Step s, Set<String> ticked, Account a)
	{
		return ticked.contains(s.key()) || met(s, a) || passed(s, a);
	}

	/**
	 * True when a step the game cannot confirm for good lies behind one it has confirmed: the route
	 * runs in order, so the player is past it.
	 */
	public boolean passed(Step s, Account a)
	{
		if (s.checkable())
		{
			return false;
		}
		int next = nextLasting[s.index];
		return next >= 0 && met(steps.get(next), a);
	}

	/** The first step not yet done, skipping optional ones, or null when the route is finished. */
	public Step current(Set<String> ticked, Account a)
	{
		for (Step s : steps)
		{
			if (!s.optional && !done(s, ticked, a))
			{
				return s;
			}
		}
		return null;
	}

	public int doneCount(Set<String> ticked, Account a)
	{
		int n = 0;
		for (Step s : steps)
		{
			if (done(s, ticked, a))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * The steps in hand whose moment checks all hold now, in order: each ticks, and the one after it
	 * is tried in turn.
	 */
	public List<Step> observe(Set<String> ticked, Account a, Moment m)
	{
		List<Step> out = new ArrayList<>();
		java.util.HashSet<String> t = new java.util.HashSet<>(ticked);
		for (int guard = 0; guard < 8; guard++)
		{
			Step s = current(t, a);
			if (s == null || !s.moment() || !now(s, a, m))
			{
				break;
			}
			out.add(s);
			t.add(s.key());
		}
		return out;
	}

	/** Where to head for a step: its own place, or where the first quest it needs starts. */
	public int[] target(Step s, Account a)
	{
		if (s.go != null)
		{
			return s.go;
		}
		if (s.goHouse && a != null)
		{
			int[] portal = HOUSE_PORTALS.get(a.varbit(HOUSE_VARBIT));
			if (portal != null)
			{
				return portal;
			}
		}
		if (s.at != null)
		{
			return new int[]{s.at[0], s.at[1], s.at[2]};
		}
		if (s.area != null)
		{
			return new int[]{(s.area[0] + s.area[2]) / 2, (s.area[1] + s.area[3]) / 2, Math.max(0, s.area[4])};
		}
		List<String> qs = new ArrayList<>(s.started);
		qs.addAll(s.quests);
		for (String q : qs)
		{
			if (a != null && (s.started.contains(q) ? a.questStarted(q) : a.questDone(q)))
			{
				continue;
			}
			int[] p = questStarts.get(q);
			if (p != null)
			{
				return p;
			}
		}
		return null;
	}

	/**
	 * What to click for a step: what it names, the items it asks for (bought in a shop when the
	 * step is to buy them, picked up when it is to take them), and who starts the quest it needs.
	 */
	public Lead lead(Step s, Account a)
	{
		Lead l = new Lead();
		if (s == null)
		{
			return l;
		}
		l.npcs.addAll(s.npcs);
		l.npcIds.addAll(s.npcIds);
		l.objects.addAll(s.objects);
		l.use.addAll(s.use);
		l.shop.addAll(s.shop);
		l.ground.addAll(s.ground);
		l.say.addAll(s.say);
		String verb = s.text.toLowerCase(Locale.ENGLISH);
		if (verb.startsWith("buy ") || verb.contains(", buy ") || verb.contains(" and buy ") || verb.contains(" then buy "))
		{
			l.shop.addAll(s.items);
		}
		if (verb.startsWith("take ") || verb.startsWith("pick up "))
		{
			l.ground.addAll(s.items);
		}
		List<String> qs = new ArrayList<>(s.started);
		qs.addAll(s.quests);
		for (String q : qs)
		{
			if (a != null && a.questStarted(q))
			{
				continue;
			}
			int[] lead = questLeads.get(q);
			if (lead != null)
			{
				for (int i = 1; i < lead.length; i++)
				{
					(lead[0] == 1 ? l.objects : l.npcIds).add(lead[i]);
				}
				break;
			}
		}
		return l;
	}

	/** The quest a step needs that is under way but not done, or null: inside it, Quest Helper leads. */
	public static String inQuest(Step s, Account a)
	{
		if (s == null || a == null)
		{
			return null;
		}
		for (String q : s.quests)
		{
			if (a.questStarted(q) && !a.questDone(q))
			{
				return q;
			}
		}
		return null;
	}

	/** Where a quest starts, or null. */
	public int[] questStart(String quest)
	{
		return questStarts.get(quest);
	}

	/** How far through a section the player is: done and total. */
	public int[] section(String name, Set<String> ticked, Account a)
	{
		int done = 0;
		int all = 0;
		for (Step s : steps)
		{
			if (s.section.equals(name))
			{
				all++;
				if (done(s, ticked, a))
				{
					done++;
				}
			}
		}
		return new int[]{done, all};
	}
}

package com.codex.nomad.core;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Which emote-clue items each STASH unit takes, so a carried item can be told where it belongs.
 * Read once from the plugin's own data.
 */
public final class StashBook
{
	/** One STASH unit's needs, as written in the data. */
	public static final class Unit
	{
		public String place;
		public String chart;
		public List<Need> needs = new ArrayList<>();
	}

	/** One thing a unit needs: any one of these items. */
	public static final class Need
	{
		public String name;
		public List<Integer> ids = new ArrayList<>();
	}

	/** A unit an item belongs in. */
	public static final class Home
	{
		public final String unit;
		public final String place;
		public final String chart;

		Home(String unit, String place, String chart)
		{
			this.unit = unit;
			this.place = place;
			this.chart = chart;
		}
	}

	private final Map<String, Unit> units;
	private final Map<Integer, List<Home>> homes = new HashMap<>();

	StashBook(Map<String, Unit> units)
	{
		this.units = units;
		units.forEach((k, u) ->
		{
			for (Need n : u.needs)
			{
				for (int id : n.ids)
				{
					homes.computeIfAbsent(id, i -> new ArrayList<>()).add(new Home(k, u.place, u.chart));
				}
			}
		});
	}

	public static StashBook load(Gson gson)
	{
		Type type = new TypeToken<LinkedHashMap<String, Unit>>()
		{
		}.getType();
		try (InputStream in = StashBook.class.getResourceAsStream("/com/codex/nomad/stash.json"))
		{
			if (in == null)
			{
				return new StashBook(Collections.emptyMap());
			}
			Map<String, Unit> units = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
			return new StashBook(units == null ? Collections.emptyMap() : units);
		}
		catch (Exception e)
		{
			return new StashBook(Collections.emptyMap());
		}
	}

	public Unit unit(String name)
	{
		return units.get(name);
	}

	public int size()
	{
		return units.size();
	}

	/** Every STASH unit that takes an item, or none. */
	public List<Home> homes(int item)
	{
		List<Home> h = homes.get(item);
		return h == null ? Collections.emptyList() : Collections.unmodifiableList(h);
	}
}

package com.codex.nomad.core;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/** One place things are kept outside the player's pockets, as last seen. */
public final class Store
{
	public String key;
	public Kind kind = Kind.OTHER;
	public String name;
	/** Items by id, as the game holds them. */
	public Map<Integer, Long> items = new LinkedHashMap<>();
	/** When the contents were last seen, epoch ms. */
	public long seen;
	/** False while the contents are a guess, such as a deathbank worked out from a death. */
	public boolean exact = true;
	/** Where it is, or plane -1 for nowhere in particular. */
	public int x;
	public int y;
	public int plane = -1;
	/** When it began, epoch ms: the death that made a pile or a deathbank. */
	public long since;
	/** Game ticks of logged-in time left before a deathpile vanishes, or -1 for no timer. */
	public long ticksLeft = -1;
	/** When dropped items vanish, epoch ms, or 0 for no deadline. */
	public long until;
	/** The world dropped items lie on, or 0. */
	public int world;
	/** When each dropped item vanishes, epoch ms. */
	public Map<Integer, Long> expires = new LinkedHashMap<>();

	public Store()
	{
	}

	public Store(String key, Kind kind, String name)
	{
		this.key = key;
		this.kind = kind;
		this.name = name;
	}

	public Store at(int x, int y, int plane)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
		return this;
	}

	public boolean located()
	{
		return plane >= 0;
	}

	public long count(int item)
	{
		return items.getOrDefault(item, 0L);
	}

	public boolean isEmpty()
	{
		return items.isEmpty();
	}

	public Map<Integer, Long> view()
	{
		return Collections.unmodifiableMap(items);
	}

	/** Replaces the contents with what was just seen. */
	public void fill(Map<Integer, Long> seenItems, long now)
	{
		items = Items.clean(seenItems);
		seen = now;
		exact = true;
	}

	/** Takes up to n of an item out; returns how many came out. */
	public long take(int item, long n)
	{
		long have = count(item);
		long out = Math.min(have, Math.max(0, n));
		if (have - out <= 0)
		{
			items.remove(item);
			if (expires != null)
			{
				expires.remove(item);
			}
		}
		else
		{
			items.put(item, have - out);
		}
		return out;
	}
}

