import javax.swing.event.DocumentListener;
import net.runelite.client.ui.PluginPanel;

/**
 * The Nomad side panel: the crest, a search over everything owned, then four pages. Pack is everything carried with what is at
 * risk, dead weight and noting; Stores is every place things are kept; Trips is the packing lists
 * with the stops to make; Route is the way to Prifddinas step by step.
 */
public class NomadPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"pack", "stores", "trips", "route"};
	/** Route steps shown past the one in hand before "Show more". */
	private static final int AHEAD = 6;

	/** What the panel asks the plugin to do. */
	public interface Actions
	{
		void saveTrip(String name);

		void useTrip(String name);

		void forgetTrip(String name);

		void forgetStore(String key);

		void tickStep(String key, boolean done);

		void follow(boolean on);
	}

	private final ItemIcons icons;
	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Pack", "Stores", "Trips", "Route");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane[] pages = {scroller(), scroller(), scroller(), scroller()};
	private final boolean[] stale = {true, true, true, true};
	private final Set<String> open = new HashSet<>();
	private final Set<String> sectionsOpen = new HashSet<>();
	private final Field tripName = new Field("Name this setup");
	private final Field find = new Field("Find anything you own");
	private final JScrollPane findPage = scroller();
	private boolean findStale = true;
	private boolean routeAll;

	private View view = new View();

	public NomadPanel(ItemIcons icons, Actions actions)
	{
		super(false);
		this.icons = icons;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		JPanel findHolder = new JPanel(new BorderLayout());
		findHolder.setOpaque(false);
		findHolder.setBorder(new EmptyBorder(6, 0, 0, 0));
		findHolder.add(find, BorderLayout.CENTER);
		tabHolder.add(findHolder, BorderLayout.SOUTH);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		for (int i = 0; i < TABS.length; i++)
		{
			content.add(pages[i], TABS[i]);
		}
		content.add(findPage, "find");
		add(content, BorderLayout.CENTER);
		tabs.onChange(i ->
		{
			find.setText("");
			showTab(i);
		});
		find.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				onFind();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				onFind();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				onFind();
			}
		});
		tripName.addActionListener(e -> saveTrip());
		updateCrest();
		refresh(true);
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void show(View view)
	{
		this.view = view;
		updateCrest();
		java.util.Arrays.fill(stale, true);
		findStale = true;
		refresh(false);
	}

	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
		refresh(true);
	}

	@Override
	public void onActivate()
	{
		refresh(true);
	}

	private void refresh(boolean force)
	{
		if (!force && !isShowing())
		{
			return;
		}
		if (finding())
		{
			if (findStale)
			{
				findStale = false;
				show(findPage, found());
			}
			return;
		}
		int page = tabs.getSelected();
		if (!stale[page])
		{
			return;
		}
		stale[page] = false;
		JComponent body = page == 0 ? pack() : page == 1 ? stores() : page == 2 ? trips() : route();
		show(pages[page], body);
	}

	private static void show(JScrollPane scroll, JComponent body)
	{
		int y = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(body);
		scroll.revalidate();
		scroll.getVerticalScrollBar().setValue(y);
		scroll.repaint();
	}

	private boolean finding()
	{
		return !find.getText().trim().isEmpty();
	}

	private void onFind()
	{
		if (finding())
		{
			findStale = true;
			cards.show(content, "find");
			refresh(true);
			findPage.getVerticalScrollBar().setValue(0);
		}
		else
		{
			cards.show(content, TABS[tabs.getSelected()]);
			stale[tabs.getSelected()] = true;
			refresh(true);
		}
	}

	private void rebuild()
	{
		stale[tabs.getSelected()] = true;
		findStale = true;
		refresh(true);
	}

	// ---- the crest ----

	private void updateCrest()
	{
		View v = view;
		String heading = account(v.account).toUpperCase(Locale.ENGLISH);
		if (!v.loggedIn && v.inventory.isEmpty() && v.stores.isEmpty())
		{
			crest.update("NOMAD", "-", "", -1, "Log in to open your pack", Theme.TEXT_MUTED, Theme.GOLD_DIM);
			return;
		}
		int free = 28 - v.invUsed;
		String status;
		String shortStatus = null;
		Color color;
		View.Peril pile = null;
		View.Peril bank = null;
		View.Peril floor = null;
		for (View.Peril p : v.perils)
		{
			if (p.kind == Kind.FLOOR && (floor == null || p.until < floor.until))
			{
				floor = p;
			}
			if (p.kind == Kind.DEATHPILE && (pile == null || p.ticksLeft < pile.ticksLeft))
			{
				pile = p;
			}
			if (p.kind == Kind.DEATHBANK)
			{
				bank = p;
			}
		}
		if (floor != null)
		{
			long left = floor.until - v.now;
			status = "On the floor: " + Format.clock(left) + " left · " + Format.coins(floor.worth);
			shortStatus = "Dropped: " + Format.clock(left) + " left";
			color = left <= 30_000 ? Theme.BLOOD : Theme.EMBER;
		}
		else if (pile != null)
		{
			status = "Deathpile: " + Format.ticks(pile.ticksLeft) + " left · " + Format.coins(pile.worth);
			shortStatus = "Deathpile: " + Format.ticks(pile.ticksLeft) + " left";
			color = pile.ticksLeft <= 1000 ? Theme.BLOOD : Theme.EMBER;
		}
		else if (bank != null)
		{
			status = bank.title + (bank.exact ? " · " + Format.coins(bank.worth) : "");
			shortStatus = "Deathbank at risk";
			color = Theme.EMBER;
		}
		else if (v.fetch != null && !v.fetch.stops.isEmpty())
		{
			status = "Next: " + v.fetch.stops.get(0).name + " for " + v.fetch.name;
			shortStatus = "Next: " + v.fetch.stops.get(0).name;
			color = Theme.TEAL;
		}
		else if (v.fetch != null && v.fetch.ready == v.fetch.total)
		{
			status = v.fetch.name + ": packed and ready";
			color = Theme.GREEN;
		}
		else if (v.route != null && v.route.following && v.route.current >= 0)
		{
			status = "Route: step " + (v.route.done + 1) + " of " + v.route.total;
			color = Theme.GOLD;
		}
		else
		{
			status = "Nothing at risk · " + Format.coins(v.carriedWorth) + " carried";
			shortStatus = "Nothing at risk";
			color = Theme.TEAL;
		}
		crest.update(heading, String.valueOf(free), free == 1 ? "slot free" : "slots free", free / 28.0, status, shortStatus, color,
			free <= 2 ? Theme.EMBER : Theme.GOLD);
	}

	static String account(int varbit)
	{
		switch (varbit)
		{
			case 2:
				return "Ultimate ironman";
			case 1:
				return "Ironman";
			case 3:
				return "Hardcore ironman";
			case 4:
			case 5:
			case 6:
				return "Group ironman";
			case 0:
				return "Main account";
			default:
				return "Nomad";
		}
	}

	// ---- pack ----

	private JComponent pack()
	{
		StackPanel p = new StackPanel(6, 8);
		View v = view;
		if (!v.loggedIn && v.inventory.isEmpty())
		{
			p.add(note("Log in and Nomad starts keeping your pack: what you carry, what you keep, and what you could lose."));
			return p;
		}
		if (v.account >= 0 && v.account != 2)
		{
			p.add(note("Nomad is built for ultimate ironmen. It works on any account, but deaths and deathbanks follow ultimate ironman rules."));
		}
		if (!v.perils.isEmpty())
		{
			p.add(new SectionHeader("At risk", String.valueOf(v.perils.size())));
			for (View.Peril r : v.perils)
			{
				long left = r.until - v.now;
				String figure = r.kind == Kind.FLOOR ? Format.clock(left) : r.kind == Kind.DEATHPILE ? Format.ticks(r.ticksLeft) : r.exact ? Format.coins(r.worth) : "?";
				Color c = r.kind == Kind.FLOOR ? left <= 30_000 ? Theme.BLOOD : Theme.EMBER
					: r.kind == Kind.DEATHPILE ? r.ticksLeft <= 1000 ? Theme.BLOOD : Theme.EMBER : r.kind == Kind.DEATHBANK ? Theme.EMBER : Theme.GOLD;
				String noteText = r.kind == Kind.DEATHPILE || r.kind == Kind.FLOOR ? Format.coins(r.worth) + " · " + r.note
					: r.exact ? r.count + " items · " + r.note : "Contents unknown · " + r.note;
				p.add(new Row(-1, 0, null, r.title, figure, c, noteText, c));
			}
		}
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.coins(v.carriedWorth), "Carried", (28 - v.invUsed) + (28 - v.invUsed == 1 ? " slot free" : " slots free"), Theme.GOLD));
		tiles.add(new StatTile(Format.coins(v.dropNow), "Dying now", v.keepCount == 0 ? "keeps nothing" : "keeps " + Format.coins(v.keepNow), v.dropNow > 0 ? Theme.EMBER : Theme.TEAL));
		p.add(tiles);
		if (!v.kept.isEmpty())
		{
			p.add(new SectionHeader("Kept if you die", v.keepCount == 1 ? "1 item" : v.keepCount + " items"));
			p.add(grid(v.kept, Theme.alpha(Theme.TEAL, 140)));
		}

		p.add(new SectionHeader("Inventory", v.invUsed + " / 28"));
		p.add(grid(v.inventory, null));
		if (!v.worn.isEmpty())
		{
			p.add(new SectionHeader("Worn", String.valueOf(v.worn.size())));
			p.add(grid(v.worn, null));
		}
		if (!v.pouch.isEmpty())
		{
			p.add(new SectionHeader("Rune pouch", String.valueOf(v.pouch.size())));
			p.add(grid(v.pouch, null));
		}
		for (View.Vessel vessel : v.vessels)
		{
			p.add(new SectionHeader(vessel.name, vessel.unchecked ? "unchecked" : String.valueOf(vessel.items.size())));
			if (vessel.unchecked)
			{
				p.add(note("Check your " + vessel.name.toLowerCase() + " once so Nomad knows what is inside."));
			}
			else
			{
				p.add(grid(vessel.items, null));
			}
		}
		p.add(new SectionHeader("Looting bag", v.bagKnown ? v.bagUsed + " / 28" : "unchecked"));
		if (!v.bagKnown)
		{
			p.add(note("Check or open your looting bag once so Nomad can count it."));
		}
		else if (v.bag.isEmpty())
		{
			p.add(foot("Empty, seen " + Format.ago(v.now - v.bagSeen)));
		}
		else
		{
			p.add(grid(v.bag, Theme.alpha(Theme.EMBER, 120)));
			p.add(foot("Opens only in the Wilderness or on death · seen " + Format.ago(v.now - v.bagSeen)));
		}

		if (!v.idle.isEmpty())
		{
			p.add(new SectionHeader("Dead weight", v.idleSlots + " slots"));
			for (View.IdleLine i : v.idle)
			{
				String where = i.home != null ? "Belongs in the STASH at " + i.home : "Untouched for " + Format.duration(i.idleMs) + " of play";
				p.add(new Row(i.item.id, i.item.qty, icons, i.item.name, i.slots + (i.slots == 1 ? " slot" : " slots"), Theme.GOLD_DIM, where, null));
			}
			p.add(foot("Carried " + Format.duration(v.idleAfter) + " of play or more without being used."));
		}
		if (!v.notes.isEmpty())
		{
			p.add(new SectionHeader("Noting", String.valueOf(v.notes.size())));
			for (View.NoteLine n : v.notes)
			{
				String figure = n.unnote ? "Unnote" : "Frees " + n.frees;
				String fee = n.fee > 0 ? " · " + n.fee + " gp each" : n.fee == 0 ? " · free" : "";
				String where = n.who + ", " + n.where + fee + (n.wilderness ? " · Wilderness" : "");
				p.add(new Row(n.item.id, n.item.qty, icons, n.item.name, figure, n.unnote ? Theme.TEAL : Theme.GREEN, where,
					n.wilderness ? Theme.alpha(Theme.BLOOD, 160) : null));
			}
		}
		return p;
	}

	private JComponent grid(List<View.ItemLine> items, Color rim)
	{
		JPanel holder = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		holder.setOpaque(false);
		if (items.isEmpty())
		{
			holder.add(Ui.label("Nothing", Theme.small(), Theme.TEXT_FAINT));
			return holder;
		}
		holder.add(new ItemGrid(items, icons, rim, 5));
		return holder;
	}

	// ---- stores ----

	private JComponent stores()
	{
		StackPanel p = new StackPanel(6, 8);
		View v = view;
		if (v.stores.isEmpty())
		{
			p.add(note("Nomad remembers every place you keep things. Deposit into a STASH unit, open a costume room piece or the seed vault, and it shows here. Deathpiles, deathbanks, dropped items, the tool leprechaun, the Blast Furnace, fossil storage and the coffers appear on their own."));
			lost(p, v);
			return p;
		}
		p.add(new StatTile(Format.coins(v.keptWorth), "Kept away", v.stores.size() + " places remembered", Theme.GOLD));
		Kind last = null;
		for (View.StoreView s : v.stores)
		{
			if (s.kind != last)
			{
				int count = 0;
				for (View.StoreView o : v.stores)
				{
					count += o.kind == s.kind ? 1 : 0;
				}
				p.add(new SectionHeader(s.kind == Kind.STASH ? "STASH units" : s.kind.getLabel(), String.valueOf(count)));
				last = s.kind;
			}
			p.add(store(s));
		}
		lost(p, v);
		return p;
	}

	/** Gone for good: deathpiles that ran out, wiped deathbanks, vanished floors, newest first. */
	private void lost(StackPanel p, View v)
	{
		if (v.losses.isEmpty())
		{
			return;
		}
		p.add(new SectionHeader("Lost for good", Format.coins(v.lostWorth)));
		for (View.LossLine l : v.losses)
		{
			p.add(new Row(l.item, 0, icons, l.cause, Format.coins(l.worth), Theme.BLOOD,
				Format.ago(v.now - l.at) + " · " + l.what, null));
		}
	}

	private JComponent store(View.StoreView s)
	{
		boolean isOpen = open.contains(s.key);
		Card card = new Card(new BorderLayout());
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		Color c = s.kind == Kind.DEATHPILE || s.kind == Kind.DEATHBANK || s.kind == Kind.FLOOR ? Theme.EMBER : null;
		if (c != null)
		{
			card.accent(c);
		}
		String figure = s.kind == Kind.FLOOR ? Format.clock(s.until - view.now) : s.kind == Kind.DEATHPILE ? Format.ticks(s.ticksLeft)
			: !s.exact ? "?" : s.worth > 0 ? Format.coins(s.worth) : "";
		String sub = (s.exact ? s.items.size() + (s.items.size() == 1 ? " item" : " items") : "Estimated from your death")
			+ (s.distance >= 0 ? " · " + s.distance + " tiles" : "")
			+ (s.live ? " · read live" : s.seen > 0 ? " · " + Format.ago(view.now - s.seen) : "")
			+ (s.kind == Kind.DEATHBANK && Death.claim(s.name) != null ? " · " + Death.claim(s.name) : "");
		card.add(new Row.Plain(s.name, figure, c == null ? Theme.GOLD : c, sub), BorderLayout.NORTH);
		StackPanel in = new StackPanel(4, 0);
		in.setBorder(new EmptyBorder(6, 0, 0, 0));
		if (!s.items.isEmpty())
		{
			in.add(grid(s.items, null));
		}
		card.add(in, BorderLayout.CENTER);
		if (isOpen)
		{
			in.add(foot(s.kind.getSafety()));
			JPanel holder = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			holder.setOpaque(false);
			holder.add(new CodexButton("Forget this place", false, () -> actions.forgetStore(s.key)));
			in.add(holder);
		}
		card.highlighted(isOpen);
		card.onClick(() ->
		{
			if (!open.remove(s.key))
			{
				open.add(s.key);
			}
			rebuild();
		});
		return card;
	}

	// ---- find ----

	/** One item and every place it is. */
	private static final class Hit
	{
		final View.ItemLine item;
		long total;
		final List<String> where = new ArrayList<>();
		final List<Long> qty = new ArrayList<>();
		boolean risky;

		Hit(View.ItemLine item)
		{
			this.item = item;
		}
	}

	private JComponent found()
	{
		StackPanel p = new StackPanel(6, 8);
		View v = view;
		String q = find.getText().trim().toLowerCase(Locale.ENGLISH);
		Map<String, Hit> hits = new LinkedHashMap<>();
		look(hits, q, v.inventory, "Inventory", false);
		look(hits, q, v.worn, "Worn", false);
		look(hits, q, v.bag, "Looting bag", true);
		look(hits, q, v.pouch, "Rune pouch", false);
		for (View.Vessel vessel : v.vessels)
		{
			look(hits, q, vessel.items, vessel.name, false);
		}
		for (View.StoreView s : v.stores)
		{
			String place = s.kind == Kind.FLOOR && s.world == com.codex.nomad.core.Nomad.RAID ? "Chambers of Xeric floor"
				: s.kind == Kind.FLOOR ? "Floor, world " + s.world + " (" + Format.clock(s.until - v.now) + ")"
				: s.kind == Kind.DEATHPILE ? "Deathpile (" + Format.ticks(s.ticksLeft) + ")"
				: s.kind == Kind.STASH ? "STASH, " + s.name
				: s.kind == Kind.DEATHBANK ? "Deathbank, " + s.name : s.name;
			look(hits, q, s.items, place + (s.distance >= 0 ? ", " + s.distance + " tiles" : ""), s.kind.perilous());
		}
		p.add(new SectionHeader("Found", String.valueOf(hits.size())));
		if (hits.isEmpty())
		{
			p.add(note("Nothing you carry or keep is called that. Nomad only knows the places you have opened or used since it was installed."));
			return p;
		}
		for (Hit h : hits.values())
		{
			List<String> where = new ArrayList<>();
			for (int i = 0; i < h.where.size(); i++)
			{
				where.add(h.where.size() > 1 && h.qty.get(i) > 1 ? h.where.get(i) + " " + Format.whole(h.qty.get(i)) : h.where.get(i));
			}
			p.add(new Row(h.item.id, h.total, icons, h.item.name, Format.whole(h.total), h.risky ? Theme.EMBER : Theme.GOLD,
				String.join(" · ", where), h.risky ? Theme.alpha(Theme.EMBER, 120) : null));
		}
		p.add(foot("Clear the search to go back."));
		return p;
	}

	private static void look(Map<String, Hit> hits, String q, List<View.ItemLine> items, String place, boolean risky)
	{
		for (View.ItemLine l : items)
		{
			if (l.name == null || !l.name.toLowerCase(Locale.ENGLISH).contains(q))
			{
				continue;
			}
			Hit h = hits.computeIfAbsent(l.name, k -> new Hit(l));
			h.total += l.qty;
			h.where.add(place);
			h.qty.add(l.qty);
			h.risky |= risky;
		}
	}

	// ---- trips ----

	private void saveTrip()
	{
		String name = tripName.getText().trim();
		if (!name.isEmpty())
		{
			actions.saveTrip(name);
			tripName.setText("");
		}
	}

	private JComponent trips()
	{
		StackPanel p = new StackPanel(6, 8);
		View v = view;
		p.add(new SectionHeader("Save a packing list"));
		JPanel form = new JPanel(new BorderLayout(6, 0));
		form.setOpaque(false);
		form.add(tripName, BorderLayout.CENTER);
		form.add(new CodexButton("Save", true, this::saveTrip), BorderLayout.EAST);
		p.add(form);
		p.add(foot("Gear up once for a trip and save it: Nomad remembers what you wore and carried."));

		View.FetchView f = v.fetch;
		if (f != null)
		{
			boolean ready = f.ready == f.total;
			p.add(new SectionHeader(f.name, f.ready + " of " + f.total + " ready"));
			JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
			tiles.setOpaque(false);
			tiles.add(new StatTile(f.ready + "/" + f.total, "Packed", ready ? "Ready to go" : f.missing + " missing", ready ? Theme.GREEN : Theme.GOLD));
			tiles.add(new StatTile(f.slots + "/28", "Slots", f.slots <= 28 ? "Fits" : "Too much to carry", f.slots <= 28 ? Theme.TEAL : Theme.BLOOD));
			p.add(tiles);
			if (!f.stops.isEmpty())
			{
				p.add(new SectionHeader("Stops", String.valueOf(f.stops.size())));
				int n = 1;
				for (View.StopView s : f.stops)
				{
					Color c = s.kind == Kind.DEATHPILE ? Theme.EMBER : n == 1 ? Theme.TEAL : Theme.GOLD_DIM;
					List<String> take = new ArrayList<>();
					for (View.ItemLine l : s.take)
					{
						take.add(l.qty > 1 ? Format.amount(l.qty) + " " + l.name : l.name);
					}
					Card card = new Card(new BorderLayout());
					card.setBorder(new EmptyBorder(6, 8, 6, 8));
					card.accent(c);
					card.highlighted(n == 1);
					card.add(new Row.Plain(n + ". " + s.name, s.distance >= 0 ? s.distance + " tiles" : s.kind.getLabel(), c, String.join(", ", take)), BorderLayout.NORTH);
					p.add(card);
					n++;
				}
			}
			p.add(new SectionHeader("The list"));
			for (View.FetchLine l : f.lines)
			{
				boolean ok = l.have >= l.want.qty;
				String figure = Format.amount(l.have) + "/" + Format.amount(l.want.qty);
				String where = ok ? (l.worn ? "Worn" : "Carried") : l.from != null ? "In " + l.from
					: l.bagged > 0 ? "In your looting bag" : "Not anywhere Nomad knows";
				Color c = ok ? Theme.GREEN : l.missing > 0 && l.bagged == 0 ? Theme.BLOOD : Theme.GOLD;
				p.add(new Row(l.want.id, l.want.qty, icons, l.want.name, figure, c, where, null));
			}
			if (!f.extra.isEmpty())
			{
				p.add(new SectionHeader("Not on the list", String.valueOf(f.extra.size())));
				p.add(grid(f.extra, Theme.alpha(Theme.GOLD_DIM, 160)));
				p.add(foot("Carried but not needed: leave these somewhere before you go."));
			}
		}
		if (!v.trips.isEmpty())
		{
			p.add(new SectionHeader("Packing lists", String.valueOf(v.trips.size())));
			for (String name : v.trips)
			{
				boolean active = name.equals(v.active);
				Card card = new Card(new BorderLayout());
				card.setBorder(new EmptyBorder(5, 8, 5, 8));
				card.add(new Row.Plain(name, active ? "Fetching" : "", Theme.TEAL, null), BorderLayout.CENTER);
				if (active)
				{
					card.accent(Theme.TEAL).highlighted(true);
					card.add(new CodexButton("Forget", false, () -> actions.forgetTrip(name)), BorderLayout.EAST);
				}
				else
				{
					card.onClick(() -> actions.useTrip(name));
				}
				p.add(card);
			}
		}
		return p;
	}

	// ---- route ----

	private JComponent route()
	{
		StackPanel p = new StackPanel(6, 8);
		View.RouteView r = view.route;
		if (r == null || r.total == 0)
		{
			p.add(note("The route could not be read."));
			return p;
		}
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(r.done + "/" + r.total, "Steps done", r.current < 0 ? "Route finished" : "ticked or done", Theme.GOLD));
		tiles.add(new StatTile(Format.percent(r.done / (double) r.total), "Of the way", "to Prifddinas", Theme.TEAL));
		p.add(tiles);
		JPanel holder = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		holder.setOpaque(false);
		holder.add(new CodexButton(r.following ? "Stop following" : "Follow the route", !r.following, () -> actions.follow(!r.following)));
		p.add(holder);

		String currentSection = r.current >= 0 ? r.steps.get(r.current).section : null;
		for (int si = 0; si < r.sections.size(); si++)
		{
			String sec = r.sections.get(si);
			int[] prog = r.progress.get(si);
			boolean secOpen = sectionsOpen.contains(sec) || sec.equals(currentSection) && !sectionsOpen.contains("-" + sec);
			Card head = new Card(new BorderLayout());
			head.setBorder(new EmptyBorder(5, 8, 5, 8));
			boolean done = prog[0] == prog[1];
			head.add(new Row.Plain((si + 1) + ". " + sec, prog[0] + "/" + prog[1], done ? Theme.GREEN : sec.equals(currentSection) ? Theme.GOLD : Theme.TEXT_MUTED, null), BorderLayout.CENTER);
			head.highlighted(sec.equals(currentSection));
			head.onClick(() ->
			{
				if (sec.equals(currentSection))
				{
					if (!sectionsOpen.remove("-" + sec))
					{
						sectionsOpen.add("-" + sec);
					}
				}
				else if (!sectionsOpen.remove(sec))
				{
					sectionsOpen.add(sec);
				}
				rebuild();
			});
			p.add(head);
			if (!secOpen)
			{
				continue;
			}
			int shown = 0;
			for (View.StepView s : r.steps)
			{
				if (!s.section.equals(sec))
				{
					continue;
				}
				boolean isCurrent = s.index == r.current;
				boolean ahead = r.current >= 0 && s.index > r.current;
				if (sec.equals(currentSection) && !routeAll)
				{
					if (s.done && !isCurrent && s.index < r.current - 2)
					{
						continue;
					}
					if (ahead && shown >= AHEAD)
					{
						continue;
					}
					if (ahead)
					{
						shown++;
					}
				}
				p.add(new StepRow(s, isCurrent, () -> actions.tickStep(s.key, !s.done)));
			}
			if (sec.equals(currentSection))
			{
				JPanel more = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
				more.setOpaque(false);
				more.add(new CodexButton(routeAll ? "Show fewer steps" : "Show every step", false, () ->
				{
					routeAll = !routeAll;
					rebuild();
				}));
				p.add(more);
			}
		}
		p.add(foot("Steps paraphrased from the OSRS Wiki's Ultimate Ironman walkthrough to Prifddinas (CC BY-NC-SA 3.0)."));
		return p;
	}

	// ---- small parts ----

	private static JComponent note(String text)
	{
		Card card = new Card(new BorderLayout());
		card.add(Ui.wrapped(text, Theme.body(), Theme.TEXT_MUTED, WIDTH - 24), BorderLayout.CENTER);
		return card;
	}

	private static JComponent foot(String text)
	{
		return Ui.wrapped(text, Theme.small(), Theme.TEXT_FAINT, WIDTH);
	}
}

package com.codex.nomad.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.border.EmptyBorder;

/**
 * One painted row on a card: an item in its well (or none), a name, a figure on the right in its
 * colour, and a quieter line beneath.
 */
class Row extends Card
{
	static final int HEIGHT = 38;

	Row(int icon, long qty, ItemIcons icons, String name, String figure, Color figureColor, String note, Color accent)
	{
		super(new BorderLayout());
		setBorder(new EmptyBorder(3, 6, 3, 8));
		if (accent != null)
		{
			accent(accent);
		}
		add(new Body(icon, qty, icons, name, figure, figureColor, note), BorderLayout.CENTER);
		setToolTipText("<html><b>" + Ui.escape(name) + "</b>" + (figure == null ? "" : " " + Ui.escape(figure))
			+ (note == null ? "" : "<br>" + Ui.escape(note)) + "</html>");
	}

	private static final class Body extends Fitted
	{
		private final int icon;
		private final long qty;
		private final ItemIcons icons;
		private final String name;
		private final String figure;
		private final Color figureColor;
		private final String note;

		Body(int icon, long qty, ItemIcons icons, String name, String figure, Color figureColor, String note)
		{
			this.icon = icon;
			this.qty = qty;
			this.icons = icons;
			this.name = name;
			this.figure = figure;
			this.figureColor = figureColor;
			this.note = note;
		}

		@Override
		int heightFor(int width)
		{
			int h = lay(null, width, icon >= 0 ? Well.SIZE + 10 : 0, 14, 15);
			return icon >= 0 ? Math.max(Row.HEIGHT - 4, h) : h;
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int x = 0;
			if (icon >= 0)
			{
				BufferedImage img = icons == null ? null : icons.icon(icon, this::repaint);
				Well.paint(g, 0, 1, img, null);
				if (qty > 1)
				{
					g.setFont(Theme.small());
					Ui.shadowed(g, Format.stack(qty), 2, 10, Format.stackColor(qty));
				}
				x = Well.SIZE + 10;
			}
			lay(g, getWidth(), x, 14, 15);
			g.dispose();
		}

		private int lay(Graphics2D g, int w, int x, int top, int gap)
		{
			return Row.lay(this, g, w, x, top, gap, name, figure, figureColor, note);
		}
	}

	/**
	 * Paints a name with its figure and a quieter note beneath, both wrapping to the width, or
	 * with no graphics only measures them.
	 *
	 * @return the height used
	 */
	static int lay(JComponent c, Graphics2D g, int w, int x, int top, int gap, String name, String figure, Color figureColor, String note)
	{
		FontMetrics bold = c.getFontMetrics(Theme.title());
		FontMetrics body = c.getFontMetrics(Theme.body());
		FontMetrics small = c.getFontMetrics(Theme.small());
		int fw = figure == null ? 0 : bold.stringWidth(figure);
		List<String> names = Ui.wrap(name, body, w - x - fw - 6);
		List<String> notes = note == null ? Collections.emptyList() : Ui.wrap(note, small, w - x);
		int noteTop = top + (names.size() - 1) * 13 + gap;
		int bottom = notes.isEmpty() ? top + (names.size() - 1) * 13 + 4 : noteTop + (notes.size() - 1) * 11 + 4;
		if (g != null)
		{
			if (figure != null)
			{
				g.setFont(Theme.title());
				Ui.shadowed(g, figure, w - fw, top, figureColor);
			}
			g.setFont(Theme.body());
			for (int i = 0; i < names.size(); i++)
			{
				Ui.shadowed(g, names.get(i), x, top + i * 13, Theme.TEXT);
			}
			g.setFont(Theme.small());
			for (int i = 0; i < notes.size(); i++)
			{
				Ui.shadowed(g, notes.get(i), x, noteTop + i * 11, Theme.TEXT_MUTED);
			}
		}
		return bottom;
	}

	/** A title and figure with an optional quiet line, for use inside another card. */
	static final class Plain extends Fitted
	{
		private final String name;
		private final String figure;
		private final Color figureColor;
		private final String note;

		Plain(String name, String figure, Color figureColor, String note)
		{
			this.name = name;
			this.figure = figure == null || figure.isEmpty() ? null : figure;
			this.figureColor = figureColor;
			this.note = note == null || note.isEmpty() ? null : note;
			setToolTipText(this.note == null ? name : "<html><b>" + Ui.escape(name) + "</b><br>" + Ui.escape(this.note) + "</html>");
		}

		@Override
		int heightFor(int width)
		{
			return Row.lay(this, null, width, 0, 13, 14, name, figure, figureColor, note);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			Row.lay(this, g, getWidth(), 0, 13, 14, name, figure, figureColor, note);
			g.dispose();
		}
	}
}

package com.codex.nomad.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.nomad.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.nomad.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The Nomad mark: a gilt satchel on its strap, with a teal wayfinder's star on the flap. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);

		// The strap: a dark arc over the top.
		g.setStroke(new BasicStroke(Math.max(1f, 1.3f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		Path2D strap = new Path2D.Float();
		strap.moveTo(x + 3.4f * s, y + 6.6f * s);
		strap.curveTo(x + 3.4f * s, y + 0.8f * s, x + 12.6f * s, y + 0.8f * s, x + 12.6f * s, y + 6.6f * s);
		g.setColor(Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.3));
		g.draw(strap);

		// The body: a rounded gilt bag, lit from above.
		g.setStroke(new BasicStroke(stroke, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		RoundRectangle2D body = new RoundRectangle2D.Float(x + 1.6f * s, y + 5.6f * s, 12.8f * s, 9.4f * s, 3.2f * s, 3.2f * s);
		g.setPaint(new GradientPaint(x, y + 5 * s, Theme.GOLD, x, y + 15 * s, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.45f)));
		g.fill(body);
		g.setColor(Theme.INK_DEEP);
		g.draw(body);

		// The flap, a shade darker, curving down to a point at the clasp.
		Path2D flap = new Path2D.Float();
		flap.moveTo(x + 1.8f * s, y + 6.4f * s);
		flap.lineTo(x + 14.2f * s, y + 6.4f * s);
		flap.lineTo(x + 14.2f * s, y + 8.6f * s);
		flap.curveTo(x + 12.2f * s, y + 10.6f * s, x + 10.0f * s, y + 11.4f * s, x + 8.0f * s, y + 11.6f * s);
		flap.curveTo(x + 6.0f * s, y + 11.4f * s, x + 3.8f * s, y + 10.6f * s, x + 1.8f * s, y + 8.6f * s);
		flap.closePath();
		g.setPaint(new GradientPaint(x, y + 6 * s, Theme.mix(Theme.GOLD, Theme.GOLD_BRIGHT, 0.4f), x, y + 11 * s, Theme.GOLD_DIM));
		g.fill(flap);
		g.setColor(Theme.INK_DEEP);
		g.draw(flap);
		g.setColor(Theme.alpha(Color.WHITE, 110));
		g.drawLine(Math.round(x + 3.2f * s), Math.round(y + 7.0f * s), Math.round(x + 12.8f * s), Math.round(y + 7.0f * s));

		// The star on the clasp: four teal points with a soft glow.
		float cx = x + 8f * s;
		float cy = y + 10.4f * s;
		float r = 2.5f * s;
		float w = 0.6f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 70));
		g.fill(new Ellipse2D.Float(cx - r * 0.8f, cy - r * 0.8f, r * 1.6f, r * 1.6f));
		Path2D star = new Path2D.Float();
		star.moveTo(cx, cy - r);
		star.lineTo(cx + w, cy - w);
		star.lineTo(cx + r, cy);
		star.lineTo(cx + w, cy + w);
		star.lineTo(cx, cy + r);
		star.lineTo(cx - w, cy + w);
		star.lineTo(cx - r, cy);
		star.lineTo(cx - w, cy - w);
		star.closePath();
		g.setColor(Theme.mix(Theme.TEAL, Color.WHITE, 0.35));
		g.fill(star);
	}
}

package com.codex.nomad.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.nomad.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.swing.JComponent;

/** One bar split into coloured parts, each as wide as its share. */
public class Stacked extends JComponent
{
	private final double[] parts;
	private final Color[] colors;
	private final int height;

	public Stacked(List<Double> parts, List<Color> colors, int height)
	{
		this.parts = new double[parts.size()];
		for (int i = 0; i < parts.size(); i++)
		{
			this.parts[i] = parts.get(i);
		}
		this.colors = colors.toArray(new Color[0]);
		this.height = height;
		setOpaque(false);
		setPreferredSize(new Dimension(10, height + 2));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, parts, colors, 0, 1, getWidth(), height);
		g.dispose();
	}

	static void paint(Graphics2D g, double[] parts, Color[] colors, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x, y, w, h, h, h);
		g.setColor(Theme.INK_DEEP);
		g.fill(shape);
		double total = 0;
		for (double p : parts)
		{
			total += Math.max(0, p);
		}
		if (total <= 0)
		{
			return;
		}
		java.awt.Shape clip = g.getClip();
		g.clip(shape);
		double at = x;
		for (int i = 0; i < parts.length; i++)
		{
			double width = w * Math.max(0, parts[i]) / total;
			if (width <= 0)
			{
				continue;
			}
			g.setColor(colors[i]);
			g.fillRect((int) Math.round(at), y, (int) Math.ceil(width), h);
			at += width;
			if (at < x + w - 1)
			{
				g.setColor(Theme.INK_DEEP);
				g.drawLine((int) Math.round(at), y, (int) Math.round(at), y + h);
			}
		}
		g.setColor(Theme.alpha(Color.WHITE, 40));
		g.drawLine(x + h / 2, y, x + w - h / 2, y);
		g.setClip(clip);
	}
}

package com.codex.nomad.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.nomad.ui;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * One step of the route: a box to tick, the step in words, and for the step in hand its tips and
 * what the game checks. Steps the game has confirmed cannot be unticked.
 */
class StepRow extends Card
{
	private static final int BOX = 12;

	StepRow(View.StepView s, boolean current, Runnable toggle)
	{
		super(new BorderLayout(8, 0));
		setBorder(new EmptyBorder(current ? 7 : 4, 8, current ? 7 : 4, 8));
		if (current)
		{
			accent(Theme.GOLD).highlighted(true);
		}
		add(new Box(s.done, s.met || s.passed, current), BorderLayout.WEST);
		StackPanel text = new StackPanel(2, 0);
		Color color = s.done ? Theme.TEXT_FAINT : current ? Theme.TEXT : Theme.TEXT_MUTED;
		text.add(Ui.wrapped(s.text, current ? Theme.body() : Theme.small(), color, NomadPanel.WIDTH - 40));
		if (current)
		{
			for (String tip : s.tips)
			{
				text.add(Ui.wrapped(tip, Theme.small(), Theme.GOLD_DIM, NomadPanel.WIDTH - 40));
			}
		}
		if (s.optional && !s.done)
		{
			text.add(Ui.label("Optional", Theme.small(), Theme.TEXT_FAINT));
		}
		if (current && s.clicks != null)
		{
			text.add(Ui.wrapped(s.clicks, Theme.small(), Theme.GOLD_BRIGHT, NomadPanel.WIDTH - 40));
		}
		if (s.check != null && (current || !s.done))
		{
			text.add(Ui.wrapped(s.met ? "Done in game" : (current ? "Watching: " : "") + s.check, Theme.small(),
				s.met ? Theme.GREEN : Theme.TEAL, NomadPanel.WIDTH - 40));
		}
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.add(text, BorderLayout.NORTH);
		add(holder, BorderLayout.CENTER);
		if (s.met)
		{
			setToolTipText("The game says this is done");
		}
		else if (s.passed)
		{
			setToolTipText("Done: the game says you are past it");
		}
		else
		{
			onClick(toggle);
			setToolTipText(s.done ? "Click to untick" : "Nomad ticks this itself; click if you did it another way");
		}
	}

	private static final class Box extends JComponent
	{
		private final boolean done;
		private final boolean met;
		private final boolean current;

		Box(boolean done, boolean met, boolean current)
		{
			this.done = done;
			this.met = met;
			this.current = current;
			setOpaque(false);
			setPreferredSize(new Dimension(BOX + 2, BOX + 4));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			RoundRectangle2D box = new RoundRectangle2D.Float(1, 3, BOX, BOX, 4, 4);
			g.setColor(Theme.INK_DEEP);
			g.fill(box);
			g.setColor(done ? (met ? Theme.GREEN : Theme.TEAL) : current ? Theme.GOLD : Theme.STROKE);
			g.draw(box);
			if (done)
			{
				Path2D tick = new Path2D.Float();
				tick.moveTo(3.5f, 9f);
				tick.lineTo(6f, 11.5f);
				tick.lineTo(10.5f, 5.5f);
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.setColor(met ? Theme.GREEN : Theme.TEAL);
				g.draw(tick);
			}
			g.dispose();
		}
	}
}

package com.codex.nomad.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Provisioner keeps gold for the step in hand, teal for what is done and blood for what
 * your levels do not reach yet, so the chain reads at a glance.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	/**
	 * How long a supply lasts, as a colour: blood when it is out or will not last the trip,
	 * ember when only a few trips are left, gold when it is comfortable and green when plentiful.
	 */
	public static Color trips(int trips, int warn)
	{
		if (trips <= 0)
		{
			return BLOOD;
		}
		if (trips <= warn)
		{
			return EMBER;
		}
		if (trips >= warn * 8)
		{
			return GREEN;
		}
		return GOLD;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.nomad.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}

	/** A skill's name as the game writes it: "Herblore". */
	public static String skill(net.runelite.api.Skill skill)
	{
		return skill.getName();
	}

	/**
	 * Breaks text into rows no wider than the room, at spaces where it can and inside a word
	 * only when one word is wider than a whole row, so every letter shows.
	 */
	public static java.util.List<String> wrap(String text, java.awt.FontMetrics fm, int room)
	{
		java.util.List<String> rows = new java.util.ArrayList<>();
		if (text == null || text.isEmpty())
		{
			rows.add("");
			return rows;
		}
		room = Math.max(20, room);
		String row = "";
		for (String word : text.trim().split(" +"))
		{
			String next = row.isEmpty() ? word : row + " " + word;
			if (fm.stringWidth(next) <= room)
			{
				row = next;
				continue;
			}
			if (!row.isEmpty())
			{
				rows.add(row);
			}
			row = word;
			while (fm.stringWidth(row) > room && row.length() > 1)
			{
				int cut = row.length() - 1;
				while (cut > 1 && fm.stringWidth(row.substring(0, cut)) > room)
				{
					cut--;
				}
				rows.add(row.substring(0, cut));
				row = row.substring(cut);
			}
		}
		rows.add(row);
		return rows;
	}
}

package com.codex.nomad.ui;

import com.codex.nomad.core.Kind;
import java.util.Collections;
