		assertEquals(12_000L, (long) read("coffer:nmz").read(vars(b)).get(ItemID.COINS));
		assertEquals(Kind.COFFER, read("coffer:nmz").kind);
		assertEquals(read("bolt pouch"), Reads.touched(VarbitID.XBOWS_POUCH_NUM1, -1).get(0));
