	@Test
	public void essencePouchesFollowTheGamesOwnTypeOrder()
	{
		Map<Integer, Integer> b = new HashMap<>();
		b.put(VarbitID.GIANT_ESSENCE_POUCH, 12);
		b.put(VarbitID.GIANT_ESSENCE_POUCH_TYPE, 2);
